INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23490, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "票价", "is_correct": false, "explanation": "语义：“上班时间的票价”不成立，票价不是时间的属性，无法说很低。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是外观特征，不能用来描述上班时间的高低。"}, {"text": "知名度", "is_correct": false, "explanation": "搭配：“知名度”用于人或事物的名气，不能与“上班时间”搭配。"}, {"text": "利用效率", "is_correct": true, "explanation": "正确。“上班时间的利用效率很低”指上班时间没有被充分利用，与句意相符。"}], "explanations": {"票价": "语义：“上班时间的票价”不成立，票价不是时间的属性，无法说很低。", "颜色": "语义：“颜色”是外观特征，不能用来描述上班时间的高低。", "知名度": "搭配：“知名度”用于人或事物的名气，不能与“上班时间”搭配。", "利用效率": "正确。“上班时间的利用效率很低”指上班时间没有被充分利用，与句意相符。"}, "sentence_index": 6, "correct_answer": "利用效率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的利用效率不高，所以我们总是穿厚衣服。", "explanation": "这里应该用〈气温〉。利用效率指资源被用得是否高效，说天气的冷暖要用〈气温〉。"}, {"text": "他的利用效率很大，整个教室都听得见。", "explanation": "这里应该用〈音量〉。利用效率不指声音的大小，说声音大小要用〈音量〉。"}, {"text": "这个月的利用效率很贵，我们少用一点。", "explanation": "这里应该用〈电费〉。利用效率不表示价格，说费用高低要用〈电费〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d296638-cb17-4ff8-a734-32b70dfda79d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我们要学会规划时间，提高时间的一个利用效率。", "corrected_sentence": "周末我们要学会规划时间，提高时间的利用效率。", "error_description": "量词错误：“利用效率”是抽象名词，前面不能直接加个体量词“一个”，应去掉数量短语，说“时间的利用效率”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d296638-cb17-4ff8-a734-32b70dfda79d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个周末她的计划排得很满，时间的利用效率比以前多了。", "corrected_sentence": "这个周末她的计划排得很满，时间的利用效率比以前高了。", "error_description": "补语错误：“利用效率”的程度应说“高了”，不能说“多了”；“时间的利用效率比以前多了”不成立，正确说法是“时间的利用效率比以前高了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d296638-cb17-4ff8-a734-32b70dfda79d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
