INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23492, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西裂开或分散开，就像冰块碎掉一样。", "primary_collocate": null, "pronunciation": "wǎ jiě", "ipa": "wa˨˩˦ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "春天一到，河上的冰就瓦解了。", "target_word": "瓦解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "泥墙被大雨泡了一夜，慢慢瓦解了。", "target_word": "瓦解", "complexity_tier": "T3", "furigana": "wǎjiě", "sentence_source": "generated"}, {"text": "地震过后，那座老桥很快就瓦解成一堆碎石。", "target_word": "瓦解", "complexity_tier": "T3", "furigana": "wǎjiě", "sentence_source": "generated"}, {"text": "太阳一晒，冰块开始瓦解成小块。", "target_word": "瓦解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风吹了千年，大石头终于瓦解成沙。", "target_word": "瓦解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪人在阳光下一点点瓦解了。", "target_word": "瓦解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上的大石头在地震中瓦解了。", "target_word": "瓦解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水一泡，这块干泥巴就瓦解了。", "target_word": "瓦解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "积木塔一碰就瓦解了。", "target_word": "瓦解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座旧塔经不起风雨，一夜之间瓦解了。", "target_word": "瓦解", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "瓦解了", "label": "体标"}, {"form": "瓦解过", "label": "体标"}], "register": "书面", "sense_fingerprint": "瓦解：具体的东西（冰、墙、石头等）裂开、碎开或散开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dc1047-0180-45c4-a535-02dddfb4af73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23492, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凝固", "is_correct": false, "explanation": "语义：春天冰面消融，“凝固”是变硬，与句意的方向相反。"}, {"text": "增长", "is_correct": false, "explanation": "语义：春天的河冰应当变薄、裂开，不会“增长”。"}, {"text": "瓦解", "is_correct": true, "explanation": "正确：瓦解指东西裂开、碎开，春天河冰破裂，符合句意。"}, {"text": "发酵", "is_correct": false, "explanation": "搭配：“发酵”用于面团、酒等，不用于河上的冰。"}], "explanations": {"凝固": "语义：春天冰面消融，“凝固”是变硬，与句意的方向相反。", "增长": "语义：春天的河冰应当变薄、裂开，不会“增长”。", "瓦解": "正确：瓦解指东西裂开、碎开，春天河冰破裂，符合句意。", "发酵": "搭配：“发酵”用于面团、酒等，不用于河上的冰。"}, "sentence_index": 0, "correct_answer": "瓦解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太阳一晒，冰块开始瓦解成水。", "explanation": "这里应该用〈融化〉。瓦解指东西裂开或碎开，冰受热变成水要用融化。"}, {"text": "厨师把西瓜瓦解成两半。", "explanation": "这里应该用〈切开〉。瓦解指东西自行裂开或碎开，不用于人用刀把西瓜切开。"}, {"text": "湖水在寒冷中瓦解了。", "explanation": "这里应该用〈冻结〉。瓦解指东西裂开或碎开，湖水遇冷变硬要用冻结。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21c85038-5747-4c20-ac84-49a80cc56e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "融化", "is_correct": false, "explanation": "语义：大石头不会“融化”，地震中石块应是裂开、碎开。"}, {"text": "生长", "is_correct": false, "explanation": "语义：石头不会“生长”，地震的语境与之矛盾。"}, {"text": "复印", "is_correct": false, "explanation": "搭配：“复印”的对象是文件、材料，不能用于大石头。"}, {"text": "瓦解", "is_correct": true, "explanation": "正确：瓦解指东西在地震中裂开、碎开，符合句意。"}], "explanations": {"融化": "语义：大石头不会“融化”，地震中石块应是裂开、碎开。", "生长": "语义：石头不会“生长”，地震的语境与之矛盾。", "复印": "搭配：“复印”的对象是文件、材料，不能用于大石头。", "瓦解": "正确：瓦解指东西在地震中裂开、碎开，符合句意。"}, "sentence_index": 6, "correct_answer": "瓦解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人花了三年时间，终于把这座旧塔瓦解了。", "explanation": "这里应该用〈修复〉。瓦解指东西自行崩坏，不用于对旧建筑进行修缮。"}, {"text": "工人用白漆瓦解了墙壁。", "explanation": "这里应该用〈粉刷〉。瓦解指东西自行裂开或碎开，不用于给墙壁涂漆。"}, {"text": "他用绳子瓦解了那个包裹。", "explanation": "这里应该用〈捆绑〉。瓦解指东西裂开或碎开，不表示用绳子把包裹系紧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21c85038-5747-4c20-ac84-49a80cc56e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这堵老墙在风雨中瓦解的很快。", "corrected_sentence": "这堵老墙在风雨中瓦解得很快。", "error_description": "错误形式：瓦解的很快；正确形式：瓦解得很快。程度补语前应用“得”，不用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21c85038-5747-4c20-ac84-49a80cc56e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那座沙堡在海浪里瓦解得。", "corrected_sentence": "那座沙堡在海浪里瓦解了。", "error_description": "错误形式：瓦解得；正确形式：瓦解了。“得”不能接在动词后单独结束句子，表示完成应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21c85038-5747-4c20-ac84-49a80cc56e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
