INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23494, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "两点之间有多长。", "primary_collocate": null, "pronunciation": "jù lí", "ipa": "tɕy˥˩ li˧˥", "syllable_count": 2, "sentences": [{"text": "家到学校的距离是三公里。", "target_word": "距离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个城市的距离很远。", "target_word": "距离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请量一量桌子和墙之间的距离。", "target_word": "距离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步的距离越长，人越累。", "target_word": "距离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上一厘米代表十公里的距离。", "target_word": "距离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京到上海的距离大约一千多公里。", "target_word": "距离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他算出了两个点之间的距离。", "target_word": "距离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段距离走路要二十分钟。", "target_word": "距离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车跑了很长的距离。", "target_word": "距离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道月亮和地球的距离。", "target_word": "距离", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段距离", "label": "量词"}, {"form": "近距离", "label": "复合"}, {"form": "距離", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两点之间的长度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53331fef-4a2b-4af8-8ea1-ed5c509c92d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23494, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "距离", "is_correct": true, "explanation": "正确答案：距离，指两点之间有多长。"}, {"text": "举例", "is_correct": false, "explanation": "jǔ（第三声）与 jù（第四声）声调不同，后字 lì（第四声）与 lí（第二声）也不同，意思是举出例子。"}, {"text": "据理", "is_correct": false, "explanation": "lǐ（第三声）与 lí（第二声）声调不同，意思是依据道理。"}, {"text": "巨力", "is_correct": false, "explanation": "lì（第四声）与 lí（第二声）声调不同，意思是巨大的力量。"}, {"text": "聚力", "is_correct": false, "explanation": "lì（第四声）与 lí（第二声）声调不同，意思是聚集起来的力量。"}], "explanations": {"距离": "正确答案：距离，指两点之间有多长。", "举例": "jǔ（第三声）与 jù（第四声）声调不同，后字 lì（第四声）与 lí（第二声）也不同，意思是举出例子。", "据理": "lǐ（第三声）与 lí（第二声）声调不同，意思是依据道理。", "巨力": "lì（第四声）与 lí（第二声）声调不同，意思是巨大的力量。", "聚力": "lì（第四声）与 lí（第二声）声调不同，意思是聚集起来的力量。"}, "sentence_index": null, "correct_answer": "距离"}, "level_3": {"options": [{"text": "时间", "is_correct": false, "explanation": "语义：“时间”指时长，不用公里计量，不能说“家到学校的时间是三公里”。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”要说“每小时几公里”，不能直接说“速度是三公里”。"}, {"text": "距离", "is_correct": true, "explanation": "正确：“距离”指两点之间的长度，与“家到学校”及“三公里”搭配。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热程度，不能用公里计量。"}], "explanations": {"时间": "语义：“时间”指时长，不用公里计量，不能说“家到学校的时间是三公里”。", "速度": "搭配：“速度”要说“每小时几公里”，不能直接说“速度是三公里”。", "距离": "正确：“距离”指两点之间的长度，与“家到学校”及“三公里”搭配。", "温度": "语义：“温度”指冷热程度，不能用公里计量。"}, "sentence_index": 0, "correct_answer": "距离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个西瓜的距离是三公斤。", "explanation": "这里应该用〈重量〉。距离只指两点之间的长度，西瓜的轻重要说重量。"}, {"text": "他的距离比去年又长了两厘米。", "explanation": "这里应该用〈身高〉。距离指两点之间的长度，人的高矮要说身高。"}, {"text": "我们认识的距离已经三年了。", "explanation": "这里应该用〈时间〉。距离只用于空间，不能用来计算时间的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6006d7-9289-404a-bd33-5cf9c717080e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23494, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "距离", "is_correct": true, "explanation": "正确答案：距离，指两点之间有多长。"}, {"text": "巨利", "is_correct": false, "explanation": "lì（第四声）与 lí（第二声）声调不同，意思是巨额利润。"}, {"text": "拘礼", "is_correct": false, "explanation": "jū（第一声）与 jù（第四声）声调不同，lǐ（第三声）与 lí（第二声）也不同，意思是过分讲究礼节。"}, {"text": "巨粒", "is_correct": false, "explanation": "lì（第四声）与 lí（第二声）声调不同，意思是颗粒很大。"}], "explanations": {"距离": "正确答案：距离，指两点之间有多长。", "巨利": "lì（第四声）与 lí（第二声）声调不同，意思是巨额利润。", "拘礼": "jū（第一声）与 jù（第四声）声调不同，lǐ（第三声）与 lí（第二声）也不同，意思是过分讲究礼节。", "巨粒": "lì（第四声）与 lí（第二声）声调不同，意思是颗粒很大。"}, "sentence_index": null, "correct_answer": "距离"}, "level_3": {"options": [{"text": "面积", "is_correct": false, "explanation": "语义：“面积”指平面图形的大小，不能用来描述两点之间的关系。"}, {"text": "角度", "is_correct": false, "explanation": "搭配：“角度”要说“两条线或两个方向之间”，不说“两个点之间”。"}, {"text": "距离", "is_correct": true, "explanation": "正确：“距离”指两点之间的长度，符合句意。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指物体的轻重，与两点之间的长短无关。"}], "explanations": {"面积": "语义：“面积”指平面图形的大小，不能用来描述两点之间的关系。", "角度": "搭配：“角度”要说“两条线或两个方向之间”，不说“两个点之间”。", "距离": "正确：“距离”指两点之间的长度，符合句意。", "重量": "语义：“重量”指物体的轻重，与两点之间的长短无关。"}, "sentence_index": 6, "correct_answer": "距离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子的距离是三立方米。", "explanation": "这里应该用〈体积〉。距离只指两点之间的长度，不能描述箱子占据的空间。"}, {"text": "他的英语距离很高。", "explanation": "这里应该用〈水平〉。距离只表示长度，描述能力的高低要用水平。"}, {"text": "他的距离已经二十岁了。", "explanation": "这里应该用〈年龄〉。距离是空间上的长度，不能用来表示人的年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6006d7-9289-404a-bd33-5cf9c717080e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "从家到车站有一条距离，我们走过去。", "corrected_sentence": "从家到车站有一段距离，我们走过去。", "error_description": "量词错误：“距离”前面应该用量词“段”，说“一段距离”，不能用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6006d7-9289-404a-bd33-5cf9c717080e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小明和小红之内的距离不远。", "corrected_sentence": "小明和小红之间的距离不远。", "error_description": "方位词错误：两个人之间应说“之间”。“之内”表示在某个范围的内部，不用于两人之间，应说“之间的距离”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6006d7-9289-404a-bd33-5cf9c717080e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
