INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23496, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "火或草慢慢变大、变多，像爬山虎一样到处跑。", "primary_collocate": null, "pronunciation": "màn yán", "ipa": "man˥˩ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "大火蔓延到了旁边的树林。", "target_word": "蔓延", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爬山虎蔓延到了整面墙。", "target_word": "蔓延", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草长得很快，蔓延到路上来了。", "target_word": "蔓延", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山火顺着风向蔓延开来。", "target_word": "蔓延", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂草在院子里到处蔓延。", "target_word": "蔓延", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "藤蔓一年就蔓延到了屋顶。", "target_word": "蔓延", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火从厨房蔓延到了客厅。", "target_word": "蔓延", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，山上的火不再蔓延。", "target_word": "蔓延", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绿色的青苔蔓延到整块石头上。", "target_word": "蔓延", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里的草蔓延着，越来越多。", "target_word": "蔓延", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "蔓延着", "label": "体标"}, {"form": "蔓延了", "label": "体标"}, {"form": "蔓延开来", "label": "复合"}], "register": "中性", "sense_fingerprint": "火或草木一点点向四处扩展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53331fef-4a2b-4af8-8ea1-ed5c509c92d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23496, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "游", "is_correct": false, "explanation": "语义：“游”是在水中的动作，大火不会游泳，不能说“大火游到了树林”。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”指搬运物体或搬家，大火不能被搬。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要送的人、送的东西和接受者，大火不能作为送的施事。"}, {"text": "蔓延", "is_correct": true, "explanation": "正确：“蔓延”指火向四周扩展，与“大火”和“到了旁边的树林”搭配。"}], "explanations": {"游": "语义：“游”是在水中的动作，大火不会游泳，不能说“大火游到了树林”。", "搬": "语义：“搬”指搬运物体或搬家，大火不能被搬。", "送": "配价：“送”需要送的人、送的东西和接受者，大火不能作为送的施事。", "蔓延": "正确：“蔓延”指火向四周扩展，与“大火”和“到了旁边的树林”搭配。"}, "sentence_index": 0, "correct_answer": "蔓延"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车队缓缓蔓延到了山下。", "explanation": "这里应该用〈移动〉。蔓延只用于火、草木、疫病等向四周扩散的事物，有方向的行进要说移动。"}, {"text": "士兵蔓延到了山后。", "explanation": "这里应该用〈撤退〉。蔓延指向四周扩展，部队有组织地退回要说撤退。"}, {"text": "鸟群蔓延到了南方。", "explanation": "这里应该用〈迁移〉。蔓延指向四周扩散，鸟类有规律地远飞要说迁移。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6006d7-9289-404a-bd33-5cf9c717080e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23496, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挪", "is_correct": false, "explanation": "语义：“挪”指移动物体的位置，火不能被挪动。"}, {"text": "寄", "is_correct": false, "explanation": "配价：“寄”需要寄的东西和收件人，火不能作为寄出的对象。"}, {"text": "倒", "is_correct": false, "explanation": "搭配：“倒”多指液体倾倒，火不说“倒到了客厅”。"}, {"text": "蔓延", "is_correct": true, "explanation": "正确：“蔓延”指火向四周扩展，与“火从厨房”和“到了客厅”搭配。"}], "explanations": {"挪": "语义：“挪”指移动物体的位置，火不能被挪动。", "寄": "配价：“寄”需要寄的东西和收件人，火不能作为寄出的对象。", "倒": "搭配：“倒”多指液体倾倒，火不说“倒到了客厅”。", "蔓延": "正确：“蔓延”指火向四周扩展，与“火从厨房”和“到了客厅”搭配。"}, "sentence_index": 6, "correct_answer": "蔓延"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "垃圾蔓延在墙角。", "explanation": "这里应该用〈堆积〉。蔓延强调向四周连续扩展，物品聚在一处要说堆积。"}, {"text": "碎片蔓延在地上。", "explanation": "这里应该用〈散落〉。蔓延强调连续扩展，碎片分散掉落要说散落。"}, {"text": "气球蔓延在空中。", "explanation": "这里应该用〈漂浮〉。蔓延指扩散，气球在空中飘着要说漂浮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6006d7-9289-404a-bd33-5cf9c717080e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雾顺着山谷蔓延来开。", "corrected_sentence": "大雾顺着山谷蔓延开来。", "error_description": "补语语序错误：“蔓延开来”中“开”是结果补语，“来”是趋向补语，顺序不能颠倒，应说“蔓延开来”，不能说“蔓延来开”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6006d7-9289-404a-bd33-5cf9c717080e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "火很快蔓延了到阳台。", "corrected_sentence": "火很快蔓延到了阳台。", "error_description": "“了”位置错误：完成标记应放在“到”后，写作“蔓延到了阳台”；错误写成“蔓延了到阳台”，“了”不能放在“到”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6006d7-9289-404a-bd33-5cf9c717080e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
