INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23498, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d296638-cb17-4ff8-a734-32b70dfda79d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23498, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做到，比如我们说‘达成目标’就是完成了目标。", "primary_collocate": null, "pronunciation": "dá chéng", "ipa": "ta³⁵ ʈʂʰɤŋ³⁵", "syllable_count": 2, "sentences": [{"text": "他每天跑步，想达成减肥的目标。", "target_word": "达成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的任务我们达成了。", "target_word": "达成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要达成目标，就不能怕累。", "target_word": "达成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用三年时间达成了自己的心愿。", "target_word": "达成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队没有达成今年的目标。", "target_word": "达成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要坚持，你一定能达成这个目标。", "target_word": "达成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的学习目标已经达成了。", "target_word": "达成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他靠自己的努力达成了目标。", "target_word": "达成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想达成这个目标，需要两年时间。", "target_word": "达成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了达成存钱的目标，他不买新衣服。", "target_word": "达成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "达成了", "label": "完成体"}, {"form": "达成过", "label": "经历体"}], "register": "书面语", "sense_fingerprint": "做到并完成预定的目标", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f97476-a1c8-44d6-945d-bc65b062c339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "达成", "is_correct": true, "explanation": "正确。“达成”指做到预定目标，与“减肥的目标”相符。"}, {"text": "跑", "is_correct": false, "explanation": "配价：“跑”是不及物动词，不能带“目标”作宾语。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”只用于动物或婴幼儿，不能搭配“目标”。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”针对具体器物，“目标”不能被修理。"}], "explanations": {"达成": "正确。“达成”指做到预定目标，与“减肥的目标”相符。", "跑": "配价：“跑”是不及物动词，不能带“目标”作宾语。", "喂养": "搭配：“喂养”只用于动物或婴幼儿，不能搭配“目标”。", "修理": "语义：“修理”针对具体器物，“目标”不能被修理。"}, "sentence_index": 0, "correct_answer": "达成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次比赛达成了很多困难，但他没有放弃。", "explanation": "这里应该用〈经历〉。困难不是目标，“达成”只用于实现目标。"}, {"text": "他在学校达成了很多朋友。", "explanation": "这里应该用〈结交〉。“达成”的对象是目标，不能用于朋友。"}, {"text": "学校因为下雨达成了运动会。", "explanation": "这里应该用〈取消〉。“达成”表示完成某个目标，不能用于运动会这类活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d296638-cb17-4ff8-a734-32b70dfda79d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "达成", "is_correct": true, "explanation": "正确。“达成”指做到学习目标，与“已经……了”相符。"}, {"text": "包扎", "is_correct": false, "explanation": "搭配：“包扎”用于伤口，不能搭配“目标”。"}, {"text": "驯服", "is_correct": false, "explanation": "语义：“驯服”针对动物或烈性事物，“目标”不能被驯服。"}, {"text": "冲洗", "is_correct": false, "explanation": "搭配：“冲洗”用于物体表面，不能用于“目标”。"}], "explanations": {"达成": "正确。“达成”指做到学习目标，与“已经……了”相符。", "包扎": "搭配：“包扎”用于伤口，不能搭配“目标”。", "驯服": "语义：“驯服”针对动物或烈性事物，“目标”不能被驯服。", "冲洗": "搭配：“冲洗”用于物体表面，不能用于“目标”。"}, "sentence_index": 6, "correct_answer": "达成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他达成了学校的规定，每天按时上课。", "explanation": "这里应该用〈遵守〉。“达成”用于目标或协议，不能用于规定。"}, {"text": "他达成了自己的错误，并向老师道歉。", "explanation": "这里应该用〈承认〉。“达成”的对象是目标或协议，不能用于错误。"}, {"text": "他达成了房间的门，走了进去。", "explanation": "这里应该用〈打开〉。“达成”不能用于具体的物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d296638-cb17-4ff8-a734-32b70dfda79d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直努力，终于达成着目标。", "corrected_sentence": "他一直努力，终于达成了目标。", "error_description": "“达成”表示已完成的结果，不能加「着」表示进行。应说「终于达成了目标」，不能说「终于达成着目标」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d296638-cb17-4ff8-a734-32b70dfda79d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于达成了一条小目标。", "corrected_sentence": "他终于达成了一个小目标。", "error_description": "“目标”的量词应用「个」。「条」用于细长的事物，不能修饰目标。错误句「一条小目标」应改为「一个小目标」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d296638-cb17-4ff8-a734-32b70dfda79d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
