INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23504, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西放得比较松，不挤。", "primary_collocate": null, "pronunciation": "dī mì dù", "ipa": "ti˥ mi˥˩ tu˥˩", "syllable_count": 3, "sentences": [{"text": "这座城市的新区以低密度住宅为主。", "target_word": "低密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "果园采用低密度种植，树和树隔得很远。", "target_word": "低密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的货架采用低密度布局，看着很宽松。", "target_word": "低密度", "complexity_tier": "T3", "furigana": "dī mì dù", "sentence_source": "generated"}, {"text": "学校把教室里的桌椅改成低密度排列。", "target_word": "低密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情期间，餐厅采用低密度座位，客人坐得不挤。", "target_word": "低密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区的村子是低密度居住，房子之间离得很远。", "target_word": "低密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低密度布置的展厅里，每件展品周围都很空。", "target_word": "低密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼塘里养鱼不能太挤，要采用低密度养殖。", "target_word": "低密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢住在低密度的小区，楼与楼之间很空。", "target_word": "低密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园是低密度设计，游客不会觉得拥挤。", "target_word": "低密度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "人、物、建筑等布局稀疏宽松、不拥挤（如低密度种植、低密度住宅）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f97476-a1c8-44d6-945d-bc65b062c339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23504, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低密度", "is_correct": true, "explanation": "正确。低密度指住宅布局稀疏、不拥挤，符合新区以此类住宅为主的规划语境。"}, {"text": "古老", "is_correct": false, "explanation": "语义：“古老”与“新区”相矛盾，新区不会以古老的住宅为主。"}, {"text": "沙哑", "is_correct": false, "explanation": "搭配：“沙哑”形容声音，不能用来修饰住宅。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”一般形容物质的触感，不能用来描述住宅。"}], "explanations": {"低密度": "正确。低密度指住宅布局稀疏、不拥挤，符合新区以此类住宅为主的规划语境。", "古老": "语义：“古老”与“新区”相矛盾，新区不会以古老的住宅为主。", "沙哑": "搭配：“沙哑”形容声音，不能用来修饰住宅。", "柔软": "搭配：“柔软”一般形容物质的触感，不能用来描述住宅。"}, "sentence_index": 0, "correct_answer": "低密度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条合同的价格是低密度的，大家都觉得划算。", "explanation": "这里应该用〈便宜〉。价格的高低要说“便宜”或“贵”；“低密度”只说东西放得松、不挤，不能用于价格。"}, {"text": "这件外套的口袋是低密度的，东西放进去很挤。", "explanation": "这里应该用〈宽松〉。“低密度”指东西放得松，口袋宽松时才能这样说；它与“很挤”自相矛盾，不能用来形容口袋的容量。"}, {"text": "这次发言的时长是低密度的，大家都没听懂。", "explanation": "这里应该用〈短〉。时长的多少要说“长”或“短”；“低密度”只说东西放得松、不挤，不能用于时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d296638-cb17-4ff8-a734-32b70dfda79d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低密度", "is_correct": true, "explanation": "正确。低密度修饰“布置”，指展品之间空间稀疏，与“周围都很空”一致。"}, {"text": "紧凑", "is_correct": false, "explanation": "语义：“紧凑”表示空间挤满，与句中“周围都很空”相矛盾。"}, {"text": "拥挤", "is_correct": false, "explanation": "语义：“拥挤”表示空间狭窄、挤满，与句中“周围都很空”相矛盾。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”形容声音，不能用来修饰“布置”。"}], "explanations": {"低密度": "正确。低密度修饰“布置”，指展品之间空间稀疏，与“周围都很空”一致。", "紧凑": "语义：“紧凑”表示空间挤满，与句中“周围都很空”相矛盾。", "拥挤": "语义：“拥挤”表示空间狭窄、挤满，与句中“周围都很空”相矛盾。", "嘈杂": "搭配：“嘈杂”形容声音，不能用来修饰“布置”。"}, "sentence_index": 6, "correct_answer": "低密度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这笔钱是低密度的，够花一年。", "explanation": "这里应该用〈宽裕〉。钱款的多少要说“宽裕”或“拮据”，“低密度”只描述东西放得松，不用于钱。"}, {"text": "他的脾气是低密度的，大家都不敢惹他。", "explanation": "这里应该用〈温和〉或〈暴躁〉。性情不用“低密度”描述，它只说东西放得松、不挤。"}, {"text": "这个方案的预算是低密度的，大家都很满意。", "explanation": "这里应该用〈低〉。预算的高低要说“高”或“低”；“低密度”只说东西放得松、不挤，不能用于预算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d296638-cb17-4ff8-a734-32b70dfda79d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个展厅的布置是低密度地，观众走动很方便。", "corrected_sentence": "这个展厅的布置是低密度的，观众走动很方便。", "error_description": "错误：“低密度地”。“地”标记状语，而这里“低密度”修饰名词“布置”，应用“的”，不能用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d296638-cb17-4ff8-a734-32b70dfda79d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "展厅的很低密度布置让观众走动很方便。", "corrected_sentence": "展厅的低密度布置让观众走动很方便。", "error_description": "错误：“很低密度布置”。“低密度”作定语修饰“布置”时不能受“很”修饰，应说“的低密度布置”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d296638-cb17-4ff8-a734-32b70dfda79d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
