INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23506, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "实证就是能证明一件事是真的东西。", "primary_collocate": null, "pronunciation": "shí zhèng", "ipa": "ʂɻ̩³⁵ ʈʂɤŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "你说他去过那里，有实证吗？", "target_word": "实证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有实证，大家不会相信你。", "target_word": "实证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这段录像就是他没说谎的实证。", "target_word": "实证", "complexity_tier": "T3", "furigana": "zhè duàn lùxiàng jiù shì tā méi shuōhuǎng de shízhèng", "sentence_source": "generated"}, {"text": "这张照片就是最好的实证。", "target_word": "实证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我：你的看法有什么实证？", "target_word": "实证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿不出任何实证。", "target_word": "实证", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些数字是我们的实证。", "target_word": "实证", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想找一些实证给大家看。", "target_word": "实证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了实证，他才放心。", "target_word": "实证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些脚印是他来过的实证。", "target_word": "实证", "complexity_tier": "T3", "furigana": "zhèxiē jiǎoyìn shì tā láiguo de shízhèng", "sentence_source": "generated"}], "morphological_forms": [{"form": "實證", "label": "繁体"}, {"form": "实证研究", "label": "复合"}], "register": "中性", "sense_fingerprint": "能证明一件事是真的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9fe1e84-341e-4afc-b28f-a4b71a6d4ab1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23506, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实证", "is_correct": true, "explanation": "正确。实证指能证明一件事是真的东西。"}, {"text": "施政", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是施行政策。"}, {"text": "市政", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是城市的行政事务。"}, {"text": "石阵", "is_correct": false, "explanation": "zhèn 与 zhèng 只差韵尾（n 与 ng），意思是石头排成的阵势。"}], "explanations": {"实证": "正确。实证指能证明一件事是真的东西。", "施政": "shī（第一声）与 shí（第二声）声调不同，意思是施行政策。", "市政": "shì（第四声）与 shí（第二声）声调不同，意思是城市的行政事务。", "石阵": "zhèn 与 zhèng 只差韵尾（n 与 ng），意思是石头排成的阵势。"}, "sentence_index": null, "correct_answer": "实证"}, "level_3": {"options": [{"text": "实证", "is_correct": true, "explanation": "正确。“有实证吗”问的是有没有能证明的依据。"}, {"text": "运气", "is_correct": false, "explanation": "语义：“有运气吗”与“去过那里”的问题无关，问的不是能证明的依据。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是人的性情，无法证明他去过哪里。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是身体特征，与他是否去过某地无关，句意不通。"}], "explanations": {"实证": "正确。“有实证吗”问的是有没有能证明的依据。", "运气": "语义：“有运气吗”与“去过那里”的问题无关，问的不是能证明的依据。", "脾气": "语义：脾气是人的性情，无法证明他去过哪里。", "体重": "体貌：体重是身体特征，与他是否去过某地无关，句意不通。"}, "sentence_index": 0, "correct_answer": "实证"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他心里有很多实证，所以说不出话。", "explanation": "这里应该用〈感受〉。实证指能证明一件事是真的东西，不能用来指心里的感受。"}, {"text": "证人作了实证，承认那天在场。", "explanation": "这里应该用〈证词〉。“作证”后接的是证人的陈述，实证是观察或实验得来的材料，不能“作”。"}, {"text": "这张照片就是最好的一座实证。", "explanation": "这里应该用〈项〉。“座”用于山、桥、建筑等大型固定物，实证是抽象的证据，不能用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实证", "is_correct": true, "explanation": "正确。“这些数字是我们的实证”指数字能证明我们的观点。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：宠物是饲养的动物，数字不能是宠物。"}, {"text": "祖先", "is_correct": false, "explanation": "语义：祖先是已故的人，数字不能是我们的祖先。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，与这句书面论断的语域不合，数字也不是玩意儿。"}], "explanations": {"实证": "正确。“这些数字是我们的实证”指数字能证明我们的观点。", "宠物": "语义：宠物是饲养的动物，数字不能是宠物。", "祖先": "语义：祖先是已故的人，数字不能是我们的祖先。", "玩意儿": "语域：“玩意儿”是口语，与这句书面论断的语域不合，数字也不是玩意儿。"}, "sentence_index": 6, "correct_answer": "实证"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在那里弹了一段实证，然后离开了。", "explanation": "这里应该用〈留下〉。“弹”用于乐器，实证是证据，不能被弹。"}, {"text": "他在那里绣了一幅实证，然后离开了。", "explanation": "这里应该用〈留下〉。“绣”用于刺绣，实证不能被绣。"}, {"text": "他在那里穿上了一件实证，然后离开了。", "explanation": "这里应该用〈留下〉。“穿”用于衣物，实证不能被穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们找到过了实证，才相信他的话。", "corrected_sentence": "我们找到了实证，才相信他的话。", "error_description": "体标错误：“找到过了”同时用了“过”和“了”，两个体标不能并用；“找到”是已完成的动作，应只用“了”，正确为“找到了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于找了出实证，足以说服大家。", "corrected_sentence": "他终于找出了实证，足以说服大家。", "error_description": "补语错误：“找出”是动词加结果补语，“了”应放在“出”之后。错误为“找了出实证”，正确为“找出了实证”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
