INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23508, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情发生的次数。", "primary_collocate": null, "pronunciation": "pín cì", "ipa": "pʰin³⁵ tsʰɹ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "我喝咖啡的频次不高。", "target_word": "频次", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你看电影的频次是多少？", "target_word": "频次", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他迟到的频次太高了。", "target_word": "频次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路出事故的频次很低。", "target_word": "频次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请写下你每天刷牙的频次。", "target_word": "频次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公交车来的频次变少了。", "target_word": "频次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我们玩游戏的频次。", "target_word": "频次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们见面的频次越来越低。", "target_word": "频次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他打电话回家的频次是一周一次。", "target_word": "频次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃甜食的频次太高对牙不好。", "target_word": "频次", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "頻次", "label": "繁体"}, {"form": "出现频次", "label": "复合"}], "register": "通用", "sense_fingerprint": "事情发生的次数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9fe1e84-341e-4afc-b28f-a4b71a6d4ab1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23508, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "频次", "is_correct": true, "explanation": "正确：“频次”指喝咖啡的次数，与“不高”搭配，语义通顺。"}, {"text": "步数", "is_correct": false, "explanation": "语义：喝咖啡不计步数，“喝咖啡的步数”语义不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”只说人的身材，不能修饰“喝咖啡”这个行为。"}, {"text": "力气", "is_correct": false, "explanation": "语义：喝咖啡不以力气衡量，“喝咖啡的力气不高”与语境不符。"}], "explanations": {"频次": "正确：“频次”指喝咖啡的次数，与“不高”搭配，语义通顺。", "步数": "语义：喝咖啡不计步数，“喝咖啡的步数”语义不通。", "身高": "体貌：“身高”只说人的身材，不能修饰“喝咖啡”这个行为。", "力气": "语义：喝咖啡不以力气衡量，“喝咖啡的力气不高”与语境不符。"}, "sentence_index": 0, "correct_answer": "频次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "声波的频次是一千赫兹。", "explanation": "这里应该用〈频率〉。频次指次数，不用来表示“赫兹”这类周期性的速率。"}, {"text": "这个班级里男生与女生的频次是二比一。", "explanation": "这里应该用〈比例〉。频次指发生次数，不能表示两个数量之间的比例。"}, {"text": "这批产品的合格频次是百分之九十八。", "explanation": "这里应该用〈合格率〉。频次是次数，不能表示合格所占的比率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "频次", "is_correct": true, "explanation": "正确：“频次”指玩游戏的次数，与“老师问”的语境相符。"}, {"text": "工资", "is_correct": false, "explanation": "语义：玩游戏不产生工资，“玩游戏的工资”语义不通。"}, {"text": "鞋码", "is_correct": false, "explanation": "语义：玩游戏与鞋码无关，“玩游戏的鞋码”与语境不符。"}, {"text": "个头", "is_correct": false, "explanation": "体貌：“个头”只指人或物体的身材，不能用于“玩游戏”。"}], "explanations": {"频次": "正确：“频次”指玩游戏的次数，与“老师问”的语境相符。", "工资": "语义：玩游戏不产生工资，“玩游戏的工资”语义不通。", "鞋码": "语义：玩游戏与鞋码无关，“玩游戏的鞋码”与语境不符。", "个头": "体貌：“个头”只指人或物体的身材，不能用于“玩游戏”。"}, "sentence_index": 6, "correct_answer": "频次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕的频次是百分之三十。", "explanation": "这里应该用〈含量〉。频次指事件发生的次数，不能用来表示物质所占的分量。"}, {"text": "这顿饭的频次是三十分钟。", "explanation": "这里应该用〈时长〉。频次指次数，不能用来表示持续的时间。"}, {"text": "这次旅行的频次是五百块钱。", "explanation": "这里应该用〈费用〉。频次指事件发生的次数，不能用来表示花掉的钱数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家医院每天体检的一把频次很高。", "corrected_sentence": "这家医院每天体检的频次很高。", "error_description": "错误在于频次前多加了量词“一把”。“把”用于有柄的器具，不能修饰抽象的频次，应说“体检的频次很高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天吃甜食频次很高。", "corrected_sentence": "他每天吃甜食的频次很高。", "error_description": "错误在于漏掉了“的”。“吃甜食”是修饰“频次”的定语，中间要用“的”，应说“吃甜食的频次很高”，不说“吃甜食频次很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
