INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23510, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "骑车就是坐在车上用脚蹬着走。", "primary_collocate": null, "pronunciation": "qí xíng", "ipa": "tɕʰi˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他每天骑行十公里去公司。", "target_word": "骑行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山路很陡，骑行很累。", "target_word": "骑行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们沿着河边骑行了一个小时。", "target_word": "骑行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以后骑行要开灯。", "target_word": "骑行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她骑行到学校只要十分钟。", "target_word": "骑行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天不能骑行，路太滑了。", "target_word": "骑行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想骑行去看海。", "target_word": "骑行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们在公园里骑行，玩得很开心。", "target_word": "骑行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑行的时候别看手机。", "target_word": "骑行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们骑行到山顶，大家都累坏了。", "target_word": "骑行", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "骑行了", "label": "体标"}, {"form": "骑行过", "label": "体标"}, {"form": "騎行", "label": "繁体"}], "register": "中性", "sense_fingerprint": "坐在车上用脚蹬着前进的动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9fe1e84-341e-4afc-b28f-a4b71a6d4ab1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23510, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骑行", "is_correct": true, "explanation": "正确：“骑行”表示骑车去公司的方式，与“十公里”的距离相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳不是通勤方式，“每天游泳十公里去公司”语义不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌不能表示去公司的方式，“每天唱歌十公里去公司”语义不通。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：洗澡不能作去公司的方式，与“十公里”的语境冲突。"}], "explanations": {"骑行": "正确：“骑行”表示骑车去公司的方式，与“十公里”的距离相符。", "游泳": "语义：游泳不是通勤方式，“每天游泳十公里去公司”语义不通。", "唱歌": "语义：唱歌不能表示去公司的方式，“每天唱歌十公里去公司”语义不通。", "洗澡": "语义：洗澡不能作去公司的方式，与“十公里”的语境冲突。"}, "sentence_index": 0, "correct_answer": "骑行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他骑行汽车去郊外。", "explanation": "这里应该用〈驾驶〉。骑行指骑车，驾驶汽车要用“驾驶”，不能说“骑行”。"}, {"text": "我们骑行大巴去北京。", "explanation": "这里应该用〈乘坐〉。骑行指骑车，乘坐大巴要用“乘坐”，不能说“骑行”。"}, {"text": "孩子们在冰场上骑行。", "explanation": "这里应该用〈滑冰〉。骑行指骑车，在冰上运动要用“滑冰”，不能说“骑行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23510, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骑行", "is_correct": true, "explanation": "正确：“骑行”表示去看海的方式，与“我想”的句意相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉不能作为去看海的方式，语义不通。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞不能表示去看海的方式，与语境不符。"}, {"text": "乘坐", "is_correct": false, "explanation": "配价：“乘坐”须带宾语（如乘坐汽车），不能单独作去看海的方式。"}], "explanations": {"骑行": "正确：“骑行”表示去看海的方式，与“我想”的句意相符。", "睡觉": "语义：睡觉不能作为去看海的方式，语义不通。", "跳舞": "语义：跳舞不能表示去看海的方式，与语境不符。", "乘坐": "配价：“乘坐”须带宾语（如乘坐汽车），不能单独作去看海的方式。"}, "sentence_index": 6, "correct_answer": "骑行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我骑行出租车去机场。", "explanation": "这里应该用〈坐〉。骑行指骑车，乘坐出租车要用“坐”，不能说“骑行”。"}, {"text": "他骑行船去岛上。", "explanation": "这里应该用〈开〉。骑行指骑车，驾驶船只要用“开”，不能说“骑行”。"}, {"text": "她骑行地铁送我上学。", "explanation": "这里应该用〈乘〉。骑行指骑车，乘地铁要用“乘”，不能说“骑行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们骑行一起去公园。", "corrected_sentence": "孩子们骑行去公园。", "error_description": "语序错误：“一起”是状语，不能放在动词“骑行”之后。错误为“骑行一起去公园”，删去“一起”后为“骑行去公园”；若要保留“一起”，应放在动词前，说“一起骑行去公园”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他骑行地很慢。", "corrected_sentence": "他骑行得很慢。", "error_description": "错误在于“地”。动词后作补语要用“得”，不能用“地”，应说“骑行得很慢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
