INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23520, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能自己跑的车，比如汽车、公交车。", "primary_collocate": null, "pronunciation": "jī dòng chē", "ipa": "tɕi⁵⁵ tʊŋ⁵¹ ʈʂʰɤ⁵⁵", "syllable_count": 3, "sentences": [{"text": "汽车是一种机动车。", "target_word": "机动车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公交车也是机动车。", "target_word": "机动车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "自行车不是机动车。", "target_word": "机动车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "马路上有很多机动车。", "target_word": "机动车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "机动车不能进公园。", "target_word": "机动车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "过马路时要看机动车。", "target_word": "机动车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "机动车的声音很大。", "target_word": "机动车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家门口停着三辆机动车。", "target_word": "机动车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家没有机动车，上班坐地铁。", "target_word": "机动车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些机动车都在等红灯。", "target_word": "机动车", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "機動車", "label": "繁体"}, {"form": "辆", "label": "量词"}, {"form": "非机动车", "label": "复合"}], "register": "通用", "sense_fingerprint": "能自己跑的车，如汽车、公交车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9fe1e84-341e-4afc-b28f-a4b71a6d4ab1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23520, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机动车", "is_correct": true, "explanation": "正确。“汽车是一种机动车”指汽车属于能自行驱动的车辆。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不是汽车的类别，“汽车是一种水果”不成立。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物与汽车不属同一类，这个句子不成立。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“是一种”后接的类别须与汽车同属，“乐器”不能作为汽车的上位类。"}], "explanations": {"机动车": "正确。“汽车是一种机动车”指汽车属于能自行驱动的车辆。", "水果": "语义：水果不是汽车的类别，“汽车是一种水果”不成立。", "植物": "语义：植物与汽车不属同一类，这个句子不成立。", "乐器": "搭配：“是一种”后接的类别须与汽车同属，“乐器”不能作为汽车的上位类。"}, "sentence_index": 0, "correct_answer": "机动车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "马路上修剪了很多机动车。", "explanation": "这里应该用〈停〉或〈开〉。“修剪”用于树木、头发，机动车不能被修剪。"}, {"text": "马路上烤着很多机动车。", "explanation": "这里应该用〈停〉。“烤”用于食物，机动车不能被烤。"}, {"text": "马路上织着很多机动车。", "explanation": "这里应该用〈停〉。“织”用于布料、毛线，机动车不能被织。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23520, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机动车", "is_correct": true, "explanation": "正确。“机动车的声音”指发动机等动力装置发出的声音。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜不会发出声音，“蔬菜的声音很大”不成立。"}, {"text": "棉花", "is_correct": false, "explanation": "语义：棉花质地柔软，不会发出声音，与句意不合。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：“的声音”须是能发声的事物，月亮不能发出声音。"}], "explanations": {"机动车": "正确。“机动车的声音”指发动机等动力装置发出的声音。", "蔬菜": "语义：蔬菜不会发出声音，“蔬菜的声音很大”不成立。", "棉花": "语义：棉花质地柔软，不会发出声音，与句意不合。", "月亮": "搭配：“的声音”须是能发声的事物，月亮不能发出声音。"}, "sentence_index": 6, "correct_answer": "机动车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些机动车都靠人蹬，正在路口等红灯。", "explanation": "这里说的是靠人蹬的自行车，应该用〈自行车〉。机动车靠动力驱动，不靠人蹬。"}, {"text": "孩子们拉着这些机动车在雪地上玩，笑得很开心。", "explanation": "这里说的是雪橇，应该用〈雪橇〉。机动车能自己跑，雪橇要靠人拉。"}, {"text": "这些机动车都是靠马拉的，正在路口等红灯。", "explanation": "这里说的是马车，应该用〈马车〉。机动车靠发动机驱动，不靠马拉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "马路上停了着很多机动车。", "corrected_sentence": "马路上停着很多机动车。", "error_description": "体标错误：“停着”表示状态，“了”与“着”不能同时用在同一个动词上，应去掉“了”。错误为“停了着”，正确为“停着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "路边停着两张机动车，车主都不在。", "corrected_sentence": "路边停着两辆机动车，车主都不在。", "error_description": "量词错误：“张”用于纸张、桌子等平面的东西，机动车是车辆，计量用“辆”。错误为“两张机动车”，正确为“两辆机动车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23522, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "破坏", "is_correct": true, "explanation": "破坏与修复构成反义：修复是使损坏之物恢复，破坏是使之损坏。"}, {"text": "建造", "is_correct": false, "explanation": "与修复无反义关系：建造是从无到有地造，并非修复的相反。"}, {"text": "收集", "is_correct": false, "explanation": "与修复无反义关系：收集是把东西聚拢起来，与修复不相对。"}, {"text": "打扫", "is_correct": false, "explanation": "与修复无反义关系：打扫指清除脏物，不与修复相对。"}], "correct_answer": "破坏", "explanations": {"破坏": "破坏与修复构成反义：修复是使损坏之物恢复，破坏是使之损坏。", "建造": "与修复无反义关系：建造是从无到有地造，并非修复的相反。", "收集": "与修复无反义关系：收集是把东西聚拢起来，与修复不相对。", "打扫": "与修复无反义关系：打扫指清除脏物，不与修复相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39c147ad-02dc-40a2-9f0d-2cea2ca5d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23522, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "破坏", "is_correct": true, "explanation": "破坏与修复构成反义：修复是使损坏之物恢复，破坏是使之损坏。"}, {"text": "雕刻", "is_correct": false, "explanation": "与修复无反义关系：雕刻是用工具刻出形状，与修复不相对。"}, {"text": "浏览", "is_correct": false, "explanation": "与修复无反义关系：浏览是快速查看，与修复不相对。"}, {"text": "登山", "is_correct": false, "explanation": "与修复无反义关系：登山是爬山活动，与修复不构成相对的动作。"}], "correct_answer": "破坏", "explanations": {"破坏": "破坏与修复构成反义：修复是使损坏之物恢复，破坏是使之损坏。", "雕刻": "与修复无反义关系：雕刻是用工具刻出形状，与修复不相对。", "浏览": "与修复无反义关系：浏览是快速查看，与修复不相对。", "登山": "与修复无反义关系：登山是爬山活动，与修复不构成相对的动作。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39c147ad-02dc-40a2-9f0d-2cea2ca5d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23522, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把坏的东西修好。", "primary_collocate": null, "pronunciation": "xiū fù", "ipa": "ɕiou˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "爸爸正在修复我坏了的自行车。", "target_word": "修复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮我修复这个坏手机。", "target_word": "修复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水管坏了，工人下午来修复。", "target_word": "修复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把摔坏的椅子修复好了。", "target_word": "修复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑坏了，我想让朋友修复一下。", "target_word": "修复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视机坏了两天，今天才修复。", "target_word": "修复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居帮我修复了窗户上的玻璃。", "target_word": "修复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会修复旧钟表，很多人找他。", "target_word": "修复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用胶水修复了摔坏的杯子。", "target_word": "修复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门锁坏了，师傅一小时就修复了。", "target_word": "修复", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "修复了", "label": "体标"}, {"form": "修复过", "label": "体标"}, {"form": "修复好", "label": "复合"}], "register": "中性", "sense_fingerprint": "把日常用的坏东西修好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd15d400-ff1c-4929-b18e-ebdd0160fea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23522, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "修复", "is_correct": true, "explanation": "修复 xiū fù：把坏的东西修好。"}, {"text": "吸附", "is_correct": false, "explanation": "吸附 xī fù 第一音节没有 u 介音（韵母为 -i），与修复 xiū 的韵母 -iu 不同，意思是吸附。"}, {"text": "心腹", "is_correct": false, "explanation": "心腹 xīn fù 第一音节韵母为 -in，与修复 xiū 的 -iu 不同，意思是心腹、亲信。"}, {"text": "胸腹", "is_correct": false, "explanation": "胸腹 xiōng fù 第一音节韵母为 -iong，与修复 xiū 的 -iu 不同，意思是胸部和腹部。"}, {"text": "小腹", "is_correct": false, "explanation": "小腹 xiǎo fù 第一音节为第三声且韵母为 -ao，与修复 xiū（第一声）不同，意思是下腹部。"}], "explanations": {"修复": "修复 xiū fù：把坏的东西修好。", "吸附": "吸附 xī fù 第一音节没有 u 介音（韵母为 -i），与修复 xiū 的韵母 -iu 不同，意思是吸附。", "心腹": "心腹 xīn fù 第一音节韵母为 -in，与修复 xiū 的 -iu 不同，意思是心腹、亲信。", "胸腹": "胸腹 xiōng fù 第一音节韵母为 -iong，与修复 xiū 的 -iu 不同，意思是胸部和腹部。", "小腹": "小腹 xiǎo fù 第一音节为第三声且韵母为 -ao，与修复 xiū（第一声）不同，意思是下腹部。"}, "sentence_index": null, "correct_answer": "修复"}, "level_3": {"options": [{"text": "修复", "is_correct": true, "explanation": "正确：修复指把坏掉的自行车修好，与“我坏了的自行车”相符。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”的对象是植物，不能说种植自行车。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言或文字，不能说翻译自行车。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”指印行书刊，与自行车无关。"}], "explanations": {"修复": "正确：修复指把坏掉的自行车修好，与“我坏了的自行车”相符。", "种植": "搭配：“种植”的对象是植物，不能说种植自行车。", "翻译": "搭配：“翻译”的对象是语言或文字，不能说翻译自行车。", "出版": "语义：“出版”指印行书刊，与自行车无关。"}, "sentence_index": 0, "correct_answer": "修复"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把算错的数字修复了。", "explanation": "这里应该用〈修正〉。修复用于把坏掉的东西修好，错误的数字要说修正。"}, {"text": "这本词典每年都会修复一次。", "explanation": "这里应该用〈修订〉。修复用于把坏掉的东西修好，书籍的改版要说修订。"}, {"text": "他把这个笑话修复了三次。", "explanation": "这里应该用〈讲〉。修复指把坏掉的东西修好，笑话要说讲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39c147ad-02dc-40a2-9f0d-2cea2ca5d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23522, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "修复", "is_correct": true, "explanation": "修复 xiū fù：把坏的东西修好。"}, {"text": "西服", "is_correct": false, "explanation": "西服 xī fú 第一音节韵母为 -i，第二音节为第二声 fú，与修复 xiū fù 不同，意思是西装。"}, {"text": "心服", "is_correct": false, "explanation": "心服 xīn fú 第一音节韵母为 -in，第二音节为第二声 fú，与修复不同，意思是心里信服。"}, {"text": "吸附", "is_correct": false, "explanation": "吸附 xī fù 第一音节没有 u 介音（韵母为 -i），与修复 xiū 的韵母 -iu 不同，意思是吸附。"}], "explanations": {"修复": "修复 xiū fù：把坏的东西修好。", "西服": "西服 xī fú 第一音节韵母为 -i，第二音节为第二声 fú，与修复 xiū fù 不同，意思是西装。", "心服": "心服 xīn fú 第一音节韵母为 -in，第二音节为第二声 fú，与修复不同，意思是心里信服。", "吸附": "吸附 xī fù 第一音节没有 u 介音（韵母为 -i），与修复 xiū 的韵母 -iu 不同，意思是吸附。"}, "sentence_index": null, "correct_answer": "修复"}, "level_3": {"options": [{"text": "修复", "is_correct": true, "explanation": "正确：修复指把坏掉的玻璃修好，与“窗户上的玻璃”相符。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“烹饪”的对象是食物，不能烹饪玻璃。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”的对象是文件或图片，不能打印玻璃。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：“演奏”的对象是乐器或乐曲，不能演奏玻璃。"}], "explanations": {"修复": "正确：修复指把坏掉的玻璃修好，与“窗户上的玻璃”相符。", "烹饪": "搭配：“烹饪”的对象是食物，不能烹饪玻璃。", "打印": "搭配：“打印”的对象是文件或图片，不能打印玻璃。", "演奏": "搭配：“演奏”的对象是乐器或乐曲，不能演奏玻璃。"}, "sentence_index": 6, "correct_answer": "修复"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位作家每周都在修复自己的小说。", "explanation": "这里应该用〈修改〉。修复用于把坏掉的东西修好，小说的改动要说修改。"}, {"text": "工人正在修复新建的公路。", "explanation": "这里应该用〈修建〉。修复指把坏掉的东西修好，新公路要说修建。"}, {"text": "她每天凌晨在院子里修复花草，剪得很整齐。", "explanation": "这里应该用〈修剪〉。修复用于恢复损坏之物，把花草修整得整齐要说修剪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39c147ad-02dc-40a2-9f0d-2cea2ca5d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23522, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈已经把碎了的碗修复了好。", "corrected_sentence": "妈妈已经把碎了的碗修复好了。", "error_description": "错误在于补语“好”的位置：应说“修复好了”，“了”要放在补语之后，不能说“修复了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39c147ad-02dc-40a2-9f0d-2cea2ca5d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
