INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23526, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "许多动物、植物和它们生活的地方一起，组成了一个大家庭。", "primary_collocate": null, "pronunciation": "shēng tài xì tǒng", "ipa": "ʂəŋ˥ tʰai˥˩ ɕi˥˩ tʰʊŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "森林是一个很大的生态系统。", "target_word": "生态系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鱼、水草和河水组成了河里的生态系统。", "target_word": "生态系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变化会影响生态系统。", "target_word": "生态系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖里的生态系统很完整。", "target_word": "生态系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护生态系统，就是保护我们的家。", "target_word": "生态系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大海里的生态系统很丰富。", "target_word": "生态系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的生态系统需要大家一起保护。", "target_word": "生态系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在研究草原的生态系统。", "target_word": "生态系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们砍了太多树，生态系统变坏了。", "target_word": "生态系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了一个关于生态系统的故事。", "target_word": "生态系统", "complexity_tier": "T3", "furigana": "shēngtài xìtǒng", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个生态系统", "label": "量词"}, {"form": "森林生态系统", "label": "复合"}, {"form": "生態系統", "label": "繁体"}], "register": "书面", "sense_fingerprint": "生物与环境相互联系组成的整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c432fe6-4db2-4f87-8eb1-bd238a86f80d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23526, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生态系统", "is_correct": true, "explanation": "正确：“一个很大的生态系统”指由生物与环境组成的整体，与句意相符。"}, {"text": "动物", "is_correct": false, "explanation": "语义：森林是一片地方，不是一只动物，句中“一个很大的”后不能接“动物”。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：森林是自然环境，不是杯子，说“一个很大的杯子”与事实不符。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“水”是不可数名词，不能用“一个很大的”来修饰。"}], "explanations": {"生态系统": "正确：“一个很大的生态系统”指由生物与环境组成的整体，与句意相符。", "动物": "语义：森林是一片地方，不是一只动物，句中“一个很大的”后不能接“动物”。", "杯子": "语义：森林是自然环境，不是杯子，说“一个很大的杯子”与事实不符。", "水": "搭配：“水”是不可数名词，不能用“一个很大的”来修饰。"}, "sentence_index": 0, "correct_answer": "生态系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我大学学的专业是生态系统。", "explanation": "这里应该用〈生态学〉。生态系统指生物与环境组成的整体，是研究对象；学科名称是生态学。"}, {"text": "湖里有一只生态系统。", "explanation": "这里应该用〈个〉。“只”用于动物等个体，生态系统是抽象的整体，应说“一个生态系统”。"}, {"text": "我每天早上都用生态系统刷牙。", "explanation": "这里是把〈生态系统〉误当成〈工具〉的意思。生态系统指生物与环境组成的整体，不能用来刷牙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23526, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生态系统", "is_correct": true, "explanation": "正确：“这里的生态系统”需要大家共同保护，与句意相符。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是需要大家一起保护的对象，与句中的语境不合。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是供人喝的东西，不需要大家共同保护。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“保护”的对象通常是环境或生物，天气不能被保护。"}], "explanations": {"生态系统": "正确：“这里的生态系统”需要大家共同保护，与句意相符。", "作业": "语义：作业不是需要大家一起保护的对象，与句中的语境不合。", "饮料": "语义：饮料是供人喝的东西，不需要大家共同保护。", "天气": "搭配：“保护”的对象通常是环境或生物，天气不能被保护。"}, "sentence_index": 6, "correct_answer": "生态系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的生态系统很甜。", "explanation": "这里是把〈生态系统〉误当成〈食物〉的意思。生态系统是生物与环境组成的整体，不能用“甜”来形容。"}, {"text": "这个湖的生态系统很便宜。", "explanation": "这里是把〈生态系统〉误当成〈商品〉的意思。生态系统指生物与环境组成的整体，不是可以标价出售的东西，不能用“便宜”来形容。"}, {"text": "这家工厂的生态系统很严重。", "explanation": "这里应该用〈污染〉。“严重”形容污染或破坏的程度，不用来修饰生态系统本身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片草地是一只完整的生态系统。", "corrected_sentence": "这片草地是一个完整的生态系统。", "error_description": "错误形式：“一只完整的生态系统”；正确形式：“一个完整的生态系统”。生态系统是抽象的整体，量词应用“个”，“只”多用于动物等个体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要好好吃生态系统。", "corrected_sentence": "我们要好好保护生态系统。", "error_description": "搭配错误：“保护”才能与“生态系统”搭配，“吃”不能用于生态系统，应改为“保护”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
