INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23532, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为别人做事，比如帮人拿东西。", "primary_collocate": null, "pronunciation": "fú wù", "ipa": "fu˧˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "酒店工作人员为客人服务，帮他们拿行李。", "target_word": "服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在车站为老人服务，帮他们提包。", "target_word": "服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在机场为旅客服务，推着行李车跑来跑去。", "target_word": "服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末孩子们在超市里为顾客服务，帮人拿购物篮。", "target_word": "服务", "complexity_tier": "T3", "furigana": "zhōu mò hái zi men zài chāo shì lǐ wèi gù kè fú wù, bāng rén ná gòu wù lán.", "sentence_source": "generated"}, {"text": "她很高兴为朋友服务，帮他搬箱子。", "target_word": "服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者在门口为客人服务，帮大家拿雨伞。", "target_word": "服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天在饭店为客人服务，端菜倒茶。", "target_word": "服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你东西太多了，就让我为你服务，帮你拿一下吧。", "target_word": "服务", "complexity_tier": "T3", "furigana": "nǐ dōng xi tài duō le, jiù ràng wǒ wèi nǐ fú wù, bāng nǐ ná yí xià ba.", "sentence_source": "generated"}, {"text": "上车的时候，司机为老人服务，帮她拿包。", "target_word": "服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的向导为游客服务，帮他们背包。", "target_word": "服务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "服务了", "label": "体标"}, {"form": "服务过", "label": "体标"}, {"form": "服务员", "label": "复合"}], "register": "中性", "sense_fingerprint": "为具体的人做具体的事，如拿东西、提包", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd15d400-ff1c-4929-b18e-ebdd0160fea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23532, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "服务", "is_correct": true, "explanation": "服务指为客人做事、提供帮助，与后文「帮他们拿行李」的句意一致。"}, {"text": "批评", "is_correct": false, "explanation": "语义：批评客人与后文「帮他们拿行李」的意思相反，句意不通。"}, {"text": "生气", "is_correct": false, "explanation": "语义：为客人生气与后文「帮他们拿行李」的服务内容不符，句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉不能替客人拿行李，与句中的帮助动作不符。"}], "explanations": {"服务": "服务指为客人做事、提供帮助，与后文「帮他们拿行李」的句意一致。", "批评": "语义：批评客人与后文「帮他们拿行李」的意思相反，句意不通。", "生气": "语义：为客人生气与后文「帮他们拿行李」的服务内容不符，句意不通。", "睡觉": "语义：睡觉不能替客人拿行李，与句中的帮助动作不符。"}, "sentence_index": 0, "correct_answer": "服务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他小心地为行李箱服务，怕它被弄坏。", "explanation": "这里应该用〈照看〉。服务的对象一般是人或集体，行李箱是物，不能说「为行李箱服务」。"}, {"text": "妹妹穿着一件漂亮的服务去上学。", "explanation": "这里应该用〈衣服〉。衣服可以穿在身上，服务是为别人做事，不能用来指衣物。"}, {"text": "他一个人在家里服务，自己做饭洗衣。", "explanation": "这里应该用〈料理〉。服务是为别人做事，自己做饭洗衣是料理家务，不能说服务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39c147ad-02dc-40a2-9f0d-2cea2ca5d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23532, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "服务", "is_correct": true, "explanation": "服务指为客人做事，与「端菜倒茶」的工作内容一致，符合句意。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：失眠与后文「端菜倒茶」的工作内容不符，句意不通。"}, {"text": "发脾气", "is_correct": false, "explanation": "语义：对客人发脾气与后文「端菜倒茶」的服务内容相反，句意不通。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试不能替客人完成，「为客人考试」说不通。"}], "explanations": {"服务": "服务指为客人做事，与「端菜倒茶」的工作内容一致，符合句意。", "失眠": "语义：失眠与后文「端菜倒茶」的工作内容不符，句意不通。", "发脾气": "语义：对客人发脾气与后文「端菜倒茶」的服务内容相反，句意不通。", "考试": "语义：考试不能替客人完成，「为客人考试」说不通。"}, "sentence_index": 6, "correct_answer": "服务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很服务老师，从不顶嘴。", "explanation": "这里应该用〈服从〉。服从指听从，服务表示为人做事，不能用来表示听从。"}, {"text": "比赛输了，他心里很不服务。", "explanation": "这里应该用〈服气〉。服气指心里信服，服务不能表达这种心理。"}, {"text": "病人要按时服务，病才能好得快。", "explanation": "这里应该用〈服药〉。服药指按时吃药，服务不能用来指吃药。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39c147ad-02dc-40a2-9f0d-2cea2ca5d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在机场旅客服务，帮他们拿行李。", "corrected_sentence": "他在机场为旅客服务，帮他们拿行李。", "error_description": "「旅客服务」缺少介词「为」。应为「为旅客服务」，「服务」的对象要用「为……」引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39c147ad-02dc-40a2-9f0d-2cea2ca5d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她为朋友服务地很周到。", "corrected_sentence": "她为朋友服务得很周到。", "error_description": "补语前的「地」应为「得」。「服务」后接程度补语要用「动词+得+补语」，即「服务得很周到」；「地」用于修饰动词、形容词作状语，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39c147ad-02dc-40a2-9f0d-2cea2ca5d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
