INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23536, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc161bb1-80b8-483c-a3a8-eec2686a4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23536, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让车停下来不动。", "primary_collocate": null, "pronunciation": "tíng chē", "ipa": "tʰiŋ˧˥ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "前面有人过马路，司机要马上停车。", "target_word": "停车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车坏了，他只好在路中间停车。", "target_word": "停车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到红灯，请停车等一等。", "target_word": "停车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到家门口了，爸爸开始停车。", "target_word": "停车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“请在这里停车，我要下车。”", "target_word": "停车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机停车以后，乘客才下去。", "target_word": "停车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察对我们说：“请停车检查。”", "target_word": "停车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨了，我们到桥下停车。", "target_word": "停车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开了很久，他想停车喝点水。", "target_word": "停车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出租车在学校门口停车，学生们下了车。", "target_word": "停车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "停了车", "label": "体标"}, {"form": "停过车", "label": "体标"}, {"form": "停车场", "label": "复合"}], "register": "中性", "sense_fingerprint": "让行驶中的车停下来不动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '275ccb5f-1b55-4271-8c6c-799b66cfc0d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23536, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "停车", "is_correct": true, "explanation": "正确：有行人过马路时，司机要马上让车停下来，句意相合。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与行车安全无关，不符合遇到行人过马路的紧急情况。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“马上吃饭”不是司机遇到行人时的反应，搭配不成立。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：司机在行人过马路时睡觉会造成危险，与句意相反。"}], "explanations": {"停车": "正确：有行人过马路时，司机要马上让车停下来，句意相合。", "唱歌": "语义：唱歌与行车安全无关，不符合遇到行人过马路的紧急情况。", "吃饭": "搭配：“马上吃饭”不是司机遇到行人时的反应，搭配不成立。", "睡觉": "语义：司机在行人过马路时睡觉会造成危险，与句意相反。"}, "sentence_index": 0, "correct_answer": "停车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小区突然停车了，大家很着急。", "explanation": "这里应该用〈停水〉。停车只用于车辆，供水中断要说“停水”。"}, {"text": "晚上突然停车，房间很黑。", "explanation": "这里应该用〈停电〉。停车只指车辆停下，电力中断要说“停电”。"}, {"text": "这家店因为装修停车了。", "explanation": "这里应该用〈停业〉。店铺暂停营业要说“停业”，“停车”只用于车辆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc161bb1-80b8-483c-a3a8-eec2686a4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23536, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "停车", "is_correct": true, "explanation": "正确：“请停车检查”是警察要求车辆停下接受检查的说法，句意相合。"}, {"text": "搬家", "is_correct": false, "explanation": "语义：搬家与检查车辆无关，“请搬家检查”不通。"}, {"text": "理发", "is_correct": false, "explanation": "语义：理发与车辆检查无关，不符合警察的指令。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳检查”不是常用搭配，警察不会这样对车辆下指令。"}], "explanations": {"停车": "正确：“请停车检查”是警察要求车辆停下接受检查的说法，句意相合。", "搬家": "语义：搬家与检查车辆无关，“请搬家检查”不通。", "理发": "语义：理发与车辆检查无关，不符合警察的指令。", "游泳": "搭配：“游泳检查”不是常用搭配，警察不会这样对车辆下指令。"}, "sentence_index": 6, "correct_answer": "停车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他说话时停车了一下。", "explanation": "这里应该用〈停顿〉。停车只指车辆停下，人说话时暂停要说“停顿”。"}, {"text": "因为下大雨，工地停车了。", "explanation": "这里应该用〈停工〉。“停车”只用于车辆，工地暂停施工要说“停工”。"}, {"text": "因为台风，学校停车了。", "explanation": "这里应该用〈停课〉。“停车”只用于车辆，学校暂停上课要说“停课”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc161bb1-80b8-483c-a3a8-eec2686a4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们以前在这里停车过。", "corrected_sentence": "我们以前在这里停过车。", "error_description": "离合词体标位置错误：“过”应插在“停”与“车”之间，应为“停过车”，不能说“停车过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc161bb1-80b8-483c-a3a8-eec2686a4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "司机停车着，在车里打电话。", "corrected_sentence": "司机停着车，在车里打电话。", "error_description": "离合词位置错误：“着”应插在“停”与“车”之间，应为“停着车”，不能说“停车着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc161bb1-80b8-483c-a3a8-eec2686a4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
