INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23538, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "雨水是从天上落下来的水。", "primary_collocate": null, "pronunciation": "yǔ shuǐ", "ipa": "y˨˩˦ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "雨水是从天上落下来的水。", "target_word": "雨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用桶接了一桶雨水来浇花。", "target_word": "雨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水从窗户外面流了进来。", "target_word": "雨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路面上有很多雨水，小心滑倒。", "target_word": "雨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水把我的鞋都弄湿了。", "target_word": "雨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨过后，雨水流进了小河。", "target_word": "雨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋檐下的雨水一滴一滴往下掉。", "target_word": "雨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用雨水洗车，不用自来水。", "target_word": "雨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水太多，田里都是水。", "target_word": "雨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停以后，地上的雨水慢慢变少了。", "target_word": "雨水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "滴", "label": "量词"}, {"form": "雨水花园", "label": "复合"}], "register": "中性", "sense_fingerprint": "从天上落下来的雨形成的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '275ccb5f-1b55-4271-8c6c-799b66cfc0d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23538, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雨水", "is_correct": true, "explanation": "正确。雨水就是从天上落下来的水。"}, {"text": "河水", "is_correct": false, "explanation": "语义：河水来自地表的河流，不是从天上落下来的。"}, {"text": "泉水", "is_correct": false, "explanation": "语义：泉水从地下涌出，不是从天上落下来的。"}, {"text": "雨季", "is_correct": false, "explanation": "搭配：“雨季”指一段时间，不能作为“水”的定义主语。"}], "explanations": {"雨水": "正确。雨水就是从天上落下来的水。", "河水": "语义：河水来自地表的河流，不是从天上落下来的。", "泉水": "语义：泉水从地下涌出，不是从天上落下来的。", "雨季": "搭配：“雨季”指一段时间，不能作为“水”的定义主语。"}, "sentence_index": 0, "correct_answer": "雨水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "杯子里还剩一块雨水。", "explanation": "这里应该用〈一杯〉或〈一滴〉。雨水是液体，不能用“块”计量。"}, {"text": "汽车加满了雨水。", "explanation": "这里应该用〈汽油〉。汽车要加汽油，雨水不能作燃料。"}, {"text": "他的额头上冒出了雨水。", "explanation": "这里应该用〈汗水〉。额头冒出的是汗水，雨水不会从额头上冒出来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc161bb1-80b8-483c-a3a8-eec2686a4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23538, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨水", "is_correct": true, "explanation": "正确。屋檐下的雨水一滴一滴地落下，符合语境。"}, {"text": "瀑布", "is_correct": false, "explanation": "语义：瀑布是连续的大股水流，不会一滴一滴地往下掉。"}, {"text": "灰尘", "is_correct": false, "explanation": "搭配：“一滴一滴”只用于液体，不能用来修饰灰尘。"}, {"text": "铁锈", "is_correct": false, "explanation": "语义：铁锈是金属表面的氧化物，不是水，不会一滴一滴地往下掉。"}], "explanations": {"雨水": "正确。屋檐下的雨水一滴一滴地落下，符合语境。", "瀑布": "语义：瀑布是连续的大股水流，不会一滴一滴地往下掉。", "灰尘": "搭配：“一滴一滴”只用于液体，不能用来修饰灰尘。", "铁锈": "语义：铁锈是金属表面的氧化物，不是水，不会一滴一滴地往下掉。"}, "sentence_index": 6, "correct_answer": "雨水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人在墙上刷了一层雨水。", "explanation": "这里应该用〈油漆〉。刷墙用的是油漆，雨水不能用来刷墙。"}, {"text": "灯里加了雨水，就能点亮。", "explanation": "这里应该用〈煤油〉。煤油可以作灯油，雨水不能用来点灯。"}, {"text": "他把钢笔灌满了雨水，准备写字。", "explanation": "这里应该用〈墨水〉。钢笔要灌墨水，雨水不能用来灌钢笔写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc161bb1-80b8-483c-a3a8-eec2686a4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场大雨水把院子都淹了，院子里全是雨水。", "corrected_sentence": "这场大雨把院子都淹了，院子里全是雨水。", "error_description": "词语混用：描述降雨事件应说“这场大雨”，不能说“大雨水”；“雨水”指液体，不指降雨事件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc161bb1-80b8-483c-a3a8-eec2686a4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这桶水雨水，不能直接喝。", "corrected_sentence": "这桶水是雨水，不能直接喝。", "error_description": "漏掉“是”：判断句“这桶水是雨水”中的“是”不能省略，否则句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc161bb1-80b8-483c-a3a8-eec2686a4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
