INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23540, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "猫、狗、花、树这样活着的东西就是生物。", "primary_collocate": null, "pronunciation": "shēng wù", "ipa": "ʂɤŋ˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "猫、狗、花、树都是生物。", "target_word": "生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石头不是生物，它不会长大。", "target_word": "生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海里有很多我们不认识的生物。", "target_word": "生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种小生物只在夜里出来。", "target_word": "生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生物需要水和空气才能活着。", "target_word": "生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮上没有水，也没有生物。", "target_word": "生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的生物很多，有鸟、鱼和花草。", "target_word": "生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳光对所有生物都很重要。", "target_word": "生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些生物小得用眼睛看不见。", "target_word": "生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在山里发现了一种新的生物。", "target_word": "生物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "微生物", "label": "复合"}, {"form": "生物学", "label": "复合"}], "register": "中性", "sense_fingerprint": "生物：有生命、活着的东西，如动物和植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea089b11-07da-4ae5-aa39-37efb2e90fe9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23540, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生物", "is_correct": true, "explanation": "正确：“生物”指有生命的东西，如动物、植物。"}, {"text": "圣物", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是神圣的物品。"}, {"text": "生育", "is_correct": false, "explanation": "韵母不同：wù 为 u，yù 为 ü（w、y 只是零声母的拼写形式）；“生育”意思是生孩子、繁殖。"}, {"text": "省悟", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，意思是忽然醒悟。"}], "explanations": {"生物": "正确：“生物”指有生命的东西，如动物、植物。", "圣物": "shèng（第四声）与 shēng（第一声）声调不同，意思是神圣的物品。", "生育": "韵母不同：wù 为 u，yù 为 ü（w、y 只是零声母的拼写形式）；“生育”意思是生孩子、繁殖。", "省悟": "shěng（第三声）与 shēng（第一声）声调不同，意思是忽然醒悟。"}, "sentence_index": null, "correct_answer": "生物"}, "level_3": {"options": [{"text": "生物", "is_correct": true, "explanation": "正确：“猫、狗、花、树都是生物”中，“生物”指有生命的东西，符合句意。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：猫、狗、花、树都是有生命的东西，不是垃圾，句子意思不通。"}, {"text": "工具", "is_correct": false, "explanation": "语义：猫、狗、花、树不是工具，不能说“都是工具”。"}, {"text": "家具", "is_correct": false, "explanation": "语义：猫、狗、花、树不是家具，不能说“都是家具”。"}], "explanations": {"生物": "正确：“猫、狗、花、树都是生物”中，“生物”指有生命的东西，符合句意。", "垃圾": "语义：猫、狗、花、树都是有生命的东西，不是垃圾，句子意思不通。", "工具": "语义：猫、狗、花、树不是工具，不能说“都是工具”。", "家具": "语义：猫、狗、花、树不是家具，不能说“都是家具”。"}, "sentence_index": 0, "correct_answer": "生物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的生物很健康，经常去跑步。", "explanation": "这里应该用〈身体〉。“生物”指有生命的东西，不指人的身体；说身体健康要用身体。"}, {"text": "他为了朋友，愿意付出自己的生物。", "explanation": "这里应该用〈生命〉。“生物”指有生命的东西，不指生命本身；“付出生命”是固定说法。"}, {"text": "张老师是一个非常负责的生物。", "explanation": "这里应该用〈人〉。“生物”指动物、植物等有生命的东西，形容一个人的品质要用“人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23540, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生物", "is_correct": true, "explanation": "正确：“这里的生物很多，有鸟、鱼和花草”中，“生物”指有生命的东西，符合句意。"}, {"text": "家具", "is_correct": false, "explanation": "语义：句子列举的是鸟、鱼和花草，与家具无关，“家具”不能这样并列。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“很多”修饰可数的事物，不能说“很多天气”。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器不是鸟、鱼、花草一类，与句中列举的内容不符。"}], "explanations": {"生物": "正确：“这里的生物很多，有鸟、鱼和花草”中，“生物”指有生命的东西，符合句意。", "家具": "语义：句子列举的是鸟、鱼和花草，与家具无关，“家具”不能这样并列。", "天气": "搭配：“很多”修饰可数的事物，不能说“很多天气”。", "乐器": "语义：乐器不是鸟、鱼、花草一类，与句中列举的内容不符。"}, "sentence_index": 6, "correct_answer": "生物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的生物很开放，喜欢交朋友。", "explanation": "这里应该用〈思想〉。“生物”指有生命的东西，不指人的观念；形容思想开放要用思想。"}, {"text": "今天的生物很好，我们去公园吧。", "explanation": "这里应该用〈天气〉。“生物”指有生命的东西，不指天气情况；形容天气好要用天气。"}, {"text": "这道菜的生物很好，我吃了三碗。", "explanation": "这里应该用〈味道〉。“生物”指有生命的东西，不指食物的味道；形容味道好要用味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23540, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "池塘里有一块很小的生物。", "corrected_sentence": "池塘里有一种很小的生物。", "error_description": "量词错误：“生物”应该用量词“种”（或“个”），“块”用于块状的东西，不能用来数生物。应为「池塘里有一种很小的生物」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23540, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "深海里生活着一些发光地生物。", "corrected_sentence": "深海里生活着一些发光的生物。", "error_description": "结构助词错误：修饰名词“生物”要用“的”，“地”用于修饰动词。应为「发光的生物」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23548, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23548, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23548, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "廊道是房子里面或外面的一个长长的过道，上面有屋顶。", "primary_collocate": null, "pronunciation": "láng dào", "ipa": "lɑŋ˧˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "学校的廊道很长，也很干净。", "target_word": "廊道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家门前有一条廊道，下雨也不会湿。", "target_word": "廊道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院的廊道里有很多椅子，病人可以坐下等。", "target_word": "廊道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫在廊道里睡觉，没有人叫它。", "target_word": "廊道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上廊道里的灯亮了，我们走回房间。", "target_word": "廊道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老房子的廊道上有很多花盆。", "target_word": "廊道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭店的廊道在房子外面，夏天很凉快。", "target_word": "廊道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人坐在廊道里，看着院子里的雨。", "target_word": "廊道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在廊道里大声说话。", "target_word": "廊道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从教室出来，沿着廊道一直走就到了。", "target_word": "廊道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "生态廊道", "label": "复合"}, {"form": "生物廊道", "label": "复合"}], "register": "中性", "sense_fingerprint": "房子里外有屋顶的长过道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '393bfa21-a379-477d-b422-bab907e99afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23548, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "廊道", "is_correct": true, "explanation": "“廊道”指房子里外有屋顶的长过道，与“很长、干净”的描述相合。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是计时器具，不能用“很长”形容，“也很干净”也不合句意。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“很长”可用于歌曲，但“干净”不能用来形容歌曲，两个描述无法共同修饰它。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能用“很长”描述长度，与句中的空间语境不合。"}], "explanations": {"廊道": "“廊道”指房子里外有屋顶的长过道，与“很长、干净”的描述相合。", "闹钟": "语义：闹钟是计时器具，不能用“很长”形容，“也很干净”也不合句意。", "歌曲": "搭配：“很长”可用于歌曲，但“干净”不能用来形容歌曲，两个描述无法共同修饰它。", "空气": "语义：空气不能用“很长”描述长度，与句中的空间语境不合。"}, "sentence_index": 0, "correct_answer": "廊道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条廊道里的水很深，船可以开过去。", "explanation": "这里应该用〈水道〉。廊道指房屋内外有屋顶的过道，不指水中或水上的通路。"}, {"text": "这条生态廊道把两片森林连在一起。", "explanation": "这里“廊道”取生态学义项，指连接栖息地的带状区域，与本词“房子里外有屋顶的长过道”义项不同。"}, {"text": "这座村子的廊道全靠船来往。", "explanation": "这里应该用〈水路〉。廊道指房屋内外有屋顶的过道，不指水上的通道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23548, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "账本", "is_correct": false, "explanation": "语义：账本是记账的册子，不是房屋外的空间，与“夏天很凉快”不合。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“夏天很凉快”描述的是处所的温度，“钢琴”是乐器，不能这样搭配。"}, {"text": "廊道", "is_correct": true, "explanation": "“廊道”指房子外有屋顶的长过道，“夏天很凉快”符合句意。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装物品的袋子，不是房屋外的处所，与句意矛盾。"}], "explanations": {"账本": "语义：账本是记账的册子，不是房屋外的空间，与“夏天很凉快”不合。", "钢琴": "搭配：“夏天很凉快”描述的是处所的温度，“钢琴”是乐器，不能这样搭配。", "廊道": "“廊道”指房子外有屋顶的长过道，“夏天很凉快”符合句意。", "书包": "语义：书包是装物品的袋子，不是房屋外的处所，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "廊道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车沿着廊道一直开就到了。", "explanation": "这里应该用〈车道〉。廊道是供人行走的有顶通道，汽车不能行驶其中，车道才是车辆通行的路面。"}, {"text": "我们沿着廊道一直爬到了顶层。", "explanation": "这里应该用〈楼梯〉。廊道是水平的有顶通道，不能用于向上攀登楼层。"}, {"text": "这条生物廊道连接着两片森林，供动物迁徙。", "explanation": "这里“廊道”取生态学义项，指连接栖息地的带状区域，与本词“房子里外有屋顶的长过道”义项不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所老宅有一只廊道，连着前后两个院子。", "corrected_sentence": "这所老宅有一条廊道，连着前后两个院子。", "error_description": "量词错误：「廊道」是线状的通道，量词用「条」；「只」多用于动物、船只或成对的器物，不用于廊道。正确说法是「一条廊道」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋后有一条窄窄地廊道，通向厨房。", "corrected_sentence": "屋后有一条窄窄的廊道，通向厨房。", "error_description": "结构助词错误：修饰名词“廊道”的形容词短语后应用“的”，“地”用于修饰动词，不能接在名词前。正确说法是“窄窄的廊道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
