INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23552, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西分给每个人。", "primary_collocate": null, "pronunciation": "fēn pèi", "ipa": "fən pʰei", "syllable_count": 2, "sentences": [{"text": "学校把新书分配给每个班。", "target_word": "分配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给员工分配了新的宿舍。", "target_word": "分配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些苹果要平均分配给大家。", "target_word": "分配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府给灾区分配了很多粮食。", "target_word": "分配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱怎么分配，大家有意见。", "target_word": "分配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校分配给我们一间新教室。", "target_word": "分配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奖金要按每个人的成绩分配。", "target_word": "分配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些水果分配给三个小组。", "target_word": "分配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子是公司分配的，租金很便宜。", "target_word": "分配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食物不多，必须公平分配。", "target_word": "分配", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分配了", "label": "完成体"}, {"form": "分配过", "label": "经历体"}, {"form": "平均分配", "label": "复合"}], "register": "中性", "sense_fingerprint": "把物品、钱、资源等分给各人或各单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0347f031-0355-40d8-bc8c-c972af0e07eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23552, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分贝", "is_correct": false, "explanation": "分贝（fēn bèi）与分配（fēn pèi）只有第二音节声母不同（b 与 p），意思是声音强度的单位。"}, {"text": "分配", "is_correct": true, "explanation": "分配（fēn pèi）指按一定标准把物品分给各人或各单位，是正确答案。"}, {"text": "氛围", "is_correct": false, "explanation": "氛围（fēn wéi）第二音节声母不同（w 与 p）、声调也不同，意思是周围的气氛。"}, {"text": "丰沛", "is_correct": false, "explanation": "丰沛（fēng pèi）与分配（fēn pèi）第一音节韵尾不同（ng 与 n），意思是丰富充沛。"}, {"text": "分类", "is_correct": false, "explanation": "分类（fēn lèi）与分配（fēn pèi）只有第二音节声母不同（l 与 p），意思是按类别归类。"}], "explanations": {"分贝": "分贝（fēn bèi）与分配（fēn pèi）只有第二音节声母不同（b 与 p），意思是声音强度的单位。", "分配": "分配（fēn pèi）指按一定标准把物品分给各人或各单位，是正确答案。", "氛围": "氛围（fēn wéi）第二音节声母不同（w 与 p）、声调也不同，意思是周围的气氛。", "丰沛": "丰沛（fēng pèi）与分配（fēn pèi）第一音节韵尾不同（ng 与 n），意思是丰富充沛。", "分类": "分类（fēn lèi）与分配（fēn pèi）只有第二音节声母不同（l 与 p），意思是按类别归类。"}, "sentence_index": null, "correct_answer": "分配"}, "level_3": {"options": [{"text": "分配", "is_correct": true, "explanation": "分配：“分配给每个班”指按标准把物品分给各班，是正确用法。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指燃烧，书不能拿去烧给各班，句意不通。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿咬，与把书分给班级的情境无关。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是桌椅、脸等，不说“擦新书给每个班”。"}], "explanations": {"分配": "分配：“分配给每个班”指按标准把物品分给各班，是正确用法。", "烧": "语义：“烧”指燃烧，书不能拿去烧给各班，句意不通。", "咬": "语义：“咬”指用牙齿咬，与把书分给班级的情境无关。", "擦": "搭配：“擦”的对象是桌椅、脸等，不说“擦新书给每个班”。"}, "sentence_index": 0, "correct_answer": "分配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这些书分配放好了。", "explanation": "这里应该用〈分类〉。分配指把东西分给人或单位，把书按类整理要说分类。"}, {"text": "妈妈把蛋糕分配成了八块。", "explanation": "这里应该用〈分割〉。分割指切成几部分，分配指把东西交给人或单位，不用于切块。"}, {"text": "我把这份喜悦分配给了朋友。", "explanation": "这里应该用〈分享〉。分配用于可以划分的东西，喜悦要说分享。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23e663ea-358d-453a-a4ef-eb088c2e2768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23552, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "分批", "is_correct": false, "explanation": "分批（fēn pī）与分配（fēn pèi）韵母与声调都不同，意思是分成若干批次。"}, {"text": "分袂", "is_correct": false, "explanation": "分袂（fēn mèi）与分配（fēn pèi）只有第二音节声母不同（m 与 p），意思是离别、分手。"}, {"text": "分配", "is_correct": true, "explanation": "分配（fēn pèi）指按一定标准把物品分给各人或各单位，是正确答案。"}, {"text": "分赔", "is_correct": false, "explanation": "分赔（fēn péi）与分配（fēn pèi）只有第二音节声调不同，意思是按比例分摊赔付。"}], "explanations": {"分批": "分批（fēn pī）与分配（fēn pèi）韵母与声调都不同，意思是分成若干批次。", "分袂": "分袂（fēn mèi）与分配（fēn pèi）只有第二音节声母不同（m 与 p），意思是离别、分手。", "分配": "分配（fēn pèi）指按一定标准把物品分给各人或各单位，是正确答案。", "分赔": "分赔（fēn péi）与分配（fēn pèi）只有第二音节声调不同，意思是按比例分摊赔付。"}, "sentence_index": null, "correct_answer": "分配"}, "level_3": {"options": [{"text": "分配", "is_correct": true, "explanation": "分配：“按……分配”指按某个标准进行分配，与“按每个人的成绩”搭配。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”指用力使东西裂开，奖金不能按成绩被撕。"}, {"text": "制造", "is_correct": false, "explanation": "搭配：“制造”不与“成绩”组合，不说“按成绩制造”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指抛掉，与依据成绩发放奖金的含义不符。"}], "explanations": {"分配": "分配：“按……分配”指按某个标准进行分配，与“按每个人的成绩”搭配。", "撕": "语义：“撕”指用力使东西裂开，奖金不能按成绩被撕。", "制造": "搭配：“制造”不与“成绩”组合，不说“按成绩制造”。", "扔": "语义：“扔”指抛掉，与依据成绩发放奖金的含义不符。"}, "sentence_index": 6, "correct_answer": "分配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很擅长分配药材的好坏。", "explanation": "这里应该用〈分辨〉。分配指把东西分给人或单位，判断好坏要说分辨。"}, {"text": "大家应该一起分配困难。", "explanation": "这里应该用〈分担〉。困难不能分配，分担表示共同承受。"}, {"text": "妈妈把西瓜分配成了六块。", "explanation": "这里应该用〈切〉。分配是把东西交给人或单位，切成块要用切。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23e663ea-358d-453a-a4ef-eb088c2e2768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师把练习本分配了每个小组。", "corrected_sentence": "老师把练习本分配给了每个小组。", "error_description": "错误在于“分配”后漏了“给”。应说“分配给每个小组”，表示把练习本交给各组。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23e663ea-358d-453a-a4ef-eb088c2e2768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔钱要平均分配三个部门。", "corrected_sentence": "这笔钱要平均分配给三个部门。", "error_description": "错误在于“分配”后直接接“三个部门”，把接受者误当成了宾语；应加“给”引出接受者，说“平均分配给三个部门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23e663ea-358d-453a-a4ef-eb088c2e2768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23554, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "手动", "is_correct": true, "explanation": "正确。手动指靠人力操作，与电动靠电力驱动正好相对。"}, {"text": "陈旧", "is_correct": false, "explanation": "陈旧指东西老旧，与动力来源无关，不是电动的反义词。"}, {"text": "狭窄", "is_correct": false, "explanation": "狭窄指空间小，与动力来源无关，不构成相对关系。"}, {"text": "稳定", "is_correct": false, "explanation": "稳定指状态平稳不变，与动力来源不构成相对关系。"}], "correct_answer": "手动", "explanations": {"手动": "正确。手动指靠人力操作，与电动靠电力驱动正好相对。", "陈旧": "陈旧指东西老旧，与动力来源无关，不是电动的反义词。", "狭窄": "狭窄指空间小，与动力来源无关，不构成相对关系。", "稳定": "稳定指状态平稳不变，与动力来源不构成相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc161bb1-80b8-483c-a3a8-eec2686a4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23554, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "手动", "is_correct": true, "explanation": "正确。手动指靠人力操作，与电动靠电力驱动正好相对。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙指表面不光滑，与动力来源无关，不构成相对关系。"}, {"text": "简陋", "is_correct": false, "explanation": "简陋指设备粗糙、简单，与动力来源无关，不构成相对关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软指质地软，与动力来源无关，不构成相对关系。"}], "correct_answer": "手动", "explanations": {"手动": "正确。手动指靠人力操作，与电动靠电力驱动正好相对。", "粗糙": "粗糙指表面不光滑，与动力来源无关，不构成相对关系。", "简陋": "简陋指设备粗糙、简单，与动力来源无关，不构成相对关系。", "柔软": "柔软指质地软，与动力来源无关，不构成相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc161bb1-80b8-483c-a3a8-eec2686a4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23554, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "电动的东西是用电让它动起来的。", "primary_collocate": null, "pronunciation": "diàn dòng", "ipa": "tjɛn˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个窗帘是电动的，按一下就能打开。", "target_word": "电动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家超市的门看到人走近就会自己开，是电动的。", "target_word": "电动", "complexity_tier": "T3", "furigana": "zhè jiā chāo shì de mén kàn dào rén zǒu jìn jiù huì zì jǐ kāi, shì diàn dòng de", "sentence_source": "generated"}, {"text": "爷爷的轮椅是电动的，不用人推。", "target_word": "电动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的剃须刀是电动的，刮得很干净。", "target_word": "电动", "complexity_tier": "T3", "furigana": "bà ba de tì xū dāo shì diàn dòng de, guā de hěn gān jìng", "sentence_source": "generated"}, {"text": "哥哥的火车玩具是电动的，会在轨道上自己跑。", "target_word": "电动", "complexity_tier": "T3", "furigana": "gē ge de huǒ chē wán jù shì diàn dòng de, huì zài guǐ dào shàng zì jǐ pǎo", "sentence_source": "generated"}, {"text": "这把锯是电动的，比手动的快得多。", "target_word": "电动", "complexity_tier": "T3", "furigana": "zhè bǎ jù shì diàn dòng de, bǐ shǒu dòng de kuài de duō", "sentence_source": "generated"}, {"text": "这把椅子是电动的，可以自己升高。", "target_word": "电动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小熊是电动的，一碰就会自己唱歌。", "target_word": "电动", "complexity_tier": "T3", "furigana": "zhè zhī xiǎo xióng shì diàn dòng de, yí pèng jiù huì zì jǐ chàng gē", "sentence_source": "generated"}, {"text": "妈妈的按摩机是电动的，每天用二十分钟。", "target_word": "电动", "complexity_tier": "T3", "furigana": "mā ma de àn mó jī shì diàn dòng de, měi tiān yòng èr shí fēn zhōng", "sentence_source": "generated"}, {"text": "这张床可以电动调节高度，很舒服。", "target_word": "电动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "電動", "label": "繁体"}, {"form": "电动门", "label": "复合"}, {"form": "电动车", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西靠电来驱动，不用人手去动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '275ccb5f-1b55-4271-8c6c-799b66cfc0d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23554, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电动", "is_correct": true, "explanation": "正确。电动指东西用电力驱动，不用人手去动。"}, {"text": "调动", "is_correct": false, "explanation": "diào（第四声）与 diàn 韵母不同（ao 与 an），调动指调配或改变位置。"}, {"text": "变动", "is_correct": false, "explanation": "biàn（第四声）与 diàn 声母不同（b 与 d），变动指改变、变化。"}, {"text": "颤动", "is_correct": false, "explanation": "chàn（第四声）与 diàn 声母不同（ch 与 d），颤动指物体快速地抖动。"}], "explanations": {"电动": "正确。电动指东西用电力驱动，不用人手去动。", "调动": "diào（第四声）与 diàn 韵母不同（ao 与 an），调动指调配或改变位置。", "变动": "biàn（第四声）与 diàn 声母不同（b 与 d），变动指改变、变化。", "颤动": "chàn（第四声）与 diàn 声母不同（ch 与 d），颤动指物体快速地抖动。"}, "sentence_index": null, "correct_answer": "电动"}, "level_3": {"options": [{"text": "电动", "is_correct": true, "explanation": "正确。电动窗帘靠电力驱动，按一下即可开合。"}, {"text": "手动", "is_correct": false, "explanation": "语义：手动窗帘要用手拉，与“按一下就能打开”相矛盾。"}, {"text": "石质", "is_correct": false, "explanation": "语义：石质的窗帘既不能开合，也与常识不符。"}, {"text": "人力", "is_correct": false, "explanation": "搭配：“人力”不能用来形容窗帘的开合方式。"}], "explanations": {"电动": "正确。电动窗帘靠电力驱动，按一下即可开合。", "手动": "语义：手动窗帘要用手拉，与“按一下就能打开”相矛盾。", "石质": "语义：石质的窗帘既不能开合，也与常识不符。", "人力": "搭配：“人力”不能用来形容窗帘的开合方式。"}, "sentence_index": 0, "correct_answer": "电动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块面包是电动的，吃起来很软。", "explanation": "这里应该用〈松软〉。电动指用电让东西动起来，面包不会自己动，不能说电动。"}, {"text": "这块石头是电动的，放在桌上很稳。", "explanation": "这里应该用〈沉重〉或〈坚硬〉。石头没有动力，不能说电动。"}, {"text": "这只花瓶是电动的，插花很好看。", "explanation": "这里应该用〈精致〉。花瓶不靠电力动起来，不能说电动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc161bb1-80b8-483c-a3a8-eec2686a4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23554, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "电动", "is_correct": true, "explanation": "正确。电动指东西用电力驱动，不用人手去动。"}, {"text": "店东", "is_correct": false, "explanation": "dōng（第一声）与 dòng（第四声）声调不同，店东指店铺的主人。"}, {"text": "点动", "is_correct": false, "explanation": "diǎn（第三声）与 diàn（第四声）声调不同，点动指机器短时间启动后即停。"}, {"text": "颠动", "is_correct": false, "explanation": "diān（第一声）与 diàn（第四声）声调不同，颠动指上下或前后快速晃动。"}], "explanations": {"电动": "正确。电动指东西用电力驱动，不用人手去动。", "店东": "dōng（第一声）与 dòng（第四声）声调不同，店东指店铺的主人。", "点动": "diǎn（第三声）与 diàn（第四声）声调不同，点动指机器短时间启动后即停。", "颠动": "diān（第一声）与 diàn（第四声）声调不同，颠动指上下或前后快速晃动。"}, "sentence_index": null, "correct_answer": "电动"}, "level_3": {"options": [{"text": "电动", "is_correct": true, "explanation": "正确。电动椅子靠电力驱动，可以自己升高。"}, {"text": "木质", "is_correct": false, "explanation": "语义：木质椅子靠人力调节，不能自己升高。"}, {"text": "陶瓷", "is_correct": false, "explanation": "语义：陶瓷是易碎材料，不能自己升高。"}, {"text": "固定", "is_correct": false, "explanation": "搭配：“固定”与“自己升高”意思相反，搭配不通。"}], "explanations": {"电动": "正确。电动椅子靠电力驱动，可以自己升高。", "木质": "语义：木质椅子靠人力调节，不能自己升高。", "陶瓷": "语义：陶瓷是易碎材料，不能自己升高。", "固定": "搭配：“固定”与“自己升高”意思相反，搭配不通。"}, "sentence_index": 6, "correct_answer": "电动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片树叶是电动的，风一吹就会动。", "explanation": "这里应该用〈轻盈〉。电动指用电力让东西动起来，树叶靠风动，不能说电动。"}, {"text": "这首歌是电动的，听起来很有活力。", "explanation": "这里应该用〈动感〉。电动说的是动力来源，不能形容歌曲的节奏。"}, {"text": "这座山是电动的，夏天能看到很多云。", "explanation": "这里应该用〈高大〉。山没有动力装置，不能说电动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc161bb1-80b8-483c-a3a8-eec2686a4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23554, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张沙发可以电动动调节角度，坐着很舒服。", "corrected_sentence": "这张沙发可以电动调节角度，坐着很舒服。", "error_description": "词内重复：“电动”是固定词语，末尾的“动”不能重复，应说“可以电动调节角度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc161bb1-80b8-483c-a3a8-eec2686a4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23554, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台按摩椅电动的，坐上去很放松。", "corrected_sentence": "这台按摩椅是电动的，坐上去很放松。", "error_description": "漏掉“是”：“是电动的”中的“是”不能省略，应说“这台按摩椅是电动的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc161bb1-80b8-483c-a3a8-eec2686a4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
