INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23562, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供电系统就是让灯亮、让电器工作的东西。", "primary_collocate": null, "pronunciation": "gōng diàn xì tǒng", "ipa": "kʊŋ˥ tjɛn˥˩ ɕi˥˩ tʰʊŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "有了供电系统，家里的灯才能亮。", "target_word": "供电系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "供电系统坏了，所有电器都不能用。", "target_word": "供电系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区的孩子们终于用上了新的供电系统。", "target_word": "供电系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子里的供电系统让冰箱和电视都能工作。", "target_word": "供电系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座岛上没有供电系统，晚上很黑。", "target_word": "供电系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在教室里装好了供电系统，灯亮了。", "target_word": "供电系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为供电系统出了错，整条街都停电了。", "target_word": "供电系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停电时，医院的备用供电系统会马上工作。", "target_word": "供电系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的供电系统每年都要检查。", "target_word": "供电系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，家里的供电系统该换了。", "target_word": "供电系统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "供電系統", "label": "繁体"}], "register": "书面", "sense_fingerprint": "让灯亮、让电器能工作的送电设施", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '275ccb5f-1b55-4271-8c6c-799b66cfc0d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23562, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "供电系统", "is_correct": true, "explanation": "正确：供电系统是让灯亮、让电器工作的设施，与“灯才能亮”直接相关。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘只能遮光，不能让灯亮，与“灯才能亮”的前提不符。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙用于开锁，与灯能否亮没有关系。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“灯才能亮”的前提应是供电，“饭菜”不能作为灯亮的条件，搭配不当。"}], "explanations": {"供电系统": "正确：供电系统是让灯亮、让电器工作的设施，与“灯才能亮”直接相关。", "窗帘": "语义：窗帘只能遮光，不能让灯亮，与“灯才能亮”的前提不符。", "钥匙": "语义：钥匙用于开锁，与灯能否亮没有关系。", "饭菜": "搭配：“灯才能亮”的前提应是供电，“饭菜”不能作为灯亮的条件，搭配不当。"}, "sentence_index": 0, "correct_answer": "供电系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "供电系统向我们道歉了。", "explanation": "这里应该用〈电力公司〉。道歉是人或机构的行为，供电系统只是设施，不能道歉。"}, {"text": "供电系统让房子长高了。", "explanation": "这里应该用〈加盖〉。房子增高要靠施工加盖，供电系统不能让房子长高。"}, {"text": "供电系统向老师请了假。", "explanation": "这里应该用〈学生〉。请假是人的行为，供电系统不能请假。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc161bb1-80b8-483c-a3a8-eec2686a4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23562, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "供电系统", "is_correct": true, "explanation": "正确：供电系统出错会造成整条街停电，这里的因果关系成立。"}, {"text": "作业本", "is_correct": false, "explanation": "语义：作业本出错不会让整条街停电，前后的因果关系不成立。"}, {"text": "交通规则", "is_correct": false, "explanation": "语义：交通规则出错不会造成停电，与后文的结果无关。"}, {"text": "菜单", "is_correct": false, "explanation": "搭配：“出了错”后面的后果应是停电这类设施故障，“菜单”出错不能导致停电，搭配不当。"}], "explanations": {"供电系统": "正确：供电系统出错会造成整条街停电，这里的因果关系成立。", "作业本": "语义：作业本出错不会让整条街停电，前后的因果关系不成立。", "交通规则": "语义：交通规则出错不会造成停电，与后文的结果无关。", "菜单": "搭配：“出了错”后面的后果应是停电这类设施故障，“菜单”出错不能导致停电，搭配不当。"}, "sentence_index": 6, "correct_answer": "供电系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客厅的供电系统每天给我们放新闻。", "explanation": "这里应该用〈电视机〉。放新闻是电视机的功能，供电系统不能播放节目。"}, {"text": "供电系统能放很多书。", "explanation": "这里应该用〈书架〉。放书是书架的用途，供电系统不能用来放东西。"}, {"text": "供电系统每天早上把我叫醒。", "explanation": "这里应该用〈闹钟〉。按时叫人起床是闹钟的作用，供电系统不能叫人起床。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc161bb1-80b8-483c-a3a8-eec2686a4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23562, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家装了一根供电系统。", "corrected_sentence": "我们家装了一套供电系统。", "error_description": "量词错误：“供电系统”是成套设备，应说“一套”，不能说“一根”，“根”用于细长的物件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc161bb1-80b8-483c-a3a8-eec2686a4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23562, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套供电系统去年喝过。", "corrected_sentence": "这套供电系统去年换过。", "error_description": "搭配错误：“喝”不能用于“供电系统”，应说“换过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc161bb1-80b8-483c-a3a8-eec2686a4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
