INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23564, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23564, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以一直用的能源，比如太阳和风。", "primary_collocate": null, "pronunciation": "zài shēng néng yuán", "ipa": "tsaɪ˥˩ ʂɤŋ˥ nɤŋ˧˥ ɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "太阳是再生能源，每天都有。", "target_word": "再生能源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风也是一种再生能源。", "target_word": "再生能源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "再生能源用不完，所以很好。", "target_word": "再生能源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的房子用再生能源发电，不用买电。", "target_word": "再生能源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，水也是再生能源。", "target_word": "再生能源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "石油会用完，再生能源不会用完。", "target_word": "再生能源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小村子的电都来自再生能源。", "target_word": "再生能源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风车用风发电，风是再生能源。", "target_word": "再生能源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在山上建了一座太阳能电站，用的是再生能源。", "target_word": "再生能源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该多用再生能源，少用煤。", "target_word": "再生能源", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "可再生能源", "label": "复合"}], "register": "书面", "sense_fingerprint": "可以一直使用的能源（太阳、风）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '393bfa21-a379-477d-b422-bab907e99afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23564, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再生能源", "is_correct": true, "explanation": "正确：“太阳是再生能源”说的是能一直使用的能源，与“每天都有”一致。"}, {"text": "煤炭", "is_correct": false, "explanation": "语义：煤炭会越用越少，不是每天都有，与“每天都有”矛盾。"}, {"text": "天然气", "is_correct": false, "explanation": "语义：天然气是化石燃料，用一点就少一点，与“每天都有”不符。"}, {"text": "发电机", "is_correct": false, "explanation": "搭配：“太阳”不能与“发电机”归为同类，发电机是设备，不是能源来源。"}], "explanations": {"再生能源": "正确：“太阳是再生能源”说的是能一直使用的能源，与“每天都有”一致。", "煤炭": "语义：煤炭会越用越少，不是每天都有，与“每天都有”矛盾。", "天然气": "语义：天然气是化石燃料，用一点就少一点，与“每天都有”不符。", "发电机": "搭配：“太阳”不能与“发电机”归为同类，发电机是设备，不是能源来源。"}, "sentence_index": 0, "correct_answer": "再生能源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "煤炭属于再生能源。", "explanation": "这里应该用〈化石能源〉。煤炭会用完，不能不断再生，不属于“再生能源”的义项。"}, {"text": "这堆废铁属于可以回收的再生能源。", "explanation": "这里应该用〈再生资源〉。废铁是可回收利用的物资，不属于能源；“再生能源”只指能不断再生的能源。"}, {"text": "这台冰箱是再生能源。", "explanation": "这里“再生能源”取能源类别的义项，冰箱是电器，不是能源，不能说它“是再生能源”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23564, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再生能源", "is_correct": true, "explanation": "正确：“来自再生能源”指电的来源是能不断再生的能源，与句子语境相符。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市是人聚居的地方，不能作为电的来源。"}, {"text": "书本", "is_correct": false, "explanation": "语义：书本不能产生电，“电都来自书本”与常识相反。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：冰箱是耗电的电器，不是电的来源，“来自”后面不能接“冰箱”。"}], "explanations": {"再生能源": "正确：“来自再生能源”指电的来源是能不断再生的能源，与句子语境相符。", "城市": "语义：城市是人聚居的地方，不能作为电的来源。", "书本": "语义：书本不能产生电，“电都来自书本”与常识相反。", "冰箱": "搭配：冰箱是耗电的电器，不是电的来源，“来自”后面不能接“冰箱”。"}, "sentence_index": 6, "correct_answer": "再生能源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "喝了一杯牛奶后，身体就能补充再生能源。", "explanation": "这里应该用〈能量〉。牛奶给身体提供的是能量，不是能源的种类，不能说补充“再生能源”。"}, {"text": "这台电动机的再生能源很大。", "explanation": "这里应该用〈功率〉。功率表示机器做功的快慢，可以说“很大”；“再生能源”是能源的类别，不能说“很大”。"}, {"text": "我把再生能源装进了书包里。", "explanation": "这里应该用〈电〉。再生能源是抽象的能源类别，不是实物，不能装进书包；可以说“把电存进电池”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23564, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地热能是一台再生能源，可以一直用。", "corrected_sentence": "地热能是一种再生能源，可以一直用。", "error_description": "量词错误：“再生能源”是能源，应用量词“种”；“台”用于机器、设备，不能用于能源。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23564, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农村大力推迟再生能源。", "corrected_sentence": "农村大力推广再生能源。", "error_description": "搭配错误：“再生能源”是能源，不能与“推迟”搭配；“推迟”指把时间往后定，应用动词“推广”，说“大力推广再生能源”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
