INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23572, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过闸门进入，如检票入场或赛马进入起跑闸。", "primary_collocate": null, "pronunciation": "rù zhá", "ipa": "/ʐu˥˩ ʈʂa˧˥/", "syllable_count": 2, "sentences": [{"text": "比赛前，赛马一匹一匹入闸。", "target_word": "入闸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员请观众从这边入闸。", "target_word": "入闸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷们排好队，慢慢入闸。", "target_word": "入闸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开场前一小时，观众开始入闸。", "target_word": "入闸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着票，第一个入闸。", "target_word": "入闸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小马很紧张，不肯入闸。", "target_word": "入闸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演唱会七点开始，六点大家就入闸了。", "target_word": "入闸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让学生按顺序入闸。", "target_word": "入闸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们跟着家长入闸看比赛。", "target_word": "入闸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家带好票，从二号口入闸。", "target_word": "入闸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人或赛马依次走进闸门", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad8707b-b94c-4d2f-9bdd-fe5d9124629c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23572, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "入闸", "is_correct": true, "explanation": "入闸：赛马依次走进起跑闸门，符合“比赛前”的场景。"}, {"text": "散场", "is_correct": false, "explanation": "语义：散场是演出或比赛结束后人群散去，与“比赛前”的时间背景矛盾。"}, {"text": "夺冠", "is_correct": false, "explanation": "语义：夺冠是比赛结束后的结果，放在“比赛前”的语境中语义不通。"}, {"text": "赢球", "is_correct": false, "explanation": "搭配：“赢球”用于球类比赛，赛马不说“赢球”。"}], "explanations": {"入闸": "入闸：赛马依次走进起跑闸门，符合“比赛前”的场景。", "散场": "语义：散场是演出或比赛结束后人群散去，与“比赛前”的时间背景矛盾。", "夺冠": "语义：夺冠是比赛结束后的结果，放在“比赛前”的语境中语义不通。", "赢球": "搭配：“赢球”用于球类比赛，赛马不说“赢球”。"}, "sentence_index": 0, "correct_answer": "入闸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在售票窗口入闸，买了一张票。", "explanation": "这里应该用〈买票〉。“入闸”指走进闸门，买票要在售票窗口办，不能用“入闸”表示。"}, {"text": "演出结束后，观众开始入闸。", "explanation": "这里应该用〈离场〉。“入闸”是走进闸门，表示进入；演出结束后观众是离开，要说“离场”。"}, {"text": "演员谢幕后入闸。", "explanation": "这里应该用〈退场〉。“入闸”是走进闸门，不是从舞台退下；谢幕后退下要说“退场”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab5485f9-d7c9-4527-8302-2ad2d3088ebc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23572, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "入闸", "is_correct": true, "explanation": "入闸：走进闸门，符合“六点大家就”进场的意思，与“七点开始”相呼应。"}, {"text": "散场", "is_correct": false, "explanation": "语义：散场发生在演出结束后，与“七点开始”“六点就……”的时间顺序矛盾。"}, {"text": "退场", "is_correct": false, "explanation": "语义：退场是演出结束后的离开，放在演唱会开始前的语境中语义不通。"}, {"text": "卖票", "is_correct": false, "explanation": "搭配：“卖票”的主体是售票方，观众不说“大家就卖票了”。"}], "explanations": {"入闸": "入闸：走进闸门，符合“六点大家就”进场的意思，与“七点开始”相呼应。", "散场": "语义：散场发生在演出结束后，与“七点开始”“六点就……”的时间顺序矛盾。", "退场": "语义：退场是演出结束后的离开，放在演唱会开始前的语境中语义不通。", "卖票": "搭配：“卖票”的主体是售票方，观众不说“大家就卖票了”。"}, "sentence_index": 6, "correct_answer": "入闸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "列车缓缓入闸，乘客陆续下车。", "explanation": "这里应该用〈进站〉。列车进站要说“进站”，“入闸”指走进一个门，不能用来形容列车。"}, {"text": "球赛结束后，球迷慢慢入闸。", "explanation": "这里应该用〈离场〉。“入闸”是走进闸门，球赛结束后观众是离开，要说“离场”。"}, {"text": "电影放完，观众入闸。", "explanation": "这里应该用〈散场〉。“入闸”表示进入，电影放完后人群散开要说“散场”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab5485f9-d7c9-4527-8302-2ad2d3088ebc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23572, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这匹马以前入闸过，比较镇定。", "corrected_sentence": "这匹马以前入过闸，比较镇定。", "error_description": "错在“入闸过”。“过”要紧跟动词，应说“入过闸”，不说“入闸过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab5485f9-d7c9-4527-8302-2ad2d3088ebc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23572, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工作人员让大家从二号口闸入，入闸的人很多。", "corrected_sentence": "工作人员让大家从二号口入闸，入闸的人很多。", "error_description": "错在“闸入”。“入闸”是动宾结构，应说“入闸”，不说“闸入”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab5485f9-d7c9-4527-8302-2ad2d3088ebc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
