INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23578, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用卡在机器上划一下，可以付钱或开门。", "primary_collocate": null, "pronunciation": "shuā kǎ", "ipa": "ʂwa˥ kʰa˨˩˦", "syllable_count": 2, "sentences": [{"text": "我刷卡买了一杯咖啡。", "target_word": "刷卡", "complexity_tier": "T3", "furigana": "wǒ shuā kǎ mǎi le yì bēi kā fēi", "sentence_source": "generated"}, {"text": "请在这里刷卡，门就会开。", "target_word": "刷卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明每天早上刷卡进学校。", "target_word": "刷卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以刷卡，也可以给现金。", "target_word": "刷卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刷卡以后，要输入密码。", "target_word": "刷卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门买东西，我常常刷卡。", "target_word": "刷卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器坏了，不能刷卡。", "target_word": "刷卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸刷卡付了电费。", "target_word": "刷卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们刷卡上了公共汽车。", "target_word": "刷卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刷卡后，机器会响一声。", "target_word": "刷卡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "刷了卡", "label": "体标"}, {"form": "刷过卡", "label": "体标"}, {"form": "刷卡机", "label": "复合"}], "register": "中性", "sense_fingerprint": "刷卡·动词·用卡在机器上划一下付钱或开门", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad8707b-b94c-4d2f-9bdd-fe5d9124629c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23578, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刷卡", "is_correct": true, "explanation": "刷卡：用卡在机器上划一下完成付款，与“买了一杯咖啡”的语境吻合。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：跑步与买咖啡没有动作上的关联，句子说的是购买。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳不能用来完成购买咖啡的动作，放在这里语义矛盾。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”的对象是文件、材料，不能用来表示买咖啡。"}], "explanations": {"刷卡": "刷卡：用卡在机器上划一下完成付款，与“买了一杯咖啡”的语境吻合。", "跑步": "语义：跑步与买咖啡没有动作上的关联，句子说的是购买。", "游泳": "语义：游泳不能用来完成购买咖啡的动作，放在这里语义矛盾。", "打印": "搭配：“打印”的对象是文件、材料，不能用来表示买咖啡。"}, "sentence_index": 0, "correct_answer": "刷卡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家健身房按月刷卡。", "explanation": "这里应该用〈收费〉。刷卡指用卡在机器上划过付款，不表示按月计价；按月计费要说“收费”。"}, {"text": "妈妈刷卡给我一个红包。", "explanation": "这里应该用〈发〉。刷卡只用于在机器上付款或开门，不能把红包送给别人；发红包要说“发”。"}, {"text": "电梯里他刷卡选了一下楼层。", "explanation": "这里应该用〈按〉。刷卡只是在机器上划一下，不能用来选择楼层；按电梯按钮要说“按”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab5485f9-d7c9-4527-8302-2ad2d3088ebc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23578, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刷卡", "is_correct": true, "explanation": "刷卡：用卡在机器上划过，是机器能正常工作时才能完成的操作，与“机器坏了”形成对照。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：机器不会睡觉，“睡觉”与句中机器故障的语境无关。"}, {"text": "撒谎", "is_correct": false, "explanation": "语义：机器不会撒谎，这个动作与句中讲的机器功能毫不相干。"}, {"text": "遨游", "is_correct": false, "explanation": "语域：“遨游”是文学性的书面用语，与口语化的“机器坏了”语域不协调。"}], "explanations": {"刷卡": "刷卡：用卡在机器上划过，是机器能正常工作时才能完成的操作，与“机器坏了”形成对照。", "睡觉": "语义：机器不会睡觉，“睡觉”与句中机器故障的语境无关。", "撒谎": "语义：机器不会撒谎，这个动作与句中讲的机器功能毫不相干。", "遨游": "语域：“遨游”是文学性的书面用语，与口语化的“机器坏了”语域不协调。"}, "sentence_index": 6, "correct_answer": "刷卡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刷卡量了一下体温。", "explanation": "这里应该用〈测〉。刷卡是在机器上划卡付款或开门，不能用来测体温；测体温要说“测”。"}, {"text": "他刷卡擦了擦桌子。", "explanation": "这里应该用〈擦〉。刷卡是在机器上划卡付款或开门，不能用来擦桌子；擦桌子要说“擦”。"}, {"text": "他在收据上刷卡。", "explanation": "这里应该用〈签收〉。刷卡是划卡动作，不能用在纸质收据上；在收据上确认收到要说“签收”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab5485f9-d7c9-4527-8302-2ad2d3088ebc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把卡刷卡，机器就响了。", "corrected_sentence": "我刷卡，机器就响了。", "error_description": "错在“把卡刷卡”：“刷卡”本身已含宾语“卡”，前面又用“把卡”引出同一宾语，重复；应直接说“刷卡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab5485f9-d7c9-4527-8302-2ad2d3088ebc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我刷卡了过，机器就响了。", "corrected_sentence": "我刷卡了，机器就响了。", "error_description": "错在「了过」：「了」与「过」不能同时用在同一动词后。表示已完成的一次动作只用「了」，应删去「过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab5485f9-d7c9-4527-8302-2ad2d3088ebc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
