INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23580, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "坐车的人。", "primary_collocate": null, "pronunciation": "chéng kè", "ipa": "ʈʂʰɤŋ˧˥ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "车上的乘客一个接一个下去了。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆公交车一次能坐五十名乘客。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘客买票以后才能进站。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机帮老年乘客拿行李。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船上的乘客都在看海。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场广播请乘客去三号门登机。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这趟高铁上的第一位乘客。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘客太多，车门关不上。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘客向司机说了声谢谢。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的末班车只有两位乘客。", "target_word": "乘客", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位乘客", "label": "量词"}, {"form": "一名乘客", "label": "量词"}], "register": "中性", "sense_fingerprint": "坐车的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d73da08-f1e3-4736-83d2-b9a3a45c59eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23580, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乘客", "is_correct": true, "explanation": "正确：坐车的人，这里指车上下车的人。"}, {"text": "飞机", "is_correct": false, "explanation": "语义：飞机不会一个接一个从车上下去，与句子不合。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星挂在天上，不会从车上一个接一个下去。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会自己下车，与“下去”的意思不合。"}], "explanations": {"乘客": "正确：坐车的人，这里指车上下车的人。", "飞机": "语义：飞机不会一个接一个从车上下去，与句子不合。", "星星": "语义：星星挂在天上，不会从车上一个接一个下去。", "石头": "语义：石头不会自己下车，与“下去”的意思不合。"}, "sentence_index": 0, "correct_answer": "乘客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "剧场里的乘客很多，大家都在等演出开始。", "explanation": "这里应该用〈观众〉。乘客指乘车的人，看演出的人应说〈观众〉。"}, {"text": "教室里的乘客都在认真听讲。", "explanation": "这里应该用〈学生〉。乘客指乘车的人，上课听讲的人应说〈学生〉。"}, {"text": "我们家来了一位乘客，陪我们聊天。", "explanation": "这里应该用〈客人〉。乘客指乘坐交通工具的人，来家里做客的人应说〈客人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乘客", "is_correct": true, "explanation": "正确：坐车的人，这里指第一个上这趟车的人。"}, {"text": "幽灵", "is_correct": false, "explanation": "语义：幽灵不是坐车的人，“第一位幽灵”的说法与句意不合。"}, {"text": "客官", "is_correct": false, "explanation": "语域：“客官”是旧式称呼，现代不用来指高铁上的乘客。"}, {"text": "车票", "is_correct": false, "explanation": "语义：车票是纸片，不是人，不能用“位”来数。"}], "explanations": {"乘客": "正确：坐车的人，这里指第一个上这趟车的人。", "幽灵": "语义：幽灵不是坐车的人，“第一位幽灵”的说法与句意不合。", "客官": "语域：“客官”是旧式称呼，现代不用来指高铁上的乘客。", "车票": "语义：车票是纸片，不是人，不能用“位”来数。"}, "sentence_index": 6, "correct_answer": "乘客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座古城每天有很多乘客。", "explanation": "这里应该用〈游客〉。乘客指乘坐交通工具的人，来景点观光的人应说〈游客〉。"}, {"text": "医院里的乘客排着队等候看病。", "explanation": "这里应该用〈病人〉。乘客指乘车的人，等候看病的人应说〈病人〉。"}, {"text": "社区里来了一位乘客，找我们商量事情。", "explanation": "这里应该用〈访客〉。乘客指乘车的人，到社区来找人的应说〈访客〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车上有三只乘客。", "corrected_sentence": "车上有三名乘客。", "error_description": "“乘客”指人，量词应用“名”或“位”，不能用“只”（“只”多用于动物）。应说“三名乘客”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "司机让一位乘客们先上车。", "corrected_sentence": "司机让一位乘客先上车。", "error_description": "“们”表示复数，不能与数量词“一位”连用；有了数量词，“乘客”就已经计量清楚。应说“一位乘客”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
