INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23588, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思是真正重要的、根本的。", "primary_collocate": null, "pronunciation": "shí zhì xìng", "ipa": "ʂʐ̩˧˥ ʈʂʐ̩˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "老师给我的建议有实质性帮助。", "target_word": "实质性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个办法没有实质性区别。", "target_word": "实质性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他只是笑笑，没有给出实质性答复。", "target_word": "实质性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理希望会议有实质性结果。", "target_word": "实质性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气对比赛没有实质性影响。", "target_word": "实质性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的关系有了实质性变化。", "target_word": "实质性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光说好话不行，要有实质性的行动。", "target_word": "实质性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "改名字不是实质性改变，只是换个说法。", "target_word": "实质性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱对他们是实质性的支持。", "target_word": "实质性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都想听到实质性的消息。", "target_word": "实质性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "實質性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "真正有分量、不只是说说而已的（实质性帮助、实质性行动）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d73da08-f1e3-4736-83d2-b9a3a45c59eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23588, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "实质性", "is_correct": true, "explanation": "“有实质性帮助”指真正起作用的帮助，符合句意。"}, {"text": "圆滚滚", "is_correct": false, "explanation": "语义：“圆滚滚”形容物体的形状，与“帮助”不相干。"}, {"text": "笨重", "is_correct": false, "explanation": "语义：“笨重”形容物体沉，不能修饰“帮助”。"}, {"text": "通红", "is_correct": false, "explanation": "搭配：“通红”是颜色，不能修饰“帮助”。"}], "explanations": {"实质性": "“有实质性帮助”指真正起作用的帮助，符合句意。", "圆滚滚": "语义：“圆滚滚”形容物体的形状，与“帮助”不相干。", "笨重": "语义：“笨重”形容物体沉，不能修饰“帮助”。", "通红": "搭配：“通红”是颜色，不能修饰“帮助”。"}, "sentence_index": 0, "correct_answer": "实质性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天上的云朵是实质性的。", "explanation": "这里应该用〈洁白〉之类描述外观的词。实质性是“真正重要、根本”，不能形容云朵这类自然景物。"}, {"text": "他的声音是实质性的。", "explanation": "这里应该用〈洪亮〉。实质性是“真正重要、根本”，不能用来形容声音这类听觉感受。"}, {"text": "他是一个实质性的朋友。", "explanation": "这里应该用〈真正〉。实质性用于修饰事情、问题或成果，不用来形容人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实质性", "is_correct": true, "explanation": "“实质性的行动”指真正付诸实施的行动，与“光说好话不行”呼应。"}, {"text": "粉红", "is_correct": false, "explanation": "搭配：“粉红”是颜色，不能修饰“行动”。"}, {"text": "湿漉漉", "is_correct": false, "explanation": "语义：“湿漉漉”形容湿透的状态，与行动无关。"}, {"text": "深红", "is_correct": false, "explanation": "搭配：“深红”是颜色，不能修饰“行动”。"}], "explanations": {"实质性": "“实质性的行动”指真正付诸实施的行动，与“光说好话不行”呼应。", "粉红": "搭配：“粉红”是颜色，不能修饰“行动”。", "湿漉漉": "语义：“湿漉漉”形容湿透的状态，与行动无关。", "深红": "搭配：“深红”是颜色，不能修饰“行动”。"}, "sentence_index": 6, "correct_answer": "实质性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盆花的香味是实质性的。", "explanation": "这里应该用〈香浓〉。实质性是“真正重要、根本”，不能用来形容香味这类感觉。"}, {"text": "这张桌子的形状是实质性的。", "explanation": "这里应该用〈圆〉或〈方〉之类描述形状的词。实质性是“真正重要、根本”，不能用来描述形状。"}, {"text": "他的脾气是实质性的。", "explanation": "这里应该用〈温和〉。实质性是“真正重要、根本”，不能用来形容脾气这类性格特点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们终于有了实质性地进展。", "corrected_sentence": "他们终于有了实质性的进展。", "error_description": "结构助词误用：“实质性”修饰名词“进展”，应用“的”，不用“地”。“地”用于修饰动词或形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次会议要提出实质性的建议们。", "corrected_sentence": "这次会议要提出实质性的建议。", "error_description": "名词误用：“建议”是抽象名词，不能加“们”表示复数，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
