INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23590, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来打开锁或保护秘密的一串数字、字母或符号。", "primary_collocate": null, "pronunciation": "mì mǎ", "ipa": "mi˥˩ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个行李箱的密码是三个数字。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我记不住保险箱的密码。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门锁的密码只有家人知道。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他输入密码，打开了小柜子。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把箱子的密码改成你的生日吧。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给手机设了一个新密码。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "密码太长了，我用本子记下来。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的日记本有密码，我打不开。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板只把保险柜的密码告诉了我。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开门前要先输入密码。", "target_word": "密码", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "密码箱", "label": "复合"}, {"form": "密碼", "label": "繁体"}], "register": "中性", "sense_fingerprint": "打开锁或保护秘密的一串数字字母符号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569bc8cf-48c5-4326-bc0a-b2a00dd42f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23590, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "密码", "is_correct": true, "explanation": "正确：行李箱的密码是一串数字，「密码」与「是三个数字」搭配自然。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是金属器具，不能由数字组成，句子意思说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「是三个数字」描述的是可数的符号，颜色不能用数字来描述。"}, {"text": "轮子", "is_correct": false, "explanation": "体貌：轮子是箱子的有形部件，它的外形和数量不能用「三个数字」来说明。"}], "explanations": {"密码": "正确：行李箱的密码是一串数字，「密码」与「是三个数字」搭配自然。", "钥匙": "语义：钥匙是金属器具，不能由数字组成，句子意思说不通。", "颜色": "搭配：「是三个数字」描述的是可数的符号，颜色不能用数字来描述。", "轮子": "体貌：轮子是箱子的有形部件，它的外形和数量不能用「三个数字」来说明。"}, "sentence_index": 0, "correct_answer": "密码"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我记住了一条密码。", "explanation": "这里应该用〈个〉。〈条〉用于细长的事物，密码用〈个〉或〈组〉。"}, {"text": "出门前要先吃掉密码。", "explanation": "这里应该用〈输入〉。〈吃掉〉的宾语必须是食物，密码不能吃，应说〈输入〉。"}, {"text": "这个密码很圆。", "explanation": "密码没有形状，〈圆〉只用于具体物体的形状，描述密码应说〈长〉或〈复杂〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23590, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密码", "is_correct": true, "explanation": "正确：「太长了」描述的是密码的长度，用本子记下来也说明它是一串需要抄写的字符。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮料，不能用「太长」来形容，也不需要用本子记下来。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：「太长了」用于可以计量长度的事物，阳光不能用长短来形容。"}, {"text": "天空", "is_correct": false, "explanation": "体貌：天空是没有长短概念的广阔空间，「太长」不能描述天空的外观。"}], "explanations": {"密码": "正确：「太长了」描述的是密码的长度，用本子记下来也说明它是一串需要抄写的字符。", "咖啡": "语义：咖啡是饮料，不能用「太长」来形容，也不需要用本子记下来。", "阳光": "搭配：「太长了」用于可以计量长度的事物，阳光不能用长短来形容。", "天空": "体貌：天空是没有长短概念的广阔空间，「太长」不能描述天空的外观。"}, "sentence_index": 6, "correct_answer": "密码"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用密码敲门，敲了三次。", "explanation": "密码不是敲门的工具，〈敲〉要用手或门环。"}, {"text": "开门前要先把密码插进去。", "explanation": "这里应该用〈输入〉。〈插进去〉用于钥匙等有形物，密码不能插入。"}, {"text": "他每天早上喝一口密码。", "explanation": "这里应该用〈牛奶〉。〈喝〉的宾语必须是可以饮用的东西，密码不能喝，应换成〈牛奶〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我找到了两把保险箱的密码。", "corrected_sentence": "我找到了两组保险箱的密码。", "error_description": "量词错误：「把」用于有柄的器具，密码应说「组」或「个」。正确句为「我找到了两组保险箱的密码。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把保险柜了密码改成了生日。", "corrected_sentence": "他把保险柜的密码改成了生日。", "error_description": "助词错误：修饰名词「密码」应用结构助词「的」，不能用「了」。正确句为「他把保险柜的密码改成了生日。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23594, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "偏私", "is_correct": true, "explanation": "正确：指不公正、偏袒某一方，与“公正”构成反义。"}, {"text": "迟缓", "is_correct": false, "explanation": "与“公正”没有反义关系，指动作或反应慢。"}, {"text": "沉重", "is_correct": false, "explanation": "与“公正”没有反义关系，指分量大或心情压抑。"}, {"text": "温暖", "is_correct": false, "explanation": "与“公正”没有反义关系，指有温度或让人感到亲切。"}], "correct_answer": "偏私", "explanations": {"偏私": "正确：指不公正、偏袒某一方，与“公正”构成反义。", "迟缓": "与“公正”没有反义关系，指动作或反应慢。", "沉重": "与“公正”没有反义关系，指分量大或心情压抑。", "温暖": "与“公正”没有反义关系，指有温度或让人感到亲切。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23594, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "偏私", "is_correct": true, "explanation": "正确：指不公正、偏袒某一方，与“公正”构成反义。"}, {"text": "柔和", "is_correct": false, "explanation": "与“公正”没有反义关系，指性质温和、不刺激。"}, {"text": "热闹", "is_correct": false, "explanation": "与“公正”没有反义关系，指人多、声音大、气氛活跃。"}, {"text": "繁忙", "is_correct": false, "explanation": "与“公正”没有反义关系，指事情多、忙碌。"}], "correct_answer": "偏私", "explanations": {"偏私": "正确：指不公正、偏袒某一方，与“公正”构成反义。", "柔和": "与“公正”没有反义关系，指性质温和、不刺激。", "热闹": "与“公正”没有反义关系，指人多、声音大、气氛活跃。", "繁忙": "与“公正”没有反义关系，指事情多、忙碌。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23594, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对每个人都一样，不偏向谁。", "primary_collocate": null, "pronunciation": "gōng zhèng", "ipa": "kʊŋ˥ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈分苹果很公正，每人一个。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判公正，两队都服气。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个公正的人，不会帮自己的朋友。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板对新人和老人一样公正。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你公正地说说，谁做得对？", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的规则很公正。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班长公正地给大家排座位。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要找一个公正的人来判断。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是照顾自己的弟弟，谈不上公正。", "target_word": "公正", "complexity_tier": "T3", "furigana": "tā zǒngshì zhàogù zìjǐ de dìdi, tán bu shàng gōngzhèng.", "sentence_source": "generated"}, {"text": "大家都说这位老师最公正。", "target_word": "公正", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不公正", "label": "复合"}, {"form": "公正性", "label": "复合"}], "register": "书面", "sense_fingerprint": "对每个人都一样，不偏向任何一方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d73da08-f1e3-4736-83d2-b9a3a45c59eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23594, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "公正", "is_correct": true, "explanation": "正确：对每个人都一样，不偏向谁。"}, {"text": "工整", "is_correct": false, "explanation": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是整齐、规范。"}, {"text": "更正", "is_correct": false, "explanation": "gēng 与 gōng 韵母不同（-eng 与 -ong），意思是改正错误。"}, {"text": "公章", "is_correct": false, "explanation": "zhāng（第一声）与 zhèng（第四声）韵母和声调都不同，意思是公用的印章。"}, {"text": "工长", "is_correct": false, "explanation": "zhǎng（第三声）与 zhèng（第四声）韵母和声调不同，意思是工地上的领班。"}], "explanations": {"公正": "正确：对每个人都一样，不偏向谁。", "工整": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是整齐、规范。", "更正": "gēng 与 gōng 韵母不同（-eng 与 -ong），意思是改正错误。", "公章": "zhāng（第一声）与 zhèng（第四声）韵母和声调都不同，意思是公用的印章。", "工长": "zhǎng（第三声）与 zhèng（第四声）韵母和声调不同，意思是工地上的领班。"}, "sentence_index": null, "correct_answer": "公正"}, "level_3": {"options": [{"text": "公正", "is_correct": true, "explanation": "正确：对每个人一视同仁，与“每人一个”的平均分配相符。"}, {"text": "偏心", "is_correct": false, "explanation": "语义：“偏心”指偏向一方，与“每人一个”的平均分配矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容体形，不能用来描述分苹果的做法。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不能用来修饰“分苹果”。"}], "explanations": {"公正": "正确：对每个人一视同仁，与“每人一个”的平均分配相符。", "偏心": "语义：“偏心”指偏向一方，与“每人一个”的平均分配矛盾。", "高大": "体貌：“高大”形容体形，不能用来描述分苹果的做法。", "响亮": "搭配：“响亮”形容声音，不能用来修饰“分苹果”。"}, "sentence_index": 0, "correct_answer": "公正"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题解释得很公正。", "explanation": "这里应该用〈清楚〉。公正用于人、裁决和制度，讲解明白要说〈清楚〉。"}, {"text": "房间打扫得很公正。", "explanation": "这里应该用〈干净〉。公正不用来形容清洁程度，要说〈干净〉。"}, {"text": "他学习很公正，成绩很好。", "explanation": "这里应该用〈刻苦〉。公正指对人一视同仁，学习的努力程度要说〈刻苦〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23594, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公正", "is_correct": true, "explanation": "正确：形容“排”的方式，指一视同仁地安排。"}, {"text": "流利", "is_correct": false, "explanation": "搭配：“流利”形容说话或读写顺畅，不用来修饰“排座位”。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”是情绪，不能用来形容班长安排座位的方式。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能用来修饰“排座位”。"}], "explanations": {"公正": "正确：形容“排”的方式，指一视同仁地安排。", "流利": "搭配：“流利”形容说话或读写顺畅，不用来修饰“排座位”。", "悲伤": "语义：“悲伤”是情绪，不能用来形容班长安排座位的方式。", "清脆": "搭配：“清脆”形容声音，不能用来修饰“排座位”。"}, "sentence_index": 6, "correct_answer": "公正"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子很公正，窗户很大。", "explanation": "这里应该用〈明亮〉。公正用于人、裁决和制度，形容光线要说〈明亮〉。"}, {"text": "这个蛋糕很公正，大家都爱吃。", "explanation": "这里应该用〈甜〉。公正不用来形容味道，形容蛋糕的味道要说〈甜〉。"}, {"text": "湖边的小镇很公正。", "explanation": "这里应该用〈宁静〉。公正不用来形容地方的环境，形容小镇的安静要说〈宁静〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师公正的批改了作业。", "corrected_sentence": "老师公正地批改了作业。", "error_description": "“公正”在句中修饰动词“批改”，作状语应用“地”，不用“的”：应说“公正地批改”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种做法公正，大家都很失望。", "corrected_sentence": "这种做法不公正，大家都很失望。", "error_description": "语义矛盾：“公正”是肯定评价，与后句“大家都很失望”不符，应在“公正”前加“不”，说“不公正”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
