INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23596, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地图是一张纸，上面画着城市、道路和河流，告诉我们怎么去想去的地方。", "primary_collocate": null, "pronunciation": "dì tú", "ipa": "ti˥˩ tʰu˧˥", "syllable_count": 2, "sentences": [{"text": "爸爸买了一张新地图。", "target_word": "地图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张地图是纸做的。", "target_word": "地图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上画着一条长长的河。", "target_word": "地图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们看着地图，找到了公园。", "target_word": "地图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上哪里是我们的学校？", "target_word": "地图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把地图叠好，放进包里。", "target_word": "地图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有地图，我们会走错路。", "target_word": "地图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上有山、有河，还有城市。", "target_word": "地图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那张旧地图已经破了。", "target_word": "地图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用笔在地图上画出路。", "target_word": "地图", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "纸地图", "label": "复合词"}, {"form": "旅游地图", "label": "复合词"}], "register": "中性", "sense_fingerprint": "画着城市、道路和河流、帮人找路的纸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '075e48bb-16bc-4c85-a794-089c95f7240f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23596, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地图", "is_correct": true, "explanation": "地图：纸上画着城市和道路，可以买，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能买，买了一张新空气，句意不通。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：梦想不是可以买的东西，句意不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：钥匙用“把”来量，不用“张”，量词搭配不当。"}], "explanations": {"地图": "地图：纸上画着城市和道路，可以买，符合句意。", "空气": "语义：空气不能买，买了一张新空气，句意不通。", "梦想": "语义：梦想不是可以买的东西，句意不通。", "钥匙": "搭配：钥匙用“把”来量，不用“张”，量词搭配不当。"}, "sentence_index": 0, "correct_answer": "地图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的地图是北京市朝阳区。", "explanation": "这里应该用〈地址〉。地图是纸上画的图，不是住址。"}, {"text": "他翻着地图，把饭做好了。", "explanation": "这里应该用〈食谱〉。做饭要看食谱，地图不讲做菜。"}, {"text": "我们看着地图，查到了这个字。", "explanation": "这里应该用〈字典〉。查字要用字典，地图不收字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23596, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地图", "is_correct": true, "explanation": "地图：没有它就会走错路，符合句意。"}, {"text": "水", "is_correct": false, "explanation": "语义：水与找路无关，没有水不会导致走错路，句意不通。"}, {"text": "钱", "is_correct": false, "explanation": "语义：钱与找路无关，没有钱不会导致走错路，句意不通。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“没有作业”与“走错路”不搭配，作业与找路没有关系。"}], "explanations": {"地图": "地图：没有它就会走错路，符合句意。", "水": "语义：水与找路无关，没有水不会导致走错路，句意不通。", "钱": "语义：钱与找路无关，没有钱不会导致走错路，句意不通。", "作业": "搭配：“没有作业”与“走错路”不搭配，作业与找路没有关系。"}, "sentence_index": 6, "correct_answer": "地图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把地图吃完了，然后出门。", "explanation": "这里应该用〈饼〉。地图是纸，不能吃，吃的应是食物。"}, {"text": "她在舞台上唱地图。", "explanation": "这里应该用〈歌〉。唱的是歌，地图不能唱。"}, {"text": "我们在操场上踢地图。", "explanation": "这里应该用〈足球〉。踢的是球，地图不是球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在地图找到了火车站。", "corrected_sentence": "他在地图上找到了火车站。", "error_description": "表示在纸上的地图里找到，“地图”后要加方位词“上”，应说“在地图上”。错误在于省略了“上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23596, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他丢了一只地图。", "corrected_sentence": "他丢了一张地图。", "error_description": "“地图”是纸张，应该用量词“张”，“只”用于动物或成对的东西。错误在于量词“只”，正确形式是“一张地图”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
