INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23598, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做自己喜欢的事情来开心。", "primary_collocate": null, "pronunciation": "wán", "ipa": "wan˧˥", "syllable_count": 1, "sentences": [{"text": "周末我和朋友去公园玩。", "target_word": "玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在院子里玩得很开心。", "target_word": "玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢玩电脑游戏。", "target_word": "玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你昨天晚上玩了什么游戏？", "target_word": "玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在草地上玩球，跑来跑去。", "target_word": "玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去海边玩了三天。", "target_word": "玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，作业写完才能出去玩。", "target_word": "玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们玩着玩着，就大声笑起来了。", "target_word": "玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没有玩过滑冰。", "target_word": "玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天天气好，我们去山上玩吧。", "target_word": "玩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "玩了", "label": "完成体"}, {"form": "玩着", "label": "进行体"}, {"form": "玩过", "label": "经历体"}, {"form": "玩玩", "label": "重叠"}, {"form": "玩儿", "label": "儿化"}, {"form": "玩具", "label": "复合词"}], "register": "口语", "sense_fingerprint": "为了开心而游戏、娱乐或消遣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebd53f51-cdf0-46b6-96dd-99270f958475') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23598, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "玩", "is_correct": true, "explanation": "正确。玩（wán）表示为了开心而游戏、消遣。"}, {"text": "碗", "is_correct": false, "explanation": "wǎn（第三声）与 wán（第二声）声调不同，意思是盛饭菜的器具。"}, {"text": "王", "is_correct": false, "explanation": "wáng 与 wán 韵母不同（-ang 与 -an），意思是国王。"}, {"text": "万", "is_correct": false, "explanation": "wàn（第四声）与 wán（第二声）声调不同，意思是数目“一万”。"}, {"text": "文", "is_correct": false, "explanation": "wén 与 wán 韵母不同（-en 与 -an），意思是文字、文章。"}, {"text": "湾", "is_correct": false, "explanation": "wān（第一声）与 wán（第二声）声调不同，意思是海湾、河湾。"}], "explanations": {"玩": "正确。玩（wán）表示为了开心而游戏、消遣。", "碗": "wǎn（第三声）与 wán（第二声）声调不同，意思是盛饭菜的器具。", "王": "wáng 与 wán 韵母不同（-ang 与 -an），意思是国王。", "万": "wàn（第四声）与 wán（第二声）声调不同，意思是数目“一万”。", "文": "wén 与 wán 韵母不同（-en 与 -an），意思是文字、文章。", "湾": "wān（第一声）与 wán（第二声）声调不同，意思是海湾、河湾。"}, "sentence_index": null, "correct_answer": "玩"}, "level_3": {"options": [{"text": "玩", "is_correct": true, "explanation": "正确。“去公园”之后，玩表示为了开心而游戏。"}, {"text": "上班", "is_correct": false, "explanation": "语义：周末去公园不能说“去公园上班”，与“和朋友”的语境不合。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”不是去公园能做的事，与周末外出游玩的语境不合。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”需要带修理的对象，这里缺少宾语，句子不成立。"}], "explanations": {"玩": "正确。“去公园”之后，玩表示为了开心而游戏。", "上班": "语义：周末去公园不能说“去公园上班”，与“和朋友”的语境不合。", "考试": "语义：“考试”不是去公园能做的事，与周末外出游玩的语境不合。", "修理": "配价：“修理”需要带修理的对象，这里缺少宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "玩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们玩了这个问题。", "explanation": "这里应该用〈讨论〉。玩指为开心而做的事，讨论问题是认真的交流，不能说“玩问题”。"}, {"text": "医生在手术室里玩了三个小时。", "explanation": "这里应该用〈工作〉。玩指为开心而做的事，手术是严肃的工作，不能说“玩”。"}, {"text": "他玩了一笔大生意。", "explanation": "这里应该用〈做〉。玩指为开心而游戏，做生意是认真的事，要说“做生意”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e535a1-3d00-41a4-8a35-d6188aee7aa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23598, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "玩", "is_correct": true, "explanation": "正确。玩（wán）表示为了开心而游戏、消遣。"}, {"text": "晚", "is_correct": false, "explanation": "wǎn（第三声）与 wán（第二声）声调不同，意思是晚上。"}, {"text": "闻", "is_correct": false, "explanation": "wén 与 wán 韵母不同（-en 与 -an），意思是闻到、听到。"}, {"text": "弯", "is_correct": false, "explanation": "wān（第一声）与 wán（第二声）声调不同，意思是弯曲。"}], "explanations": {"玩": "正确。玩（wán）表示为了开心而游戏、消遣。", "晚": "wǎn（第三声）与 wán（第二声）声调不同，意思是晚上。", "闻": "wén 与 wán 韵母不同（-en 与 -an），意思是闻到、听到。", "弯": "wān（第一声）与 wán（第二声）声调不同，意思是弯曲。"}, "sentence_index": null, "correct_answer": "玩"}, "level_3": {"options": [{"text": "玩", "is_correct": true, "explanation": "正确。“才能出去”之后，玩表示孩子为了开心而游戏。"}, {"text": "洗", "is_correct": false, "explanation": "配价：“洗”需要带洗的对象，这里没有宾语，不能说“出去洗”。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“作业写完才能出去哭”与事理不符，“哭”不能用于这种条件。"}, {"text": "搬", "is_correct": false, "explanation": "配价：“搬”需要带搬运的对象，这里缺少宾语，句子不成立。"}], "explanations": {"玩": "正确。“才能出去”之后，玩表示孩子为了开心而游戏。", "洗": "配价：“洗”需要带洗的对象，这里没有宾语，不能说“出去洗”。", "哭": "语义：“作业写完才能出去哭”与事理不符，“哭”不能用于这种条件。", "搬": "配价：“搬”需要带搬运的对象，这里缺少宾语，句子不成立。"}, "sentence_index": 6, "correct_answer": "玩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我们去山上玩身体。", "explanation": "这里应该用〈锻炼〉。玩指为开心而做的事，锻炼身体不能说“玩身体”。"}, {"text": "妈妈在厨房里玩碗。", "explanation": "这里应该用〈洗〉。玩指为开心而做的事，洗碗是家务，不能说“玩碗”。"}, {"text": "学生们在教室里玩考试。", "explanation": "这里应该用〈考〉。玩指开心的游戏，考试是严肃的测验，不能说“玩考试”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e535a1-3d00-41a4-8a35-d6188aee7aa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们玩很高兴。", "corrected_sentence": "他们玩得很高兴。", "error_description": "补语标记缺失：“玩”后引出程度补语要用“得”。应说“玩得很高兴”，不能说“玩很高兴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e535a1-3d00-41a4-8a35-d6188aee7aa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在草地上玩了一个会儿。", "corrected_sentence": "我们在草地上玩了一会儿。", "error_description": "时量补语的量词错误：“一会儿”是固定的时量词，前面不能加量词“个”。应说“玩了一会儿”，不能说“玩了一个会儿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e535a1-3d00-41a4-8a35-d6188aee7aa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
