INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23604, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人或两队比一比谁更好。", "primary_collocate": null, "pronunciation": "bǐ sài", "ipa": "pi²¹⁴ saɪ⁵¹", "syllable_count": 2, "sentences": [{"text": "我和哥哥比赛跑步。", "target_word": "比赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们两队明天比赛足球。", "target_word": "比赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们比赛谁吃得快。", "target_word": "比赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱们比赛一下，看谁先到。", "target_word": "比赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在草地上比赛骑车。", "target_word": "比赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想和你比赛游泳。", "target_word": "比赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个班比赛唱歌，我们班赢了。", "target_word": "比赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们比赛了三次，每次都是小王赢。", "target_word": "比赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们来比赛写字吧。", "target_word": "比赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们正在比赛画画。", "target_word": "比赛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "比赛了", "label": "体标"}, {"form": "比赛过", "label": "体标"}, {"form": "比賽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比赛：动词，双方或两队比一比，看谁做得更好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20be542-fd2b-4af9-92a3-e1943594c231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23604, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比赛", "is_correct": true, "explanation": "正确：“比赛”表示双方比一比高下，与“跑步”的搭配相符。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”针对语言文字，不能带“跑步”作宾语。"}, {"text": "捐赠", "is_correct": false, "explanation": "搭配：“捐赠”指赠送财物，不能与“跑步”搭配。"}, {"text": "倾听", "is_correct": false, "explanation": "语义：“倾听”指听声音或意见，不能用于“跑步”这类动作。"}], "explanations": {"比赛": "正确：“比赛”表示双方比一比高下，与“跑步”的搭配相符。", "翻译": "搭配：“翻译”针对语言文字，不能带“跑步”作宾语。", "捐赠": "搭配：“捐赠”指赠送财物，不能与“跑步”搭配。", "倾听": "语义：“倾听”指听声音或意见，不能用于“跑步”这类动作。"}, "sentence_index": 0, "correct_answer": "比赛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们比赛两份报告的优缺点。", "explanation": "这里应该用〈比较〉。比赛指双方竞争高低，比较报告的优缺点不用“比赛”。"}, {"text": "他比赛了一次体检。", "explanation": "这里应该用〈做〉。比赛指两人或两队较量高下，体检不是竞争，要用“做”。"}, {"text": "他比赛班长。", "explanation": "这里应该用〈竞选〉。比赛指比较高低，选举班长要用“竞选”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23604, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比赛", "is_correct": true, "explanation": "正确：“比赛”表示双方较量，与“两个班唱歌，我们班赢了”的语境相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对器物，不能用于“唱歌”。"}, {"text": "清洗", "is_correct": false, "explanation": "搭配：“清洗”用于物品或衣物，不能用于“唱歌”。"}, {"text": "挽救", "is_correct": false, "explanation": "语义：“挽救”指使濒临失败或危险的事情转危为安，与“唱歌”的比较不合。"}], "explanations": {"比赛": "正确：“比赛”表示双方较量，与“两个班唱歌，我们班赢了”的语境相符。", "修理": "搭配：“修理”针对器物，不能用于“唱歌”。", "清洗": "搭配：“清洗”用于物品或衣物，不能用于“唱歌”。", "挽救": "语义：“挽救”指使濒临失败或危险的事情转危为安，与“唱歌”的比较不合。"}, "sentence_index": 6, "correct_answer": "比赛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师比赛了我的名字。", "explanation": "这里应该用〈点名〉。比赛指两人或两队较量高下，叫学生的名字要用“点名”。"}, {"text": "老师要比赛优秀学生。", "explanation": "这里应该用〈评选〉。比赛指双方较量，从众多人中挑选优秀学生要用“评选”。"}, {"text": "他在比赛合适的衣服。", "explanation": "这里应该用〈挑选〉。比赛指双方竞争，选购衣服要用“挑选”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23604, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和哥哥比赛了过跑步。", "corrected_sentence": "我和哥哥比赛过跑步。", "error_description": "错误：“比赛”后同时用了“了”和“过”，两个体标不能并用。正确：“比赛过跑步”，只保留“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23604, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班没比赛了唱歌。", "corrected_sentence": "我们班没比赛唱歌。", "error_description": "错误：“没”和“了”不能同时用在同一动词“比赛”上。正确：“我们班没比赛唱歌”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
