INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23606, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示可以做得到。", "primary_collocate": null, "pronunciation": "zú yǐ", "ipa": "tsu˧˥ i˨˩˦", "syllable_count": 2, "sentences": [{"text": "这点钱足以买一张车票。", "target_word": "足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的经验足以带好这个新团队。", "target_word": "足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个小时足以走到学校。", "target_word": "足以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些证据足以说明他没有说谎。", "target_word": "足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的努力足以让所有人佩服。", "target_word": "足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间足以住下五个人。", "target_word": "足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一点点雨水不足以解决问题。", "target_word": "足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的粮食足以吃到明年春天。", "target_word": "足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的成绩足以考上好大学。", "target_word": "足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张照片足以证明他来过这里。", "target_word": "足以", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不足以", "label": "否定形式"}], "register": "书面", "sense_fingerprint": "数量、条件、能力等已经够用，可以做到某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e791c86-9557-46be-af3d-f72d116cd67f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23606, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "渐渐", "is_correct": false, "explanation": "语义：“渐渐”表示逐步变化的过程，与“买一张车票”这种一次性行为矛盾。"}, {"text": "猛然", "is_correct": false, "explanation": "搭配：“猛然”表示突然发生，不能修饰“这点钱买车票”这样平稳的行为。"}, {"text": "足以", "is_correct": true, "explanation": "足以：表示数量、条件够用，这点钱可以买一张车票，符合句意。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续不断，与“买一张车票”的单次行为矛盾。"}], "explanations": {"渐渐": "语义：“渐渐”表示逐步变化的过程，与“买一张车票”这种一次性行为矛盾。", "猛然": "搭配：“猛然”表示突然发生，不能修饰“这点钱买车票”这样平稳的行为。", "足以": "足以：表示数量、条件够用，这点钱可以买一张车票，符合句意。", "一直": "语义：“一直”表示持续不断，与“买一张车票”的单次行为矛盾。"}, "sentence_index": 0, "correct_answer": "足以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你足以走了。", "explanation": "这里应该用〈可以〉。足以表示能力或条件够不够，表示允许离开要用“可以”，“足以走了”会被理解成“你有能力走”。"}, {"text": "这本书足以不错。", "explanation": "这里应该用〈很〉。足以表示条件够不够，后面不能直接接形容词；表示程度要用“很”。"}, {"text": "你足以早点休息。", "explanation": "这里应该用〈应该〉。足以表示条件够不够，表示建议要用“应该”，不能说“足以早点休息”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”修饰有意志的施事者，雨水不能“亲自”解决问题。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意为之，雨水没有意图，与句意不合。"}, {"text": "足以", "is_correct": true, "explanation": "足以：表示条件够不够，雨水不足以解决问题，符合句意。"}, {"text": "竭力", "is_correct": false, "explanation": "语义：“竭力”表示尽全力，雨水不能竭力行事，与句意不合。"}], "explanations": {"亲自": "搭配：“亲自”修饰有意志的施事者，雨水不能“亲自”解决问题。", "故意": "语义：“故意”表示有意为之，雨水没有意图，与句意不合。", "足以": "足以：表示条件够不够，雨水不足以解决问题，符合句意。", "竭力": "语义：“竭力”表示尽全力，雨水不能竭力行事，与句意不合。"}, "sentence_index": 6, "correct_answer": "足以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他足以来过这里。", "explanation": "这里应该用〈可能〉。足以表示条件够用，推测“来过这里”要用“可能”。"}, {"text": "我足以希望你明天能来。", "explanation": "这里应该用〈希望〉。足以表示条件够不够，表达愿望要用“希望”，不能说“足以希望”。"}, {"text": "他足以不太舒服。", "explanation": "这里应该用〈好像〉。足以表示条件够不够，表示推测“他不太舒服”要用“好像”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23606, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些零钱很足以买一瓶水。", "corrected_sentence": "这些零钱足以买一瓶水。", "error_description": "副词错误：“足以”本身是副词，不能再被“很”修饰；应去掉“很”，说“这些零钱足以买一瓶水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23606, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这么小的火没足以烧毁整座房子。", "corrected_sentence": "这么小的火不足以烧毁整座房子。", "error_description": "错误：否定“足以”要用否定副词“不”，说“不足以”，不能用“没”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
