INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23610, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地面上的、让人或车走的长条形地方。", "primary_collocate": null, "pronunciation": "lù", "ipa": "lu˥˩", "syllable_count": 1, "sentences": [{"text": "这条路通向山上。", "target_word": "路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上没有车，很安静。", "target_word": "路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着这条路一直往前走。", "target_word": "路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路上有很多人。", "target_word": "路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在路中间停下来看手机。", "target_word": "路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人慢慢走过那条路。", "target_word": "路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新修的路又宽又平。", "target_word": "路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路晚上没有灯，很黑。", "target_word": "路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的路被大雪盖住了。", "target_word": "路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把车停在路的左边。", "target_word": "路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条路", "label": "量词"}, {"form": "马路", "label": "复合词"}, {"form": "公路", "label": "复合词"}, {"form": "路口", "label": "复合词"}], "register": "中性", "sense_fingerprint": "地面上让人或车通行的长条形地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb44a393-77f6-42c1-bc0b-0d5ca4c2aee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23610, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "路", "is_correct": true, "explanation": "lù（第四声）指地面上让人或车走的长条形地方。"}, {"text": "怒", "is_correct": false, "explanation": "nù 与 lù 声母不同（n 与 l），意思是愤怒。"}, {"text": "炉", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，意思是炉子。"}, {"text": "芦", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，意思是芦苇。"}, {"text": "绿", "is_correct": false, "explanation": "lǜ 与 lù 韵母不同（ü 与 u），意思是绿色。"}], "explanations": {"路": "lù（第四声）指地面上让人或车走的长条形地方。", "怒": "nù 与 lù 声母不同（n 与 l），意思是愤怒。", "炉": "lú（第二声）与 lù（第四声）声调不同，意思是炉子。", "芦": "lú（第二声）与 lù（第四声）声调不同，意思是芦苇。", "绿": "lǜ 与 lù 韵母不同（ü 与 u），意思是绿色。"}, "sentence_index": null, "correct_answer": "路"}, "level_3": {"options": [{"text": "路", "is_correct": true, "explanation": "路与“通向山上”搭配，指地面上供人或车通行的道路。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间是室内空间，不能“通向山上”。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“这条”用于长条形的东西，桌子应用“张”计量，而且桌子也不能“通向山上”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不是地面的通道，不能“通向山上”。"}], "explanations": {"路": "路与“通向山上”搭配，指地面上供人或车通行的道路。", "房间": "语义：房间是室内空间，不能“通向山上”。", "桌子": "搭配：“这条”用于长条形的东西，桌子应用“张”计量，而且桌子也不能“通向山上”。", "声音": "语义：声音不是地面的通道，不能“通向山上”。"}, "sentence_index": 0, "correct_answer": "路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在一张路上走了很久。", "explanation": "这里应该用〈条〉。“张”用于桌子、纸等平面的东西，不用于路。"}, {"text": "门前有一幅路，通向村子。", "explanation": "这里应该用〈条〉。“幅”用于画、布等平面的东西，不用于路。"}, {"text": "他沿着一把路往前走。", "explanation": "这里应该用〈条〉。“把”用于有柄的器具、椅子等，不用于路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8044f56-a0a3-4482-810e-7650c80647ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23610, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "路", "is_correct": true, "explanation": "lù（第四声）指地面上让人或车走的长条形地方。"}, {"text": "罗", "is_correct": false, "explanation": "luó（第二声）与 lù（第四声）声调不同，意思是罗（如罗马）。"}, {"text": "螺", "is_correct": false, "explanation": "luó（第二声）与 lù（第四声）声调不同，意思是螺（如螺丝）。"}, {"text": "骡", "is_correct": false, "explanation": "luó（第二声）与 lù（第四声）声调不同，意思是骡子。"}, {"text": "鲁", "is_correct": false, "explanation": "lǔ（第三声）与 lù（第四声）声调不同，意思是鲁（山东的别称）。"}], "explanations": {"路": "lù（第四声）指地面上让人或车走的长条形地方。", "罗": "luó（第二声）与 lù（第四声）声调不同，意思是罗（如罗马）。", "螺": "luó（第二声）与 lù（第四声）声调不同，意思是螺（如螺丝）。", "骡": "luó（第二声）与 lù（第四声）声调不同，意思是骡子。", "鲁": "lǔ（第三声）与 lù（第四声）声调不同，意思是鲁（山东的别称）。"}, "sentence_index": null, "correct_answer": "路"}, "level_3": {"options": [{"text": "路", "is_correct": true, "explanation": "路可以“新修”，也能“又宽又平”，符合句子的描述。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“新修的”用于修建的东西，饭不能说“新修”。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛不能“又宽又平”，与句子描述的对象不符。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“修”用于路、房屋等建造物，不说“修书”。"}], "explanations": {"路": "路可以“新修”，也能“又宽又平”，符合句子的描述。", "饭": "搭配：“新修的”用于修建的东西，饭不能说“新修”。", "眼睛": "语义：眼睛不能“又宽又平”，与句子描述的对象不符。", "书": "搭配：“修”用于路、房屋等建造物，不说“修书”。"}, "sentence_index": 6, "correct_answer": "路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只路很长，我们走了很久。", "explanation": "这里应该用〈条〉。“只”用于动物或成对物品中的一个，不用于路。"}, {"text": "前面有一座路，通向山里。", "explanation": "这里应该用〈条〉。“座”用于山、桥、楼等大型固定的东西，不用于路。"}, {"text": "我们走过一颗路，走得很累。", "explanation": "这里应该用〈条〉。“颗”用于圆形或粒状的小东西，不用于路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8044f56-a0a3-4482-810e-7650c80647ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23610, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把路修了平。", "corrected_sentence": "我们把路修平了。", "error_description": "结果补语“平”应紧跟动词，说“修平了”，不说“修了平”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8044f56-a0a3-4482-810e-7650c80647ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23610, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们走了一条很长路。", "corrected_sentence": "我们走了一条很长的路。", "error_description": "定语“很长”修饰名词时要加结构助词“的”，应说“很长的路”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8044f56-a0a3-4482-810e-7650c80647ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
