INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23612, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做各种事情，注重做事的态度与方法。", "primary_collocate": null, "pronunciation": "zuò shì", "ipa": "tswo˥˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "做事之前，先想一想后果。", "target_word": "做事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他喜欢一个人做事，不爱麻烦别人。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做事不能只图快，要做好。", "target_word": "做事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别急，慢慢做事，不会错的。", "target_word": "做事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她做事总是先想后做。", "target_word": "做事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子小，不会做事，要多教他。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我现在心情不好，没法做事。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饱饭才有力气做事。", "target_word": "做事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他边听音乐边做事，效率很高。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做事要诚实，对人要有礼貌。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "做了事", "label": "体标（了）"}, {"form": "做过事", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "做事：做各种事情，强调做事的态度与方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94fd5d6a-ee47-45b7-8109-ed74731efdc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23612, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "做事", "is_correct": true, "explanation": "正确。做事指做各种事情，强调做事的态度与方法。"}, {"text": "错事", "is_correct": false, "explanation": "cuò（第四声）与 zuò 声母不同（c 与 z），意思是做错的事。"}, {"text": "作诗", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是写诗。"}, {"text": "坐实", "is_correct": false, "explanation": "shí（第二声）与 shì 声调不同，意思是证实、确定。"}], "explanations": {"做事": "正确。做事指做各种事情，强调做事的态度与方法。", "错事": "cuò（第四声）与 zuò 声母不同（c 与 z），意思是做错的事。", "作诗": "shī（第一声）与 shì（第四声）声调不同，意思是写诗。", "坐实": "shí（第二声）与 shì 声调不同，意思是证实、确定。"}, "sentence_index": null, "correct_answer": "做事"}, "level_3": {"options": [{"text": "做事", "is_correct": true, "explanation": "正确。“做事之前，先想一想后果”指行动前要先考虑结果。"}, {"text": "打喷嚏", "is_correct": false, "explanation": "语义：打喷嚏是不由自主的反应，之前无法有意识地“先想一想后果”，句意不通。"}, {"text": "打哈欠", "is_correct": false, "explanation": "语义：打哈欠之前不需要想“后果”，句意不通。"}, {"text": "发呆", "is_correct": false, "explanation": "搭配：“发呆之前”后接“先想一想后果”，语义矛盾。"}], "explanations": {"做事": "正确。“做事之前，先想一想后果”指行动前要先考虑结果。", "打喷嚏": "语义：打喷嚏是不由自主的反应，之前无法有意识地“先想一想后果”，句意不通。", "打哈欠": "语义：打哈欠之前不需要想“后果”，句意不通。", "发呆": "搭配：“发呆之前”后接“先想一想后果”，语义矛盾。"}, "sentence_index": 0, "correct_answer": "做事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头做事很认真，从来不偷懒。", "explanation": "这里不能用〈做事〉。“做事”的主语须是人，石头不能做事。"}, {"text": "他做事了一张桌子，很结实。", "explanation": "这里应该用〈做〉。“做事”不能带“一张桌子”这类具体物件作宾语，应说“做了一张桌子”。"}, {"text": "这把椅子做事很稳，坐上去很舒服。", "explanation": "这里不能用〈做事〉。“做事”的主语须是人，椅子不能做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23612, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做事", "is_correct": true, "explanation": "正确。“心情不好，没法做事”指因心情影响而无法工作或处理事情。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：心情不好不会导致“没法呼吸”这种生理困难，句意荒谬。"}, {"text": "生长", "is_correct": false, "explanation": "语义：“生长”指生物的成长过程，与“心情不好”的原因无关。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：“没法出生”不是可以因心情而受影响的行为，搭配不成立。"}], "explanations": {"做事": "正确。“心情不好，没法做事”指因心情影响而无法工作或处理事情。", "呼吸": "语义：心情不好不会导致“没法呼吸”这种生理困难，句意荒谬。", "生长": "语义：“生长”指生物的成长过程，与“心情不好”的原因无关。", "出生": "搭配：“没法出生”不是可以因心情而受影响的行为，搭配不成立。"}, "sentence_index": 6, "correct_answer": "做事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥做事很稳，车来车往也不晃。", "explanation": "这里不能用〈做事〉。“做事”的主语须是人，桥不能做事。"}, {"text": "他做事了一锅饭，香极了。", "explanation": "这里应该用〈做〉。“做事”不能带“一锅饭”作宾语，应说“做了一锅饭”。"}, {"text": "这个灯泡做事很亮，照得屋里一片明亮。", "explanation": "这里不能用〈做事〉。“做事”的主语须是人，灯泡不能做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23612, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈正在厨房里做了事，忙个不停。", "corrected_sentence": "妈妈正在厨房里做事，忙个不停。", "error_description": "“做事”的“了”位置错误。“正在……”表示进行中，不能接“了”，应说“正在厨房里做事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23612, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他做事得很快，大家都夸他。", "corrected_sentence": "他做事做得很快，大家都夸他。", "error_description": "补语结构错误。“做事”后的补语要用“做得……”，缺少“做”会使句子不通，应说“做事做得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23614, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赢", "is_correct": true, "explanation": "“赢”与“输”在比赛胜负上正好相对，是反义词。"}, {"text": "写", "is_correct": false, "explanation": "“写”指书写文字，与“输”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”指发出歌声，与“输”没有反义关系。"}, {"text": "走", "is_correct": false, "explanation": "“走”指行走或离开，与“输”没有反义关系。"}], "correct_answer": "赢", "explanations": {"赢": "“赢”与“输”在比赛胜负上正好相对，是反义词。", "写": "“写”指书写文字，与“输”没有反义关系。", "唱": "“唱”指发出歌声，与“输”没有反义关系。", "走": "“走”指行走或离开，与“输”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23614, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赢", "is_correct": true, "explanation": "“赢”与“输”在比赛胜负上正好相对，是反义词。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”指把食物咽下，与“输”没有反义关系。"}, {"text": "读", "is_correct": false, "explanation": "“读”指看文字并发出声音，与“输”没有反义关系。"}, {"text": "跳", "is_correct": false, "explanation": "“跳”指身体向上离开地面，与“输”没有反义关系。"}], "correct_answer": "赢", "explanations": {"赢": "“赢”与“输”在比赛胜负上正好相对，是反义词。", "吃": "“吃”指把食物咽下，与“输”没有反义关系。", "读": "“读”指看文字并发出声音，与“输”没有反义关系。", "跳": "“跳”指身体向上离开地面，与“输”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23614, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比赛或游戏中，没有赢。", "primary_collocate": null, "pronunciation": "shū", "ipa": "ʂu˥", "syllable_count": 1, "sentences": [{"text": "我们队输了这场球。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他玩游戏总是输。", "target_word": "输", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明和我下棋，我输了。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟输了，哭了起来。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁输了谁请客。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这局游戏我又输了。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们打球从来不怕输。", "target_word": "输", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛结束了，红队输了。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "输了比赛，他一点也不生气。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他输给了班里最小的同学。", "target_word": "输", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "输了", "label": "体标（了）"}, {"form": "输过", "label": "体标（过）"}, {"form": "输掉", "label": "复合词"}, {"form": "输赢", "label": "复合词"}], "register": "通用", "sense_fingerprint": "比赛或游戏中没有赢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c6fe7c9-33e8-4c2f-b2e6-ccbf82b54954') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23614, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "输", "is_correct": true, "explanation": "shū（第一声），意思是比赛或游戏中没有赢，是正确答案。"}, {"text": "熟", "is_correct": false, "explanation": "shú（第二声）与 shū（第一声）声调不同，意思是熟悉或成熟。"}, {"text": "属", "is_correct": false, "explanation": "shǔ（第三声）与 shū（第一声）声调不同，意思是属于。"}, {"text": "树", "is_correct": false, "explanation": "shù（第四声）与 shū（第一声）声调不同，意思是树木。"}], "explanations": {"输": "shū（第一声），意思是比赛或游戏中没有赢，是正确答案。", "熟": "shú（第二声）与 shū（第一声）声调不同，意思是熟悉或成熟。", "属": "shǔ（第三声）与 shū（第一声）声调不同，意思是属于。", "树": "shù（第四声）与 shū（第一声）声调不同，意思是树木。"}, "sentence_index": null, "correct_answer": "输"}, "level_3": {"options": [{"text": "输", "is_correct": true, "explanation": "“输了这场球”表示这场比赛没有赢，符合句意。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”指使物体跌落或撞击，“摔了这场球”不能表示比赛的结果。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指丢弃，“扔了这场球”与比赛的语境不符。"}, {"text": "捡", "is_correct": false, "explanation": "语义：“捡”指拾取，“捡了这场球”不能表示比赛的结果。"}], "explanations": {"输": "“输了这场球”表示这场比赛没有赢，符合句意。", "摔": "语义：“摔”指使物体跌落或撞击，“摔了这场球”不能表示比赛的结果。", "扔": "语义：“扔”指丢弃，“扔了这场球”与比赛的语境不符。", "捡": "语义：“捡”指拾取，“捡了这场球”不能表示比赛的结果。"}, "sentence_index": 0, "correct_answer": "输"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "杯子输了，弟弟哭了起来。", "explanation": "这里应该用〈打碎〉。输用于比赛或游戏中的胜负，杯子摔碎要用打碎。"}, {"text": "气球输了，弟弟哭了起来。", "explanation": "这里应该用〈爆〉。输用于比赛、竞争中的胜负，气球破裂要用爆。"}, {"text": "书包输了，弟弟哭了起来。", "explanation": "这里应该用〈丢〉。输只用于比赛、竞争中的胜负，书包丢失要用丢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23614, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "输", "is_correct": true, "explanation": "shū（第一声），意思是比赛或游戏中没有赢，是正确答案。"}, {"text": "薯", "is_correct": false, "explanation": "shǔ（第三声）与 shū（第一声）声调不同，意思是薯类，如土豆、红薯。"}, {"text": "竖", "is_correct": false, "explanation": "shù（第四声）与 shū（第一声）声调不同，意思是竖直、直立。"}, {"text": "收", "is_correct": false, "explanation": "shōu（第一声）与 shū（第一声）声调相同，但韵母不同（ou 与 u），意思是收取。"}], "explanations": {"输": "shū（第一声），意思是比赛或游戏中没有赢，是正确答案。", "薯": "shǔ（第三声）与 shū（第一声）声调不同，意思是薯类，如土豆、红薯。", "竖": "shù（第四声）与 shū（第一声）声调不同，意思是竖直、直立。", "收": "shōu（第一声）与 shū（第一声）声调相同，但韵母不同（ou 与 u），意思是收取。"}, "sentence_index": null, "correct_answer": "输"}, "level_3": {"options": [{"text": "输", "is_correct": true, "explanation": "“从来不怕输”表示不怕失败，符合打球的语境。"}, {"text": "抱", "is_correct": false, "explanation": "语义：“抱”指用手臂环绕，“不怕抱”与打球的语境不符，句子说不通。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”不能与“怕”构成“不怕撕”这样的说法，不能表示对打球的态度。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”指用刀斧切断，“不怕砍”与打球的语境不符。"}], "explanations": {"输": "“从来不怕输”表示不怕失败，符合打球的语境。", "抱": "语义：“抱”指用手臂环绕，“不怕抱”与打球的语境不符，句子说不通。", "撕": "搭配：“撕”不能与“怕”构成“不怕撕”这样的说法，不能表示对打球的态度。", "砍": "语义：“砍”指用刀斧切断，“不怕砍”与打球的语境不符。"}, "sentence_index": 6, "correct_answer": "输"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只猫输了一只耳朵。", "explanation": "这里应该用〈掉〉。输用于比赛或游戏中的胜负，身体部位脱落要用掉。"}, {"text": "他因为生病输了视力。", "explanation": "这里应该用〈丧失〉。输用于比赛、竞争中的胜负，视力的丧失要用丧失。"}, {"text": "他输了信心，不想再练了。", "explanation": "这里应该用〈失去〉。输表示竞争中的失败，信心的失去要用失去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们队这次输了很惨。", "corrected_sentence": "我们队这次输得很惨。", "error_description": "错误形式“输了很惨”，正确形式“输得很惨”。“很惨”是补语，须用结构助词“得”引出，不能用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他输着三次比赛。", "corrected_sentence": "他输过三次比赛。", "error_description": "错误形式“输着三次比赛”，正确形式“输过三次比赛”。“着”表示状态的持续，描述已经发生过的经历要用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
