INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23616, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人或很多人想得到一样东西，就要努力比一比谁更好。", "primary_collocate": null, "pronunciation": "jìng zhēng", "ipa": "tɕiŋ⁵¹ ʈʂɤŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "三个人为第一名竞争。", "target_word": "竞争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两家公司正在为这个客户竞争。", "target_word": "竞争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们为一个机会竞争。", "target_word": "竞争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们不想和朋友竞争。", "target_word": "竞争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在市场上互相竞争。", "target_word": "竞争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小公司很难和大公司竞争。", "target_word": "竞争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个学生一直在竞争。", "target_word": "竞争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "三个同学都想竞争班长这个职位。", "target_word": "竞争", "complexity_tier": "T3", "furigana": "sān gè tóng xué dōu xiǎng jìng zhēng bān zhǎng zhè ge zhí wèi", "sentence_source": "generated"}, {"text": "我们公平地竞争，谁好谁赢。", "target_word": "竞争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她愿意和别人竞争这个机会。", "target_word": "竞争", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "竞争着", "label": "体标"}, {"form": "竞争了", "label": "体标"}, {"form": "竞争者", "label": "复合"}, {"form": "竞争力", "label": "复合"}, {"form": "競爭", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为了得到同一个目标而互相比较、争取", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c432fe6-4db2-4f87-8eb1-bd238a86f80d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23616, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "竞争", "is_correct": true, "explanation": "正确：“为第一名竞争”指为争取第一名而互相比较，符合句意。"}, {"text": "结婚", "is_correct": false, "explanation": "配价：“结婚”是不及物动词，不能接“为第一名”作目的对象。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与争取第一名的语境无关，句意不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是悠闲的活动，与争夺第一名的语义相反。"}], "explanations": {"竞争": "正确：“为第一名竞争”指为争取第一名而互相比较，符合句意。", "结婚": "配价：“结婚”是不及物动词，不能接“为第一名”作目的对象。", "睡觉": "语义：睡觉与争取第一名的语境无关，句意不通。", "散步": "语义：散步是悠闲的活动，与争夺第一名的语义相反。"}, "sentence_index": 0, "correct_answer": "竞争"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "士兵们在战场上竞争，保卫家乡。", "explanation": "这里应该用〈战斗〉。竞争指为争取同一目标而互相比较，不是武力对抗。"}, {"text": "我们在学校里竞争，帮助有困难的同学。", "explanation": "这里应该用〈合作〉。竞争是互相争取，不是共同完成事情。"}, {"text": "这两份报告我们竞争一下，看看有什么不同。", "explanation": "这里应该用〈比较〉。竞争指为争取同一目标而较量，核对两样东西的异同要用比较。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23616, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "竞争", "is_correct": true, "explanation": "正确：“一直在竞争”指两人持续互相争取，符合句意。"}, {"text": "下雪", "is_correct": false, "explanation": "配价：“下雪”是无施事动词，不能以“这两个学生”作主语。"}, {"text": "打雷", "is_correct": false, "explanation": "语义：打雷是自然现象，不能用来描述学生。"}, {"text": "扎根", "is_correct": false, "explanation": "语义：扎根指植物或思想深入，不能说学生“一直在扎根”。"}], "explanations": {"竞争": "正确：“一直在竞争”指两人持续互相争取，符合句意。", "下雪": "配价：“下雪”是无施事动词，不能以“这两个学生”作主语。", "打雷": "语义：打雷是自然现象，不能用来描述学生。", "扎根": "语义：扎根指植物或思想深入，不能说学生“一直在扎根”。"}, "sentence_index": 6, "correct_answer": "竞争"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们准备竞争老师，看看谁更厉害。", "explanation": "这里应该用〈比〉。竞争的对象是机会、职位等可争取的目标，不能把老师当作竞争对象；与人比试高下要用〈比〉。"}, {"text": "他决定竞争妈妈，要比她更努力。", "explanation": "这里应该用〈超过〉。竞争的对象是可争取的目标，不能是妈妈这样的亲人；想比她更好应说〈超过〉。"}, {"text": "这两个孩子在竞争朋友，谁也不让谁。", "explanation": "这里应该用〈交〉。竞争的对象是可争取的目标，朋友不能作为竞争的对象；交朋友要用〈交〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23616, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个人正在竞争了这个职位。", "corrected_sentence": "两个人正在竞争这个职位。", "error_description": "“正在……了”错误：“正在”表示动作进行，不能与表示完成的“了”同用，应去掉“了”，说“正在竞争这个职位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23616, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们竞争的很激烈，每个人都想赢。", "corrected_sentence": "他们竞争得很激烈，每个人都想赢。", "error_description": "“的”误用：表示动作程度的补语要用“得”，应为“竞争得很激烈”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23618, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "输", "is_correct": true, "explanation": "反义：“输”指比赛中未能胜过对手，与“赢”构成反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "无关：“吃”指进食，与“赢”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "无关：“唱”指歌唱，与“赢”没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "无关：“跑”指奔跑，与“赢”没有反义关系。"}], "correct_answer": "输", "explanations": {"输": "反义：“输”指比赛中未能胜过对手，与“赢”构成反义关系。", "吃": "无关：“吃”指进食，与“赢”没有反义关系。", "唱": "无关：“唱”指歌唱，与“赢”没有反义关系。", "跑": "无关：“跑”指奔跑，与“赢”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23618, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "输", "is_correct": true, "explanation": "反义：“输”指比赛中未能胜过对手，与“赢”构成反义关系。"}, {"text": "走", "is_correct": false, "explanation": "无关：“走”指行走，与“赢”没有反义关系。"}, {"text": "睡", "is_correct": false, "explanation": "无关：“睡”指睡觉，与“赢”没有反义关系。"}, {"text": "读", "is_correct": false, "explanation": "无关：“读”指阅读，与“赢”没有反义关系。"}], "correct_answer": "输", "explanations": {"输": "反义：“输”指比赛中未能胜过对手，与“赢”构成反义关系。", "走": "无关：“走”指行走，与“赢”没有反义关系。", "睡": "无关：“睡”指睡觉，与“赢”没有反义关系。", "读": "无关：“读”指阅读，与“赢”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23618, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在比赛或游戏中胜过对手，取得胜利。", "primary_collocate": null, "pronunciation": "yíng", "ipa": "iŋ˧˥", "syllable_count": 1, "sentences": [{"text": "昨天的篮球比赛，我们班赢了。", "target_word": "赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他下棋很厉害，每次都能赢。", "target_word": "赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和哥哥玩游戏，今天我赢了他两次。", "target_word": "赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个队赢了，哪个队就是第一名。", "target_word": "赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛太难了，我们不可能赢。", "target_word": "赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她赢过很多次跑步比赛。", "target_word": "赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们队以三比一赢了对手。", "target_word": "赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他玩牌总想赢，输了就不高兴。", "target_word": "赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁先到终点，谁就赢。", "target_word": "赢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然我没赢，但是我很开心。", "target_word": "赢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赢了", "label": "体标"}, {"form": "赢过", "label": "体标"}, {"form": "赢得", "label": "复合词"}, {"form": "赢家", "label": "复合词"}], "register": "中性", "sense_fingerprint": "在比赛或游戏中胜过对手，取得胜利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b36993-6be1-4beb-8bc2-c6c37fd0d0a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23618, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "影", "is_correct": false, "explanation": "yǐng（第三声）与 yíng（第二声）声调不同，意思是影子。"}, {"text": "赢", "is_correct": true, "explanation": "正确答案：yíng（第二声），意思是在比赛或游戏中胜过对手。"}, {"text": "硬", "is_correct": false, "explanation": "yìng（第四声）与 yíng（第二声）声调不同，意思是坚硬。"}, {"text": "银", "is_correct": false, "explanation": "yín 与 yíng 韵尾不同（n 与 ng），意思是银子。"}], "explanations": {"影": "yǐng（第三声）与 yíng（第二声）声调不同，意思是影子。", "赢": "正确答案：yíng（第二声），意思是在比赛或游戏中胜过对手。", "硬": "yìng（第四声）与 yíng（第二声）声调不同，意思是坚硬。", "银": "yín 与 yíng 韵尾不同（n 与 ng），意思是银子。"}, "sentence_index": null, "correct_answer": "赢"}, "level_3": {"options": [{"text": "跑", "is_correct": false, "explanation": "语义：“跑”指奔跑，与篮球比赛的胜负无关，无法说明“我们班”的结果。"}, {"text": "赢", "is_correct": true, "explanation": "正确：“赢”指在比赛中胜过对手，与“篮球比赛”和“我们班”的语境相符。"}, {"text": "踢", "is_correct": false, "explanation": "配价：“踢”是及物动词，需要“球”之类的宾语，“我们班踢了”缺少宾语，不能表示比赛结果。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指歌唱，与比赛的胜负无关。"}], "explanations": {"跑": "语义：“跑”指奔跑，与篮球比赛的胜负无关，无法说明“我们班”的结果。", "赢": "正确：“赢”指在比赛中胜过对手，与“篮球比赛”和“我们班”的语境相符。", "踢": "配价：“踢”是及物动词，需要“球”之类的宾语，“我们班踢了”缺少宾语，不能表示比赛结果。", "唱": "语义：“唱”指歌唱，与比赛的胜负无关。"}, "sentence_index": 0, "correct_answer": "赢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在公司工作，一个月赢了五千块。", "explanation": "这里应该用〈赚〉。“赢”用于比赛或游戏中取胜，工作挣钱要用“赚”。"}, {"text": "我们终于赢了困难。", "explanation": "这里应该用〈战胜〉。“赢”的对象是对手或比赛，克服困难要用“战胜”。"}, {"text": "这块蛋糕我赢了一半。", "explanation": "这里应该用〈吃〉。「赢」只用于比赛或游戏中取胜，吃东西要用「吃」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23618, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "英", "is_correct": false, "explanation": "yīng（第一声）与 yíng（第二声）声调不同，意思是英国、英雄。"}, {"text": "赢", "is_correct": true, "explanation": "正确答案：yíng（第二声），意思是在比赛或游戏中胜过对手。"}, {"text": "鹰", "is_correct": false, "explanation": "yīng（第一声）与 yíng（第二声）声调不同，意思是老鹰。"}, {"text": "应", "is_correct": false, "explanation": "yìng（第四声）与 yíng（第二声）声调不同，意思是回应、答复。"}], "explanations": {"英": "yīng（第一声）与 yíng（第二声）声调不同，意思是英国、英雄。", "赢": "正确答案：yíng（第二声），意思是在比赛或游戏中胜过对手。", "鹰": "yīng（第一声）与 yíng（第二声）声调不同，意思是老鹰。", "应": "yìng（第四声）与 yíng（第二声）声调不同，意思是回应、答复。"}, "sentence_index": null, "correct_answer": "赢"}, "level_3": {"options": [{"text": "输", "is_correct": false, "explanation": "配价：“输”不能直接带“对手”作宾语，应说“输给对手”，这里不成立。"}, {"text": "赢", "is_correct": true, "explanation": "正确：“赢”指胜过对手，与“以三比一”的比分和“对手”搭配。"}, {"text": "碰", "is_correct": false, "explanation": "语义：“碰”指接触，与“三比一”的比分无关，不能表示战胜。"}, {"text": "帮", "is_correct": false, "explanation": "语义：“帮”指帮助，与比赛的胜负矛盾，语境不通。"}], "explanations": {"输": "配价：“输”不能直接带“对手”作宾语，应说“输给对手”，这里不成立。", "赢": "正确：“赢”指胜过对手，与“以三比一”的比分和“对手”搭配。", "碰": "语义：“碰”指接触，与“三比一”的比分无关，不能表示战胜。", "帮": "语义：“帮”指帮助，与比赛的胜负矛盾，语境不通。"}, "sentence_index": 6, "correct_answer": "赢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这学期他赢了很多节课。", "explanation": "这里应该用〈上〉。「赢」用于胜过对手，上课要用「上」。"}, {"text": "我今天赢了一封信。", "explanation": "这里应该用〈收到〉。“赢”不用于收信，收到信件要用“收到”。"}, {"text": "这个月他的体重赢了三公斤。", "explanation": "这里应该用〈增加〉。“赢”用于比赛中胜出，体重增加要用“增加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23618, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们队以前赢了过几场比赛。", "corrected_sentence": "我们队以前赢过几场比赛。", "error_description": "错误：“赢了过”。正确：“赢过”。表示曾经有过的经历时，“过”已足够，不能同时加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23618, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次比赛我没赢了他。", "corrected_sentence": "这次比赛我没赢他。", "error_description": "错误：“没赢了”。正确：“没赢”。“没”否定已经发生的动作时，“赢”后不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
