INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23624, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "知道一个人或一样东西，以前见过或听说过；也指初次见面后彼此相识。", "primary_collocate": null, "pronunciation": "rèn shi", "ipa": "ʐən˥˩ ʂɨ", "syllable_count": 2, "sentences": [{"text": "你认识那位穿红衣服的老师吗？", "target_word": "认识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我认识他很多年了。", "target_word": "认识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很高兴认识你，请多关照。", "target_word": "认识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在北京认识了一个新朋友。", "target_word": "认识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是在大学里认识的。", "target_word": "认识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们认识过，只是很久没见了。", "target_word": "认识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在村里生活了几十年，认识每一户人家。", "target_word": "认识", "complexity_tier": "T3", "furigana": "rèn shi", "sentence_source": "generated"}, {"text": "你们俩是怎么认识的？", "target_word": "认识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不认识他，只在电视上见过。", "target_word": "认识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想认识一下你的同学。", "target_word": "认识", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "认识了", "label": "完成体"}, {"form": "认识过", "label": "经历体"}, {"form": "不认识", "label": "否定"}], "register": "通用", "sense_fingerprint": "因为见过或听说过而知道某人或某物，或初次见面后彼此相识", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebd53f51-cdf0-46b6-96dd-99270f958475') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23624, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "认识", "is_correct": true, "explanation": "认识：表示以前见过或听说过而知道某人，符合句意。"}, {"text": "买", "is_correct": false, "explanation": "语义：「买」的对象是东西，不能说买一位老师，句意不通。"}, {"text": "修", "is_correct": false, "explanation": "搭配：「修」用于修理物品，不能修理一位老师。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象必须是可以吃的东西，不能用于人。"}], "explanations": {"认识": "认识：表示以前见过或听说过而知道某人，符合句意。", "买": "语义：「买」的对象是东西，不能说买一位老师，句意不通。", "修": "搭配：「修」用于修理物品，不能修理一位老师。", "吃": "搭配：「吃」的对象必须是可以吃的东西，不能用于人。"}, "sentence_index": 0, "correct_answer": "认识"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我认识这个方案可行。", "explanation": "这里应该用〈认为〉。认识表示知道某人或某物，不能直接带小句表示看法；表示「觉得……」要用认为。"}, {"text": "我弟弟五岁就认识了游泳。", "explanation": "这里应该用〈学会〉。认识的对象是人或事物，不能说认识一项技能；学会技能要用学会。"}, {"text": "他已经认识了这项任务的一半。", "explanation": "这里应该用〈完成〉。认识指了解人或事物，不能表示做完一项任务；做完任务要用完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e535a1-3d00-41a4-8a35-d6188aee7aa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23624, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "认识", "is_correct": true, "explanation": "认识：表示长期生活中知道每一户人家，符合句意。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：「洗」的对象是衣物或身体，不能说洗人家。"}, {"text": "烧", "is_correct": false, "explanation": "语义：「烧」指烹煮或燃烧，用在这里句意不通。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：「摘」的对象是果实或花，不能说摘人家。"}], "explanations": {"认识": "认识：表示长期生活中知道每一户人家，符合句意。", "洗": "搭配：「洗」的对象是衣物或身体，不能说洗人家。", "烧": "语义：「烧」指烹煮或燃烧，用在这里句意不通。", "摘": "搭配：「摘」的对象是果实或花，不能说摘人家。"}, "sentence_index": 6, "correct_answer": "认识"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他认识了一场大地震。", "explanation": "这里应该用〈经历〉。认识的对象是人或事物，不能说认识一件事件；亲身遇到的事情要用经历。"}, {"text": "他认识了一份深厚的感情。", "explanation": "这里应该用〈培养〉。认识指了解人或事物，不能用来说产生感情；培养感情要用培养。"}, {"text": "他认识了我的请求。", "explanation": "这里应该用〈答应〉。认识指了解人或事物，不能用来表示同意别人的请求；同意请求要用答应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e535a1-3d00-41a4-8a35-d6188aee7aa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23624, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想认识了一下你的父母。", "corrected_sentence": "我想认识一下你的父母。", "error_description": "错误：「想」后面的「认识」不能加「了」。「想」表示打算或希望，应说「我想认识一下你的父母」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e535a1-3d00-41a4-8a35-d6188aee7aa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23624, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一下子认识不出他了。", "corrected_sentence": "我一下子认不出他了。", "error_description": "错误：「认识」后面不能接可能补语「不出」。辨认不出要说「认不出」，应说「我一下子认不出他了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e535a1-3d00-41a4-8a35-d6188aee7aa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23626, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱", "is_correct": true, "explanation": "正确：“弱”与“强”在力气或能力超过一般水平的意义上互为反义。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、分明，与“很强”无反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "“便宜”说价格，与“很强”无反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”说排列有序，与“很强”无反义关系。"}], "correct_answer": "弱", "explanations": {"弱": "正确：“弱”与“强”在力气或能力超过一般水平的意义上互为反义。", "清楚": "“清楚”形容明白、分明，与“很强”无反义关系。", "便宜": "“便宜”说价格，与“很强”无反义关系。", "整齐": "“整齐”说排列有序，与“很强”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a5d8731-1f49-491a-b49c-50d91d9928ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23626, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱", "is_correct": true, "explanation": "正确：“弱”与“强”在力气或能力超过一般水平的意义上互为反义。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”说速度，与“很强”无反义关系。"}, {"text": "亮", "is_correct": false, "explanation": "“亮”说光线，与“很强”无反义关系。"}, {"text": "甜", "is_correct": false, "explanation": "“甜”说味道，与“很强”无反义关系。"}], "correct_answer": "弱", "explanations": {"弱": "正确：“弱”与“强”在力气或能力超过一般水平的意义上互为反义。", "慢": "“慢”说速度，与“很强”无反义关系。", "亮": "“亮”说光线，与“很强”无反义关系。", "甜": "“甜”说味道，与“很强”无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a5d8731-1f49-491a-b49c-50d91d9928ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23626, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思是力气或能力非常大，比一般厉害。", "primary_collocate": null, "pronunciation": "hěn qiáng", "ipa": "xən˨˩ tɕʰjɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他的体力很强，跑十公里也不觉得累。", "target_word": "很强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥很强，三个人都打不过他。", "target_word": "很强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师的工作能力很强，同事都喜欢他。", "target_word": "很强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她游泳很强，拿过好几次第一。", "target_word": "很强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支球队很强，今年又赢了冠军。", "target_word": "很强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的适应能力很强，到哪里都能很快交朋友。", "target_word": "很强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎的力量很强，一下就能抓住小鹿。", "target_word": "很强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个战斗力很强的人，大家都想和他一组。", "target_word": "很强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的记忆力很强，看一遍就能记住。", "target_word": "很强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小男孩力量很强，一个人就搬起了椅子。", "target_word": "很强", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "很強", "label": "繁体"}], "register": "口语", "sense_fingerprint": "人或动物力气、本领大，比一般的更厉害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '490a1ea9-d1a0-48ef-b4b1-68de036f2317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23626, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "很强", "is_correct": true, "explanation": "正确答案：很强（hěn qiáng），形容力气或能力比一般的更厉害。"}, {"text": "很呛", "is_correct": false, "explanation": "qiàng（第四声）与 qiáng（第二声）声调不同，意思是很呛，形容气味刺鼻。"}, {"text": "很长", "is_correct": false, "explanation": "cháng 与 qiáng 声母不同（ch 与 q），意思是很长，形容距离或时间。"}, {"text": "很凉", "is_correct": false, "explanation": "liáng 与 qiáng 声母不同（l 与 q），意思是很凉，形容温度低。"}, {"text": "很穷", "is_correct": false, "explanation": "qióng 与 qiáng 韵母不同（ong 与 ang），意思是很穷，形容经济困难。"}], "explanations": {"很强": "正确答案：很强（hěn qiáng），形容力气或能力比一般的更厉害。", "很呛": "qiàng（第四声）与 qiáng（第二声）声调不同，意思是很呛，形容气味刺鼻。", "很长": "cháng 与 qiáng 声母不同（ch 与 q），意思是很长，形容距离或时间。", "很凉": "liáng 与 qiáng 声母不同（l 与 q），意思是很凉，形容温度低。", "很穷": "qióng 与 qiáng 韵母不同（ong 与 ang），意思是很穷，形容经济困难。"}, "sentence_index": null, "correct_answer": "很强"}, "level_3": {"options": [{"text": "很强", "is_correct": true, "explanation": "正确：很强形容体力超过一般水平，与“跑十公里也不觉得累”相合。"}, {"text": "很弱", "is_correct": false, "explanation": "语义：“很弱”与后文“跑十公里也不觉得累”的语境相反。"}, {"text": "很便宜", "is_correct": false, "explanation": "搭配：“便宜”说价格，不用来形容体力。"}, {"text": "很甜", "is_correct": false, "explanation": "搭配：“甜”说味道，不用来形容体力。"}], "explanations": {"很强": "正确：很强形容体力超过一般水平，与“跑十公里也不觉得累”相合。", "很弱": "语义：“很弱”与后文“跑十公里也不觉得累”的语境相反。", "很便宜": "搭配：“便宜”说价格，不用来形容体力。", "很甜": "搭配：“甜”说味道，不用来形容体力。"}, "sentence_index": 0, "correct_answer": "很强"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的个子很强，比同班同学都高。", "explanation": "这里应该用〈高〉。个子、身高要用“高”，“很强”只用于力气、能力等方面。"}, {"text": "这座城市的人口很强，每天都很热闹。", "explanation": "这里应该用〈多〉。人口是数量，要用“多”，“很强”不用于说数量。"}, {"text": "我家离车站很强，走路要半个小时。", "explanation": "这里应该用〈远〉。距离要用“远”，“很强”不用于说距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a5d8731-1f49-491a-b49c-50d91d9928ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23626, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很强", "is_correct": true, "explanation": "正确：很强形容力量超过一般水平，与“一下就能抓住小鹿”相合。"}, {"text": "很温柔", "is_correct": false, "explanation": "语义：“温柔”形容性情，不用来形容力量。"}, {"text": "很薄", "is_correct": false, "explanation": "搭配：“薄”说厚度，不用来形容力量。"}, {"text": "很干净", "is_correct": false, "explanation": "搭配：“干净”不用来形容力量。"}], "explanations": {"很强": "正确：很强形容力量超过一般水平，与“一下就能抓住小鹿”相合。", "很温柔": "语义：“温柔”形容性情，不用来形容力量。", "很薄": "搭配：“薄”说厚度，不用来形容力量。", "很干净": "搭配：“干净”不用来形容力量。"}, "sentence_index": 6, "correct_answer": "很强"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子很强，我一个人搬不动。", "explanation": "这里应该用〈重〉。箱子的重量要用“重”，“很强”不用于说重量。"}, {"text": "这次事故造成的损失很强，很多人受伤。", "explanation": "这里应该用〈严重〉。损失的程度要用“严重”，“很强”不用于说损失。"}, {"text": "从学校到公园的这条路很强，走了一个小时。", "explanation": "这里应该用〈长〉。路的长度要用“长”，“很强”不用于说长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a5d8731-1f49-491a-b49c-50d91d9928ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23626, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的很强体力，能一口气爬上五层楼。", "corrected_sentence": "他的体力很强，能一口气爬上五层楼。", "error_description": "「很强」为形容词性短语，不能直接修饰名词作定语；此处应说“体力很强”，不说“很强体力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a5d8731-1f49-491a-b49c-50d91d9928ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23626, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位大叔的臂力太很强，能一个人扛起两袋米。", "corrected_sentence": "这位大叔的臂力很强，能一个人扛起两袋米。", "error_description": "程度副词叠用：“太”和“很”都表示程度，不能同时修饰“强”。应说“很强”，不说“太很强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a5d8731-1f49-491a-b49c-50d91d9928ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
