INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23634, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种很奇怪的动物或东西。", "primary_collocate": null, "pronunciation": "guài wù", "ipa": "kwaɪ˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "湖里好像有一只大怪物，很多人都见过。", "target_word": "怪物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具是一只小怪物，有六条腿。", "target_word": "怪物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山洞里传来怪声，大家以为有怪物。", "target_word": "怪物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在海边看见一只怪物，马上跑回家。", "target_word": "怪物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会上，孩子们打扮成各种怪物。", "target_word": "怪物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里的怪物有大大的头和小小的身体。", "target_word": "怪物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只怪物不吃肉，只喝水。", "target_word": "怪物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，天上的云像一只大怪物。", "target_word": "怪物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说山里以前有怪物，可是没人见过。", "target_word": "怪物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天梦见了一个绿色的怪物。", "target_word": "怪物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "只", "label": "量词"}], "register": "口语", "sense_fingerprint": "样子很奇怪、让人害怕的动物或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '490a1ea9-d1a0-48ef-b4b1-68de036f2317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23634, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怪物", "is_correct": true, "explanation": "正确：怪物指一种很奇怪的动物或东西，与“湖里好像有一只大怪物”相合。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎不生活在湖里，“湖里好像有一只大老虎”与常识相反。"}, {"text": "熊猫", "is_correct": false, "explanation": "语义：熊猫不生活在湖里，与“很多人都见过”的语境不符。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：“大”与“小猫”自相矛盾，“一只大小猫”搭配不当。"}], "explanations": {"怪物": "正确：怪物指一种很奇怪的动物或东西，与“湖里好像有一只大怪物”相合。", "老虎": "语义：老虎不生活在湖里，“湖里好像有一只大老虎”与常识相反。", "熊猫": "语义：熊猫不生活在湖里，与“很多人都见过”的语境不符。", "小猫": "搭配：“大”与“小猫”自相矛盾，“一只大小猫”搭配不当。"}, "sentence_index": 0, "correct_answer": "怪物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗面条很香，我吃得很开心，它是一个怪物。", "explanation": "这里应该用〈美味〉。“怪物”指一种很奇怪的动物或东西，不能用来说好吃的面条；食物好吃要说“美味”。"}, {"text": "这本书讲的是一个小女孩的故事，她很善良，它是一个怪物。", "explanation": "这里应该用〈小说〉。“怪物”指一种很奇怪的动物或东西，不能用来说一本普通的故事书。"}, {"text": "窗外的花开得很漂亮，像一个怪物。", "explanation": "这里应该用〈蝴蝶〉。花开得漂亮可以比作“像蝴蝶”；“怪物”指很奇怪的动物或东西，不能比喻美丽的花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a5d8731-1f49-491a-b49c-50d91d9928ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23634, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怪物", "is_correct": true, "explanation": "正确：怪物指一种很奇怪的动物或东西，与“不吃肉，只喝水”相合。"}, {"text": "狼", "is_correct": false, "explanation": "语义：狼是肉食动物，“这只狼不吃肉”与常识相反。"}, {"text": "鳄鱼", "is_correct": false, "explanation": "语义：鳄鱼是肉食动物，“这只鳄鱼不吃肉”与常识相反。"}, {"text": "鲨鱼", "is_correct": false, "explanation": "语义：鲨鱼是肉食动物，“这只鲨鱼不吃肉”与常识相反。"}], "explanations": {"怪物": "正确：怪物指一种很奇怪的动物或东西，与“不吃肉，只喝水”相合。", "狼": "语义：狼是肉食动物，“这只狼不吃肉”与常识相反。", "鳄鱼": "语义：鳄鱼是肉食动物，“这只鳄鱼不吃肉”与常识相反。", "鲨鱼": "语义：鲨鱼是肉食动物，“这只鲨鱼不吃肉”与常识相反。"}, "sentence_index": 6, "correct_answer": "怪物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这封信写得很长，讲了很多事情，它是一个怪物。", "explanation": "这里应该用〈文章〉。“怪物”指一种很奇怪的动物或东西，不能用来说一封普通的信。"}, {"text": "这间教室打扫得很干净，大家都说它是一个怪物。", "explanation": "这里应该用〈整洁〉。“怪物”指一种很奇怪的动物或东西，不能用来形容打扫干净的教室。"}, {"text": "这条河的水很清，鱼在里面游来游去，它是一个怪物。", "explanation": "这里应该用〈小溪〉。“怪物”指一种很奇怪的动物或东西，不能用来说清澈平常的小河。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a5d8731-1f49-491a-b49c-50d91d9928ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖里有一本大怪物，把船都弄翻了。", "corrected_sentence": "湖里有一只大怪物，把船都弄翻了。", "error_description": "量词错误：“怪物”用量词“只”，“本”用于书籍，不能用于怪物，应说“一只大怪物”，不说“一本大怪物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a5d8731-1f49-491a-b49c-50d91d9928ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我弟弟说房间里有很怪物，其实是他的玩具。", "corrected_sentence": "我弟弟说房间里有一个怪物，其实是他的玩具。", "error_description": "程度副词误加：“很”只修饰形容词，不能修饰名词“怪物”。应说“有一个怪物”，不说“有很怪物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a5d8731-1f49-491a-b49c-50d91d9928ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
