INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23636, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在游戏或比赛中，把对方赢了。", "primary_collocate": null, "pronunciation": "dǎ bài", "ipa": "ta˨˩ pai̯˥˩", "syllable_count": 2, "sentences": [{"text": "昨天我在比赛中打败了他。", "target_word": "打败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟玩游戏时打败了我。", "target_word": "打败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班打败了二班，拿了第一。", "target_word": "打败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在棋赛中打败了老师。", "target_word": "打败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个队打败了去年的冠军。", "target_word": "打败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他练了一年，终于在乒乓球赛中打败了哥哥。", "target_word": "打败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在游戏里打败了最后的怪物。", "target_word": "打败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国队打败了日本队，进了决赛。", "target_word": "打败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李下棋时打败了爷爷。", "target_word": "打败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "红队打败蓝队，大家都很高兴。", "target_word": "打败", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打败了", "label": "体标"}, {"form": "打败过", "label": "体标"}, {"form": "打不败", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "在游戏或比赛中赢了对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '490a1ea9-d1a0-48ef-b4b1-68de036f2317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23636, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打败", "is_correct": true, "explanation": "正确：“昨天我在比赛中打败了他”指在比赛中赢了对方，符合句意。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：“打扮”不表示比赛中赢了对方，与“比赛中”的语境不符。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”的宾语须是文件，不能指人。"}, {"text": "打捞", "is_correct": false, "explanation": "配价：“打捞”指从水中取出物体，不能用于比赛中的人。"}], "explanations": {"打败": "正确：“昨天我在比赛中打败了他”指在比赛中赢了对方，符合句意。", "打扮": "语义：“打扮”不表示比赛中赢了对方，与“比赛中”的语境不符。", "打印": "搭配：“打印”的宾语须是文件，不能指人。", "打捞": "配价：“打捞”指从水中取出物体，不能用于比赛中的人。"}, "sentence_index": 0, "correct_answer": "打败"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他打败了这盘棋。", "explanation": "这里应该用〈赢〉。棋局可以说赢，“打败”的对象须是对手，不能是“这盘棋”。"}, {"text": "我们打败了这场考试。", "explanation": "这里应该用〈通过〉。考试要说通过，“打败”的对象须是对手，不能用于考试。"}, {"text": "这次比赛我们打败了好成绩。", "explanation": "这里应该用〈取得〉。成绩要说取得，“打败”的对象须是对手，不能用于成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a5d8731-1f49-491a-b49c-50d91d9928ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23636, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打败", "is_correct": true, "explanation": "正确：“在游戏里打败了最后的怪物”指在游戏中战胜对手，符合句意。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清理场地，与战胜怪物无关。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”指弄破物体，不能用来表示在游戏中的战胜。"}, {"text": "打开", "is_correct": false, "explanation": "配价：“打开”的宾语须是可以开启的物体，怪物不能被打开。"}], "explanations": {"打败": "正确：“在游戏里打败了最后的怪物”指在游戏中战胜对手，符合句意。", "打扫": "语义：“打扫”指清理场地，与战胜怪物无关。", "打碎": "语义：“打碎”指弄破物体，不能用来表示在游戏中的战胜。", "打开": "配价：“打开”的宾语须是可以开启的物体，怪物不能被打开。"}, "sentence_index": 6, "correct_answer": "打败"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在教室里打败了一块黑板。", "explanation": "这里应该用〈擦〉。擦黑板要用擦，“打败”的对象须是对手，不能用于黑板。"}, {"text": "他把一袋大米打败了。", "explanation": "这里应该用〈搬〉。搬大米要用搬，“打败”的对象须是对手，不能用于大米。"}, {"text": "弟弟在操场上打败了那个篮球。", "explanation": "这里应该用〈投〉。投篮要用投，“打败”的对象须是对手，不能用于篮球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a5d8731-1f49-491a-b49c-50d91d9928ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23636, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在上周的棋赛中打败着了表哥。", "corrected_sentence": "我在上周的棋赛中打败了表哥。", "error_description": "错误在于体标的叠用。“着”表示动作持续，“了”表示完成，二者不能同时用在“打败”之后，写成“打败着了”是错误。正确形式是“打败了表哥”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a5d8731-1f49-491a-b49c-50d91d9928ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23636, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们打败的很轻松。", "corrected_sentence": "他们打败得很轻松。", "error_description": "错误在于补语标记。表示动作程度的补语要用结构助词“得”，写成“的”是常见错误。正确形式是“打败得很轻松”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a5d8731-1f49-491a-b49c-50d91d9928ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
