INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23648, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "旗帜就是一块布，上面有特别的图案或颜色，代表一个国家、一个团体或一个想法。", "primary_collocate": null, "pronunciation": "qí zhì", "ipa": "tɕʰi˧˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "每个国家都有自己的旗帜。", "target_word": "旗帜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这面旗帜上有一颗黄色的星星。", "target_word": "旗帜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学校的旗帜是蓝色的，上面有一只鸟。", "target_word": "旗帜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到红色的旗帜，我就想起了自己的国家。", "target_word": "旗帜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个团体的旗帜上画着一棵绿色的树。", "target_word": "旗帜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旗帜折好，放进了盒子里。", "target_word": "旗帜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旗帜的颜色和图案都有特别的意思。", "target_word": "旗帜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游行的人举着旗帜，表达他们的想法。", "target_word": "旗帜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开幕式上，各国旗帜在体育馆里飘着。", "target_word": "旗帜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了不同国家的旗帜。", "target_word": "旗帜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "面", "label": "量词"}, {"form": "旗幟", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有图案或颜色、代表国家团体或想法的一块布", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de44d6c8-b05c-487d-a0c5-03c2d609f7fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23648, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "旗帜", "is_correct": true, "explanation": "正确答案：旗帜（qí zhì），指有图案或颜色、代表国家或团体的布。"}, {"text": "骑士", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），声调相同，意思是骑士，不是旗帜。"}, {"text": "气质", "is_correct": false, "explanation": "qì（第四声）与 qí（第二声）声调不同，意思是气质，不是旗帜。"}, {"text": "起止", "is_correct": false, "explanation": "qǐ 与 qí 声调不同，zhǐ 与 zhì 声调也不同，意思是起点和终点，不是旗帜。"}], "explanations": {"旗帜": "正确答案：旗帜（qí zhì），指有图案或颜色、代表国家或团体的布。", "骑士": "shì 与 zhì 声母不同（sh 与 zh），声调相同，意思是骑士，不是旗帜。", "气质": "qì（第四声）与 qí（第二声）声调不同，意思是气质，不是旗帜。", "起止": "qǐ 与 qí 声调不同，zhǐ 与 zhì 声调也不同，意思是起点和终点，不是旗帜。"}, "sentence_index": null, "correct_answer": "旗帜"}, "level_3": {"options": [{"text": "旗帜", "is_correct": true, "explanation": "正确：“每个国家都有自己的旗帜”符合语境，指代表国家的标志。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的学习任务，不属于每个国家所拥有的东西。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛是人的器官，不是国家拥有的东西，句子不成立。"}, {"text": "鼻子", "is_correct": false, "explanation": "搭配：“每个国家都有自己的”后应接可以归属国家的事物，“鼻子”不能这样搭配。"}], "explanations": {"旗帜": "正确：“每个国家都有自己的旗帜”符合语境，指代表国家的标志。", "作业": "语义：作业是学生的学习任务，不属于每个国家所拥有的东西。", "眼睛": "语义：眼睛是人的器官，不是国家拥有的东西，句子不成立。", "鼻子": "搭配：“每个国家都有自己的”后应接可以归属国家的事物，“鼻子”不能这样搭配。"}, "sentence_index": 0, "correct_answer": "旗帜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把一面旗帜铺在床上，躺了下去。", "explanation": "这里应该用〈床单〉。床单铺在床上，旗帜是标志，不能当床单用。"}, {"text": "冷天他戴上一面旗帜，出门去了。", "explanation": "这里应该用〈手套〉。戴在手上的是手套，旗帜是标志，不能戴在手上。"}, {"text": "他拿着一面旗帜在灶台前做饭。", "explanation": "这里应该用〈锅〉。做饭用锅，旗帜是标志，不能用来做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbd9635-c52a-47c3-a49c-48b88934fe98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23648, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "旗帜", "is_correct": true, "explanation": "正确答案：旗帜（qí zhì），指有图案或颜色、代表国家或团体的布。"}, {"text": "奇事", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），意思是奇怪的事情，不是旗帜。"}, {"text": "器质", "is_correct": false, "explanation": "qì（第四声）与 qí（第二声）声调不同，意思是器官的物质结构，不是旗帜。"}, {"text": "启智", "is_correct": false, "explanation": "qǐ（第三声）与 qí（第二声）声调不同，意思是开启智慧，不是旗帜。"}], "explanations": {"旗帜": "正确答案：旗帜（qí zhì），指有图案或颜色、代表国家或团体的布。", "奇事": "shì 与 zhì 声母不同（sh 与 zh），意思是奇怪的事情，不是旗帜。", "器质": "qì（第四声）与 qí（第二声）声调不同，意思是器官的物质结构，不是旗帜。", "启智": "qǐ（第三声）与 qí（第二声）声调不同，意思是开启智慧，不是旗帜。"}, "sentence_index": null, "correct_answer": "旗帜"}, "level_3": {"options": [{"text": "旗帜", "is_correct": true, "explanation": "正确：“旗帜的颜色和图案”指旗子本身的视觉特征，符合语境。"}, {"text": "歌词", "is_correct": false, "explanation": "语义：歌词是文字内容，没有颜色和图案，句子不成立。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字没有颜色和图案，不能被说有“特别的意思”的颜色和图案。"}, {"text": "微笑", "is_correct": false, "explanation": "搭配：“微笑”不能说有颜色和图案，二者搭配不当。"}], "explanations": {"旗帜": "正确：“旗帜的颜色和图案”指旗子本身的视觉特征，符合语境。", "歌词": "语义：歌词是文字内容，没有颜色和图案，句子不成立。", "数字": "语义：数字没有颜色和图案，不能被说有“特别的意思”的颜色和图案。", "微笑": "搭配：“微笑”不能说有颜色和图案，二者搭配不当。"}, "sentence_index": 6, "correct_answer": "旗帜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用一面旗帜煎了两个鸡蛋。", "explanation": "这里应该用〈平底锅〉。煎鸡蛋要用平底锅，旗帜是标志，不能用来煎东西。"}, {"text": "她穿上一面旗帜，出门去了。", "explanation": "这里应该用〈鞋子〉。穿在脚上的是鞋子，旗帜是标志，不能穿。"}, {"text": "他对着一面旗帜照镜子。", "explanation": "这里应该用〈镜子〉。照脸用的是镜子，旗帜是标志，不能用来照。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbd9635-c52a-47c3-a49c-48b88934fe98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他旗帜挂在窗户上。", "corrected_sentence": "他把旗帜挂在窗户上。", "error_description": "漏用“把”：把字句须用“把”引出宾语“旗帜”，应说“他把旗帜挂在窗户上”，省去“把”则句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbd9635-c52a-47c3-a49c-48b88934fe98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了一个红色的旗帜。", "corrected_sentence": "他买了一面红色的旗帜。", "error_description": "量词错误：“旗帜”应用量词“面”，不能用“个”。“面”用于有平面的布制品。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbd9635-c52a-47c3-a49c-48b88934fe98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
