INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23654, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "和你一起做一件事的人。", "primary_collocate": null, "pronunciation": "duì yǒu", "ipa": "twei˥˩ jou˨˩", "syllable_count": 2, "sentences": [{"text": "玩这个游戏时，我有两个队友。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做小组作业时，我的队友很认真。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们爬山时，队友一直在等我。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是我在比赛中最好的队友。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次旅行我们是队友，要一起走完。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想找一个队友一起参加比赛。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队友太慢了，我只好一个人做。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你，你是个很好的队友。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游戏里的队友都在等你开始。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的队友在山下等着我们。", "target_word": "队友", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "队友们", "label": "复数"}, {"form": "隊友", "label": "繁体"}], "register": "口语", "sense_fingerprint": "游戏、作业、旅行等活动中和你一起行动的搭档", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '575b00c1-bed6-44f5-9b9f-b02dd35e33e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23654, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "队友", "is_correct": true, "explanation": "正确：「队友」指一起玩游戏的人，与语境相符。"}, {"text": "老板", "is_correct": false, "explanation": "语义：「老板」是雇用你的人，不会是一起玩游戏的人。"}, {"text": "房东", "is_correct": false, "explanation": "语义：「房东」是出租房屋的人，与玩游戏无关。"}, {"text": "长辈", "is_correct": false, "explanation": "语义：「长辈」指年长的亲属，不是一起玩游戏的人，与语境不合。"}], "explanations": {"队友": "正确：「队友」指一起玩游戏的人，与语境相符。", "老板": "语义：「老板」是雇用你的人，不会是一起玩游戏的人。", "房东": "语义：「房东」是出租房屋的人，与玩游戏无关。", "长辈": "语义：「长辈」指年长的亲属，不是一起玩游戏的人，与语境不合。"}, "sentence_index": 0, "correct_answer": "队友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在路上遇到一个队友，我们擦肩而过，互不相识。", "explanation": "这里应该用〈路人〉。「队友」指和你一起做事的人，擦肩而过的陌生人应说「路人」。"}, {"text": "我的队友每天为病人看病，我们从没一起做过事。", "explanation": "这里应该用〈医生〉。「队友」指和你一起做事的人，为病人看病的人应说「医生」，且「从没一起做过事」与「队友」矛盾。"}, {"text": "我的队友上周批改了我的作业，他从没和我一起做过事。", "explanation": "这里应该用〈老师〉。「队友」指和你一起做事的人，批改作业的人应说「老师」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1909e090-603f-4379-8575-4bcd49f45626') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "队友", "is_correct": true, "explanation": "正确：「队友」是一起做事的同伴，太慢时只好自己做，符合语境。"}, {"text": "作业", "is_correct": false, "explanation": "语义：「作业」是要完成的任务，不能作为会「太慢」行动的同伴。"}, {"text": "饭店", "is_correct": false, "explanation": "搭配：「太慢」形容人或动作的速度，不能直接修饰「饭店」这个场所。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不会做事，不能说「太慢了」，也不能成为一起做事的人。"}], "explanations": {"队友": "正确：「队友」是一起做事的同伴，太慢时只好自己做，符合语境。", "作业": "语义：「作业」是要完成的任务，不能作为会「太慢」行动的同伴。", "饭店": "搭配：「太慢」形容人或动作的速度，不能直接修饰「饭店」这个场所。", "天气": "语义：「天气」不会做事，不能说「太慢了」，也不能成为一起做事的人。"}, "sentence_index": 6, "correct_answer": "队友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛时，队友在场上和我们对抗。", "explanation": "这里应该用〈对手〉。「队友」是同一队的人，在场上对抗我们的应说「对手」。"}, {"text": "这场比赛的队友判我犯规了。", "explanation": "这里应该用〈裁判〉。「队友」是参赛的人，不能判罚犯规；判罚的是「裁判」。"}, {"text": "这位队友买完东西就走了，我们没有一起做过任何事。", "explanation": "这里应该用〈顾客〉。「队友」指和你一起做事的人，只是来买东西、没有一起做事的人应说「顾客」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1909e090-603f-4379-8575-4bcd49f45626') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们是很好队友。", "corrected_sentence": "我们是很好的队友。", "error_description": "「很好」修饰名词「队友」时要加「的」。应说「很好的队友」，少了「的」就不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1909e090-603f-4379-8575-4bcd49f45626') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每个队友们都很认真。", "corrected_sentence": "每个队友都很认真。", "error_description": "「每个」后面不能加「们」。应说「每个队友」或「队友们」，二者不能合用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1909e090-603f-4379-8575-4bcd49f45626') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23656, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbd9635-c52a-47c3-a49c-48b88934fe98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23656, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbd9635-c52a-47c3-a49c-48b88934fe98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23656, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "队伍里带领大家的人。", "primary_collocate": null, "pronunciation": "duì zhǎng", "ipa": "tweɪ˥˩ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "队长走在最前面，我们跟在后面。", "target_word": "队长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是我们班足球队的队长。", "target_word": "队长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队长说今天下午三点开始练习。", "target_word": "队长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想当队长，因为我喜欢带着大家玩。", "target_word": "队长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长让每个人都有机会踢球。", "target_word": "队长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师请队长把名单交给她。", "target_word": "队长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的队长很会照顾新来的队员。", "target_word": "队长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，队长让大家先回帐篷。", "target_word": "队长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都听队长的话，所以队伍很整齐。", "target_word": "队长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当了三年队长，大家都很喜欢他。", "target_word": "队长", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "副队长", "label": "复合"}, {"form": "隊長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "队伍里带领大家的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de44d6c8-b05c-487d-a0c5-03c2d609f7fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23656, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "队长", "is_correct": true, "explanation": "队长指带领大家的人，走在最前面、让后面的人跟随，与句意相符。"}, {"text": "皮球", "is_correct": false, "explanation": "配价：“走”的施事须是能自主行走的人或动物，皮球不符合。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“走”要求有生命的施事，石头不能自行走动。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是静止的物件，不会走，与“我们跟在后面”的意思不合。"}], "explanations": {"队长": "队长指带领大家的人，走在最前面、让后面的人跟随，与句意相符。", "皮球": "配价：“走”的施事须是能自主行走的人或动物，皮球不符合。", "石头": "配价：“走”要求有生命的施事，石头不能自行走动。", "桌子": "语义：桌子是静止的物件，不会走，与“我们跟在后面”的意思不合。"}, "sentence_index": 0, "correct_answer": "队长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的队长今天负责接待客人。", "explanation": "这里应该用〈经理〉。餐厅、公司的负责人叫经理，队长指队伍里带领大家的人，餐厅不是这样的队伍。"}, {"text": "这家银行的队长每天负责审批贷款。", "explanation": "这里应该用〈行长〉。银行的负责人叫行长；队长指队伍里带领大家的人，不用于银行管理层。"}, {"text": "这家公司的队长每天负责审批财务报表。", "explanation": "这里应该用〈经理〉。公司的负责人叫经理；队长指队伍里带领大家的人，不用于公司管理层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbd9635-c52a-47c3-a49c-48b88934fe98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "队长", "is_correct": true, "explanation": "队长指带领大家的人，很会照顾新队员的正是这样的人，与句意相符。"}, {"text": "天气", "is_correct": false, "explanation": "配价：“照顾”的施事须是有意识的人，天气不能照顾他人。"}, {"text": "闹钟", "is_correct": false, "explanation": "配价：“照顾”要求有意识的施事，闹钟不能照顾新队员。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书本，没有照顾他人的能力，与“很会照顾”不合。"}], "explanations": {"队长": "队长指带领大家的人，很会照顾新队员的正是这样的人，与句意相符。", "天气": "配价：“照顾”的施事须是有意识的人，天气不能照顾他人。", "闹钟": "配价：“照顾”要求有意识的施事，闹钟不能照顾新队员。", "课本": "语义：课本是书本，没有照顾他人的能力，与“很会照顾”不合。"}, "sentence_index": 6, "correct_answer": "队长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家图书馆的队长每天负责整理书架、借还图书。", "explanation": "这里应该用〈馆员〉。整理书架、借还图书是图书馆员的工作；队长指队伍里带领大家的人，不用于图书馆的日常工作。"}, {"text": "这场比赛的队长对犯规的球员掏出了黄牌。", "explanation": "这里应该用〈裁判〉。出示黄牌、判罚犯规的是裁判；队长是队伍里带领大家的人，没有判罚的权力。"}, {"text": "这家超市的队长每天亲自算账、采购货物。", "explanation": "这里应该用〈经理〉。算账、采购是超市经理的工作；队长指队伍里带领大家的人，不用于超市的管理岗位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbd9635-c52a-47c3-a49c-48b88934fe98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我们班足球队的一只队长。", "corrected_sentence": "他是我们班足球队的一位队长。", "error_description": "量词错误：“队长”指人，量词应用“位”（或“个”），“只”多用于动物，不能用于指人的队长。正确说法是“一位队长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbd9635-c52a-47c3-a49c-48b88934fe98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年才当了上队长。", "corrected_sentence": "他去年才当上队长。", "error_description": "“了”的位置错误：“当上”是动补结构，“了”不能插在“当”和“上”之间，应说“当上队长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbd9635-c52a-47c3-a49c-48b88934fe98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23660, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "防守", "is_correct": true, "explanation": "防守：与进攻相对，指守住阵地，不主动攻击敌人。"}, {"text": "休息", "is_correct": false, "explanation": "休息是普通动词，与进攻没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "观察是普通动词，与进攻没有反义关系。"}, {"text": "收集", "is_correct": false, "explanation": "收集是普通动词，与进攻没有反义关系。"}], "correct_answer": "防守", "explanations": {"防守": "防守：与进攻相对，指守住阵地，不主动攻击敌人。", "休息": "休息是普通动词，与进攻没有反义关系。", "观察": "观察是普通动词，与进攻没有反义关系。", "收集": "收集是普通动词，与进攻没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1909e090-603f-4379-8575-4bcd49f45626') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23660, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "防守", "is_correct": true, "explanation": "防守：与进攻相对，指守住阵地，不主动攻击敌人。"}, {"text": "等待", "is_correct": false, "explanation": "等待是普通动词，与进攻没有反义关系。"}, {"text": "储存", "is_correct": false, "explanation": "储存是普通动词，与进攻没有反义关系。"}, {"text": "复习", "is_correct": false, "explanation": "复习是普通动词，与进攻没有反义关系。"}], "correct_answer": "防守", "explanations": {"防守": "防守：与进攻相对，指守住阵地，不主动攻击敌人。", "等待": "等待是普通动词，与进攻没有反义关系。", "储存": "储存是普通动词，与进攻没有反义关系。", "复习": "复习是普通动词，与进攻没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1909e090-603f-4379-8575-4bcd49f45626') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23660, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "主动去打敌人。", "primary_collocate": null, "pronunciation": "jìn gōng", "ipa": "tɕin˥˩ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "士兵们夜里向敌人的营地进攻。", "target_word": "进攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "将军下令明天早上进攻。", "target_word": "进攻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "敌人从河边进攻，我们守住了桥。", "target_word": "进攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们准备进攻对面的山头。", "target_word": "进攻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "国王派兵进攻邻国的城。", "target_word": "进攻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天黑以后，敌军开始进攻。", "target_word": "进攻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们的人太少，不能主动进攻。", "target_word": "进攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们进攻了一整夜，还是没有打下来。", "target_word": "进攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到信号，战士们一起向前进攻。", "target_word": "进攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "敌人进攻时，村民躲进了山洞。", "target_word": "进攻", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "进攻了", "label": "完成体"}, {"form": "进攻着", "label": "持续体"}, {"form": "进攻过", "label": "经历体"}, {"form": "進攻", "label": "繁体"}], "register": "中性", "sense_fingerprint": "战争中主动出击去打敌人或敌方阵地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '575b00c1-bed6-44f5-9b9f-b02dd35e33e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23660, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "进攻", "is_correct": true, "explanation": "正确。此处为动词，指主动向敌人发起攻打，与“向……营地”搭配。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：士兵不会在夜里向敌人的营地唱歌，语义不通。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：哭泣不是对营地发起的行动，与战斗语境不合。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“睡觉”不能与“向……营地”这类方向性的状语搭配。"}], "explanations": {"进攻": "正确。此处为动词，指主动向敌人发起攻打，与“向……营地”搭配。", "唱歌": "语义：士兵不会在夜里向敌人的营地唱歌，语义不通。", "哭泣": "语义：哭泣不是对营地发起的行动，与战斗语境不合。", "睡觉": "搭配：“睡觉”不能与“向……营地”这类方向性的状语搭配。"}, "sentence_index": 0, "correct_answer": "进攻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村民们进攻了家乡。", "explanation": "这里应该用〈保卫〉。进攻是主动打击敌人，村民守护家乡要用“保卫”。"}, {"text": "士兵们进攻了博物馆。", "explanation": "这里应该用〈参观〉。进攻是主动打击敌人，去博物馆参观要用“参观”。"}, {"text": "一只野狗进攻了路人。", "explanation": "这里应该用〈攻击〉。进攻多指军队的主动打击，动物伤人要用“攻击”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1909e090-603f-4379-8575-4bcd49f45626') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23660, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进攻", "is_correct": true, "explanation": "正确。此处为动词，“主动”修饰的是主动打敌人的行动。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“我们的人太少，不能主动跳舞”与战术判断无关，语义不通。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“主动”修饰“散步”不合语境，散步不是需要主动发起的行动。"}, {"text": "尖叫", "is_correct": false, "explanation": "语义：尖叫不是战术行动，与“人太少”的语境不合。"}], "explanations": {"进攻": "正确。此处为动词，“主动”修饰的是主动打敌人的行动。", "跳舞": "语义：“我们的人太少，不能主动跳舞”与战术判断无关，语义不通。", "散步": "搭配：“主动”修饰“散步”不合语境，散步不是需要主动发起的行动。", "尖叫": "语义：尖叫不是战术行动，与“人太少”的语境不合。"}, "sentence_index": 6, "correct_answer": "进攻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生进攻伤员。", "explanation": "这里应该用〈救助〉。进攻是主动打击敌人，救护伤员要用“救助”。"}, {"text": "村民进攻远来的客人。", "explanation": "这里应该用〈迎接〉。进攻是主动打击敌人，对远来的客人表示欢迎要用“迎接”。"}, {"text": "护士进攻病人。", "explanation": "这里应该用〈照料〉。进攻是主动打击敌人，护理病人要用“照料”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1909e090-603f-4379-8575-4bcd49f45626') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23660, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "敌军昨天夜里进攻过我们的营地。", "corrected_sentence": "敌军昨天夜里进攻了我们的营地。", "error_description": "具体的过去时间（昨天夜里）后面表示已经完成的事件，要用“了”，应说“进攻了我们的营地”。“过”表示经历，一般不与具体的过去时间连用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1909e090-603f-4379-8575-4bcd49f45626') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23660, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "敌军连夜进攻的很猛烈。", "corrected_sentence": "敌军连夜进攻得很猛烈。", "error_description": "“进攻”后面表示程度的补语要用“得”，不能写成“的”，应说“进攻得很猛烈”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1909e090-603f-4379-8575-4bcd49f45626') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
