INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23664, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "自己要做的事，就好好地做。", "primary_collocate": null, "pronunciation": "fù zé", "ipa": "fu˥˩ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他做事很负责。", "target_word": "负责", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "王老师对学生非常负责。", "target_word": "负责", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她工作认真，也很负责。", "target_word": "负责", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个孩子对自己的作业很负责，每天都认真写完。", "target_word": "负责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如果你不负责，我就不想和你一起工作。", "target_word": "负责", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "他不太负责，常常忘了关门。", "target_word": "负责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生对病人很负责，每天都来看好几次。", "target_word": "负责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的同事做事很负责，从来不迟到。", "target_word": "负责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板喜欢负责的人，因为他们不用别人催。", "target_word": "负责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个很负责的爸爸，每天送孩子上学。", "target_word": "负责", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "负责任", "label": "复合"}, {"form": "負責", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做事认真、尽到自己的责任（形容人的态度）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab33c06f-7df9-4a5c-b347-e98431a3920c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23664, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "负责", "is_correct": true, "explanation": "正确答案。负责 fù zé：做事认真，尽到自己的责任。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂 fù zá 与 负责 fù zé 只有第二音节韵母不同（zá 与 zé），意思是不简单、繁复。"}, {"text": "父子", "is_correct": false, "explanation": "父子 fù zǐ 与 负责 fù zé 第二音节声调不同（zǐ 第三声，zé 第二声），意思是父亲和儿子。"}, {"text": "负载", "is_correct": false, "explanation": "负载 fù zài 与 负责 fù zé 第二音节的韵母和声调都不同（zài 第四声，zé 第二声），意思是承受的重量。"}], "explanations": {"负责": "正确答案。负责 fù zé：做事认真，尽到自己的责任。", "复杂": "复杂 fù zá 与 负责 fù zé 只有第二音节韵母不同（zá 与 zé），意思是不简单、繁复。", "父子": "父子 fù zǐ 与 负责 fù zé 第二音节声调不同（zǐ 第三声，zé 第二声），意思是父亲和儿子。", "负载": "负载 fù zài 与 负责 fù zé 第二音节的韵母和声调都不同（zài 第四声，zé 第二声），意思是承受的重量。"}, "sentence_index": null, "correct_answer": "负责"}, "level_3": {"options": [{"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容身高，不能用来形容一个人做事的态度。"}, {"text": "负责", "is_correct": true, "explanation": "正确：“做事很负责”形容他做事认真、尽到责任的态度。"}, {"text": "红", "is_correct": false, "explanation": "语义：“红”指颜色或名气，不能用来形容做事的态度。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容体形，不能用来形容做事的态度。"}], "explanations": {"矮": "体貌：“矮”形容身高，不能用来形容一个人做事的态度。", "负责": "正确：“做事很负责”形容他做事认真、尽到责任的态度。", "红": "语义：“红”指颜色或名气，不能用来形容做事的态度。", "瘦": "体貌：“瘦”形容体形，不能用来形容做事的态度。"}, "sentence_index": 0, "correct_answer": "负责"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些字写得很负责。", "explanation": "这里应该用〈工整〉。“负责”形容人的态度，不能用来形容字的样子。"}, {"text": "今天的天气很负责，阳光很好。", "explanation": "这里应该用〈晴朗〉。“负责”形容人的态度，不能用来描述天气。"}, {"text": "这台洗衣机很负责，每天都能按时工作。", "explanation": "这里应该用〈好用〉。“负责”形容人对事情认真尽职，不能用来评价机器的性能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23664, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容体形，不能用来形容医生对病人的态度。"}, {"text": "负责", "is_correct": true, "explanation": "正确：“很负责”形容医生对病人尽心尽责，与“每天都来看好几次”呼应。"}, {"text": "宽", "is_correct": false, "explanation": "体貌：“宽”形容宽度，不能用来形容医生对病人的态度。"}, {"text": "浅", "is_correct": false, "explanation": "语义：“浅”形容深度，与医生对病人的态度无关，句子不通。"}], "explanations": {"胖": "体貌：“胖”形容体形，不能用来形容医生对病人的态度。", "负责": "正确：“很负责”形容医生对病人尽心尽责，与“每天都来看好几次”呼应。", "宽": "体貌：“宽”形容宽度，不能用来形容医生对病人的态度。", "浅": "语义：“浅”形容深度，与医生对病人的态度无关，句子不通。"}, "sentence_index": 6, "correct_answer": "负责"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子很负责，每天都稳稳地支撑着我。", "explanation": "这里应该用〈稳固〉。“负责”形容人的态度，不能用来形容椅子。"}, {"text": "我的眼睛很负责，每天都看得很清楚。", "explanation": "这里应该用〈明亮〉。“负责”形容人的态度，不能用来形容眼睛。"}, {"text": "这辆自行车很负责，每天都准时送我上学。", "explanation": "这里应该用〈可靠〉。“负责”形容人对事情认真尽职，不能用来形容自行车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小张对待工作很很负责。", "corrected_sentence": "小张对待工作很负责。", "error_description": "错误在程度副词：“很”重复使用，“很很负责”不成话，只能用一个“很”。正确：“对待工作很负责”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师是个很负责人。", "corrected_sentence": "这位老师是个很负责的人。", "error_description": "“负责人”是名词复合词，指担任领导职务的人。漏掉定语标记“的”，“很负责人”不成立；正确形式为“很负责的人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
