INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23666, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人以前曾经当面见过。", "primary_collocate": null, "pronunciation": "jiàn guo miàn", "ipa": "tɕjɛn kwo mjɛn", "syllable_count": 3, "sentences": [{"text": "我和她在大学见过面。", "target_word": "见过面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你跟李先生见过面没有？", "target_word": "见过面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们很久以前见过面。", "target_word": "见过面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们见过面，但我想不起来在哪儿。", "target_word": "见过面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你好，我们昨天见过面。", "target_word": "见过面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两位老师早就见过面了。", "target_word": "见过面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说他和你见过面。", "target_word": "见过面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在机场见过面，你忘了吗？", "target_word": "见过面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们见过面，不用我介绍了吧。", "target_word": "见过面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和他在会议上见过面。", "target_word": "见过面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没见过面", "label": "否定式"}, {"form": "见面", "label": "基本形式"}], "register": "口语", "sense_fingerprint": "见过面：两人以前已经见过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b7c2170-8037-4fb9-be28-1859d5540cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23666, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "见过面", "is_correct": true, "explanation": "正确：“在大学见过面”表示两人在大学时当面相见过，与句意相合。"}, {"text": "下过雨", "is_correct": false, "explanation": "配价：“下雨”是天气动词，不能以“我和她”作主语，句子不通。"}, {"text": "开过花", "is_correct": false, "explanation": "语义：“开花”的主语须是植物，不能用于“我和她”，句意不通。"}, {"text": "生过锈", "is_correct": false, "explanation": "语义：“生锈”指金属被氧化，不能用于人，句意不通。"}], "explanations": {"见过面": "正确：“在大学见过面”表示两人在大学时当面相见过，与句意相合。", "下过雨": "配价：“下雨”是天气动词，不能以“我和她”作主语，句子不通。", "开过花": "语义：“开花”的主语须是植物，不能用于“我和她”，句意不通。", "生过锈": "语义：“生锈”指金属被氧化，不能用于人，句意不通。"}, "sentence_index": 0, "correct_answer": "见过面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在图书馆和一本词典见过面。", "explanation": "这里应该用〈看见〉。见过面只用于人与人当面相见，不能指书籍。"}, {"text": "我一个人在大学里见过面了。", "explanation": "这里应该用〈待过〉。见过面需要两方或多方当面相见，只有我一个人，不能说见过面。"}, {"text": "这个问题我们昨天就见过面了。", "explanation": "这里应该用〈讨论过〉。见过面只用于人，不能用于抽象的问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b391b74d-4f42-4d48-a002-89ac6119d04f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "见过面", "is_correct": true, "explanation": "正确：“他说他和你见过面”是转述两人以前当面相见的事，句意通顺。"}, {"text": "打过雷", "is_correct": false, "explanation": "配价：“打雷”是天气现象，不能以“他”和“你”作主语，句子不通。"}, {"text": "刮过风", "is_correct": false, "explanation": "配价：“刮风”是天气现象，主语须是风，不能以“他”和“你”作主语，句子不通。"}, {"text": "结过冰", "is_correct": false, "explanation": "语义：“结冰”指液体凝固，不能用于人，句意不通。"}], "explanations": {"见过面": "正确：“他说他和你见过面”是转述两人以前当面相见的事，句意通顺。", "打过雷": "配价：“打雷”是天气现象，不能以“他”和“你”作主语，句子不通。", "刮过风": "配价：“刮风”是天气现象，主语须是风，不能以“他”和“你”作主语，句子不通。", "结过冰": "语义：“结冰”指液体凝固，不能用于人，句意不通。"}, "sentence_index": 6, "correct_answer": "见过面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在公园里和一只狗见过面了。", "explanation": "这里应该用〈遇见〉。见过面只指人与人当面相见，不能用于动物。"}, {"text": "我在报纸上和他的照片见过面了。", "explanation": "这里应该用〈看过〉。见过面的对象必须是真人，不能用来指照片。"}, {"text": "我和这把椅子在会议上见过面了。", "explanation": "这里应该用〈坐过〉。见过面只用于人与人之间，不能用于物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b391b74d-4f42-4d48-a002-89ac6119d04f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们以前在朋友家见面过，只是没说过话。", "corrected_sentence": "我们以前在朋友家见过面，只是没说过话。", "error_description": "错误：“过”应紧跟动词，正确形式为“见过面”；写成“见面过”是体标位置错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b391b74d-4f42-4d48-a002-89ac6119d04f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前和他在会议上不见过面。", "corrected_sentence": "我以前和他在会议上没见过面。", "error_description": "错误：否定“见过面”这种经历要用“没”，“不”不能与“过”组合；应为“没见过面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b391b74d-4f42-4d48-a002-89ac6119d04f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
