INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23672, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1909e090-603f-4379-8575-4bcd49f45626') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23672, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "中文是中国人说的话和写的字。", "primary_collocate": null, "pronunciation": "zhōng wén", "ipa": "ʈ͡ʂʊŋ˥ wən˧˥", "syllable_count": 2, "sentences": [{"text": "他不懂中文，看不懂这个字。", "target_word": "中文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想用中文给朋友写信。", "target_word": "中文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小孩两岁就会说中文了。", "target_word": "中文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中文有很多好看的字。", "target_word": "中文", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈在家只说中文。", "target_word": "中文", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "手机上可以打中文。", "target_word": "中文", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢看中文电影。", "target_word": "中文", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这张纸上的中文是谁写的？", "target_word": "中文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的中文名字很好听。", "target_word": "中文", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她在中国住了三年，会说中文。", "target_word": "中文", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "中文名", "label": "复合"}, {"form": "中文系", "label": "复合"}], "register": "通用", "sense_fingerprint": "中国人说的话和写的字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '575b00c1-bed6-44f5-9b9f-b02dd35e33e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23672, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蛋糕", "is_correct": false, "explanation": "配价：“懂”后面要接知识、语言或道理之类的对象，“不懂蛋糕”不成立。"}, {"text": "中文", "is_correct": true, "explanation": "中文：指中国人说的话和写的字，与“看不懂这个字”的语境相符。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“懂椅子”不是常用说法，“懂”不接具体的器物。"}, {"text": "雨伞", "is_correct": false, "explanation": "配价：“懂”接知识、语言一类的对象，“不懂雨伞”句意不通。"}], "explanations": {"蛋糕": "配价：“懂”后面要接知识、语言或道理之类的对象，“不懂蛋糕”不成立。", "中文": "中文：指中国人说的话和写的字，与“看不懂这个字”的语境相符。", "椅子": "搭配：“懂椅子”不是常用说法，“懂”不接具体的器物。", "雨伞": "配价：“懂”接知识、语言一类的对象，“不懂雨伞”句意不通。"}, "sentence_index": 0, "correct_answer": "中文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的朋友住在中文。", "explanation": "这里应该用〈中国〉。中国是地方，表示住的地点；中文指中国人说的话和写的字，不能作为居住的地点。"}, {"text": "他开着中文去上班。", "explanation": "这里应该用〈汽车〉。中文是语言，不能被驾驶；开车上班要用「汽车」。"}, {"text": "他去中文工作了。", "explanation": "这里应该用〈北京〉。北京是城市，表示去的地方；中文不是地名，不能作为“去”的目的地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1909e090-603f-4379-8575-4bcd49f45626') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "牙膏", "is_correct": false, "explanation": "语义：“牙膏”不是电影的类型，不能修饰“电影”，句意不通。"}, {"text": "中文", "is_correct": true, "explanation": "中文：修饰“电影”，表示中文语言的影片，是常见的说法。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“面包电影”不成词组，面包不能作为电影的类别。"}, {"text": "剪刀", "is_correct": false, "explanation": "语义：“剪刀”不是电影的类型，不能修饰“电影”，句意不通。"}], "explanations": {"牙膏": "语义：“牙膏”不是电影的类型，不能修饰“电影”，句意不通。", "中文": "中文：修饰“电影”，表示中文语言的影片，是常见的说法。", "面包": "搭配：“面包电影”不成词组，面包不能作为电影的类别。", "剪刀": "语义：“剪刀”不是电影的类型，不能修饰“电影”，句意不通。"}, "sentence_index": 6, "correct_answer": "中文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个中文学得很快。", "explanation": "这里应该用〈外国人〉。“学得很快”的主语须是人；中文指语言，不能作为“学”的主语。"}, {"text": "他每天骑着中文上学。", "explanation": "这里应该用〈自行车〉。中文是语言，不能被骑；骑车上学要用「自行车」。"}, {"text": "我的邻居是中文。", "explanation": "这里应该用〈中国人〉。中文指语言，不指人，不能用来说明“邻居”的身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1909e090-603f-4379-8575-4bcd49f45626') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这篇文章翻译中文了。", "corrected_sentence": "他把这篇文章翻译成中文了。", "error_description": "结果补语“成”缺失：应说“翻译成中文了”，不能说“翻译中文了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1909e090-603f-4379-8575-4bcd49f45626') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我学过一个中文。", "corrected_sentence": "我学过中文。", "error_description": "量词错误：“中文”指语言，不用个体量词计量；“一个”多余，应说“学过中文”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1909e090-603f-4379-8575-4bcd49f45626') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
