INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23690, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23690, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "完全进入一种状态，像泡在水里一样。", "primary_collocate": null, "pronunciation": "chén jìn", "ipa": "ʈʂʰən˧˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "我沉浸在书里，忘了时间。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他沉浸在游戏里，不想吃饭。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小女孩沉浸在画画的快乐里。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她沉浸在歌声中，闭上了眼睛。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们沉浸在学习中，教室里很安静。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我爸爸沉浸在棋局里，没有听见电话响。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家沉浸在比赛的紧张里。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他沉浸在工作中，忘了回家。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶沉浸在旧照片里，看了很久。", "target_word": "沉浸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌太好听，我整个人都沉浸进去了。", "target_word": "沉浸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "沉浸着", "label": "体标"}, {"form": "沉浸了", "label": "体标"}, {"form": "沉浸式", "label": "复合"}], "register": "中性", "sense_fingerprint": "完全进入某种状态，像泡在水里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bf87788-5a50-449d-91ed-9ab27df85da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23690, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "离开", "is_correct": false, "explanation": "配价：“离开”要直接带处所宾语，不能说“离开在……里”，这个结构不成立。"}, {"text": "争吵", "is_correct": false, "explanation": "语义：争吵与“在书里，忘了时间”的安静读书状态相矛盾。"}, {"text": "厌烦", "is_correct": false, "explanation": "搭配：“厌烦”通常直接带对象，不接“在……里”的处所结构，搭配不当。"}, {"text": "沉浸", "is_correct": true, "explanation": "沉浸指完全进入某种状态，与“在书里，忘了时间”的描述相符。"}], "explanations": {"离开": "配价：“离开”要直接带处所宾语，不能说“离开在……里”，这个结构不成立。", "争吵": "语义：争吵与“在书里，忘了时间”的安静读书状态相矛盾。", "厌烦": "搭配：“厌烦”通常直接带对象，不接“在……里”的处所结构，搭配不当。", "沉浸": "沉浸指完全进入某种状态，与“在书里，忘了时间”的描述相符。"}, "sentence_index": 0, "correct_answer": "沉浸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把大部分积蓄沉浸在股市里，一年就输光了。", "explanation": "这里应该用〈投入〉。〈沉浸〉指心神沉入某种状态，不用来说把钱投进去。"}, {"text": "我的成绩沉浸在班级前十里。", "explanation": "这里应该用〈位列〉。〈沉浸〉的主语须是人，表示全神贯注，成绩不能沉浸，应说位列班级前十。"}, {"text": "他沉浸了一碗面条，很快就吃完了。", "explanation": "这里应该用〈吃〉。〈沉浸〉不能直接带宾语，吃面条要说吃，不能说沉浸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23690, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逃离", "is_correct": false, "explanation": "配价：“逃离”要直接带处所宾语，“逃离在……里”的结构不成立。"}, {"text": "争论", "is_correct": false, "explanation": "语义：争论是口角，与“比赛的紧张”描述的投入状态不符。"}, {"text": "厌倦", "is_correct": false, "explanation": "搭配：“厌倦”通常直接带对象，不说“厌倦在……里”，不能这样搭配。"}, {"text": "沉浸", "is_correct": true, "explanation": "沉浸指完全进入某种状态，与“比赛的紧张里”的投入感相符。"}], "explanations": {"逃离": "配价：“逃离”要直接带处所宾语，“逃离在……里”的结构不成立。", "争论": "语义：争论是口角，与“比赛的紧张”描述的投入状态不符。", "厌倦": "搭配：“厌倦”通常直接带对象，不说“厌倦在……里”，不能这样搭配。", "沉浸": "沉浸指完全进入某种状态，与“比赛的紧张里”的投入感相符。"}, "sentence_index": 6, "correct_answer": "沉浸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把身子沉浸到被子里，很快就睡着了。", "explanation": "这里应该用〈钻〉。〈沉浸〉指全身心投入，不用来说把身子放进被子里。"}, {"text": "他沉浸了三个月的亏损，却毫不着急。", "explanation": "这里应该用〈承受〉。〈沉浸〉不能直接带宾语，应说承受三个月的亏损。"}, {"text": "这场比赛太精彩了，我却把手机沉浸在桌上，只看了一眼比分。", "explanation": "这里应该用〈放〉。〈沉浸〉不能用于把物品放在某处，应说把手机放在桌上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐沉浸菜香里，忘了关火。", "corrected_sentence": "姐姐沉浸在菜香里，忘了关火。", "error_description": "介词缺失：“沉浸”后面要用“在……里”引出所沉浸的对象，应说“沉浸在菜香里”，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟弟沉浸了在动画片里，忘了写作业。", "corrected_sentence": "弟弟沉浸在动画片里，忘了写作业。", "error_description": "“了”的位置错误：“了”不能插在“沉浸”和“在”之间，应说“沉浸在动画片里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
