INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23694, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西给别人", "primary_collocate": null, "pronunciation": "chuán dì", "ipa": "ʈʂʰwan˧˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "请把这张纸传递给后面的同学。", "target_word": "传递", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把书传递给每个学生。", "target_word": "传递", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们一个一个地传递着水杯。", "target_word": "传递", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们站成一排，传递着砖头。", "target_word": "传递", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信请你传递给王经理。", "target_word": "传递", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时，他把接力棒传递给下一个人。", "target_word": "传递", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一边传递小球，一边听音乐，音乐停了就出局。", "target_word": "传递", "complexity_tier": "T3", "furigana": "dà jiā yì biān chuán dì xiǎo qiú, yì biān tīng yīn yuè, yīn yuè tíng le jiù chū jú", "sentence_source": "generated"}, {"text": "妈妈让我把盘子传递给爷爷。", "target_word": "传递", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把试卷往后传递。", "target_word": "传递", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把笔传递给了同桌。", "target_word": "传递", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传递了", "label": "体标"}, {"form": "传递着", "label": "体标"}, {"form": "传递过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把东西一个接一个地交给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cff21b5d-b947-4065-949c-1c97782d2ed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23694, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传递", "is_correct": true, "explanation": "传递：把东西一个接一个地交给别人，符合“把这张纸……给后面的同学”的语境。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”是毁坏纸张，不是把纸交给别人。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”会毁掉纸，不能用来表示交给同学。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”不能与“给”构成把东西交给别人的结构，不说“擦给同学”。"}], "explanations": {"传递": "传递：把东西一个接一个地交给别人，符合“把这张纸……给后面的同学”的语境。", "撕": "语义：“撕”是毁坏纸张，不是把纸交给别人。", "烧": "语义：“烧”会毁掉纸，不能用来表示交给同学。", "擦": "搭配：“擦”不能与“给”构成把东西交给别人的结构，不说“擦给同学”。"}, "sentence_index": 0, "correct_answer": "传递"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把感冒传递给了我。", "explanation": "这里应该用〈传染〉。“传递”指把东西交给别人，把疾病传给他人要用“传染”。"}, {"text": "这个故事在村里传递了很多年。", "explanation": "这里应该用〈流传〉。“传递”指把东西一个接一个交给别人，故事代代相传要用“流传”。"}, {"text": "这辆卡车把货物传递到北京。", "explanation": "这里应该用〈运送〉。“传递”强调人与人之间的交接，长途运输货物要用“运送”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e9b3d7-70e6-4769-b272-27bad7ef97aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23694, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传递", "is_correct": true, "explanation": "传递：把球一个接一个地交给别人，符合游戏中“一边……一边”的语境。"}, {"text": "听", "is_correct": false, "explanation": "语义：“听”的对象是声音，不能说“听小球”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌，不能唱小球。"}, {"text": "吟诵", "is_correct": false, "explanation": "语域：“吟诵”是书面语，指诗词吟咏，与游戏的口语语境不合，且不能用于小球。"}], "explanations": {"传递": "传递：把球一个接一个地交给别人，符合游戏中“一边……一边”的语境。", "听": "语义：“听”的对象是声音，不能说“听小球”。", "唱": "语义：“唱”的对象是歌，不能唱小球。", "吟诵": "语域：“吟诵”是书面语，指诗词吟咏，与游戏的口语语境不合，且不能用于小球。"}, "sentence_index": 6, "correct_answer": "传递"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这封信传递到北京。", "explanation": "这里应该用〈寄〉。寄信是通过邮局送到远方，“传递”指人手递手交给身边的人。"}, {"text": "电视台把比赛传递到全国。", "explanation": "这里应该用〈转播〉。比赛通过电视传到各地要说“转播”，“传递”用于人手递手交给别人。"}, {"text": "她把孩子传递给了奶奶。", "explanation": "这里应该用〈托付〉。照顾孩子这样的责任交给别人要说“托付”，“传递”只用于物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e9b3d7-70e6-4769-b272-27bad7ef97aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23694, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把纸了传递给同学。", "corrected_sentence": "他把纸传递给同学。", "error_description": "“了”位置错误：“了”不能放在动词“传递”前面，应删去，说“他把纸传递给同学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e9b3d7-70e6-4769-b272-27bad7ef97aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23694, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家把传递给队友。", "corrected_sentence": "大家把球传递给队友。", "error_description": "宾语缺失：“把”字句中“把”后面要有被处置的宾语，应说“把球传递给队友”，不能省略“球”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e9b3d7-70e6-4769-b272-27bad7ef97aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
