INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23696, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人和人之间认识或一起做事的关系。", "primary_collocate": null, "pronunciation": "shè huì guān xì", "ipa": "ʂɤ˥˩ xweɪ˥˩ kwan˥ ɕi˥˩", "syllable_count": 4, "sentences": [{"text": "你的社会关系很广，认识很多人。", "target_word": "社会关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚搬来，在这里没有什么社会关系。", "target_word": "社会关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学和同事都是你的社会关系。", "target_word": "社会关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要学会处理社会关系。", "target_word": "社会关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的社会关系不复杂，只有几个朋友。", "target_word": "社会关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意需要有自己的社会关系。", "target_word": "社会关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "通过朋友，他认识了新的人，社会关系更多了。", "target_word": "社会关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有社会关系，找工作会容易一些。", "target_word": "社会关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，社会关系是人和人的联系。", "target_word": "社会关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢交朋友，所以社会关系很好。", "target_word": "社会关系", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "社会关系网", "label": "复合"}, {"form": "社會關係", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人与人相识或共事的关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bf87788-5a50-449d-91ed-9ab27df85da9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23696, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "社会关系", "is_correct": true, "explanation": "正确。“很广，认识很多人”说明人际联系广，与“社会关系”相合。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”不能说“很广”，与“广”搭配不当。"}, {"text": "视力", "is_correct": false, "explanation": "搭配：“视力”可以说好坏，但不能说“广”，搭配不当。"}, {"text": "孤独", "is_correct": false, "explanation": "语义：句子后半说“认识很多人”，“孤独”与之相矛盾。"}], "explanations": {"社会关系": "正确。“很广，认识很多人”说明人际联系广，与“社会关系”相合。", "体重": "搭配：“体重”不能说“很广”，与“广”搭配不当。", "视力": "搭配：“视力”可以说好坏，但不能说“广”，搭配不当。", "孤独": "语义：句子后半说“认识很多人”，“孤独”与之相矛盾。"}, "sentence_index": 0, "correct_answer": "社会关系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的社会关系很高，所以升职很快。", "explanation": "这里应用〈社会地位〉。“社会关系”指人际联系，不能用“高”来形容；“社会地位”才说“高”。"}, {"text": "他每个月都领取社会关系，生活很有保障。", "explanation": "这里应用〈社会福利〉。“领取”的对象是补贴、福利，“社会关系”指人际联系，不能被领取。"}, {"text": "他的社会关系是学生，还没有工作。", "explanation": "这里应用〈身份〉。“社会关系”指人际联系，不表示身份；说“身份是学生”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23696, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "社会关系", "is_correct": true, "explanation": "正确。“认识了新的人，……更多了”指人际联系增加，与“社会关系”相合。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”不能用“更多了”来计量，搭配不当。"}, {"text": "房子", "is_correct": false, "explanation": "语义：认识新的人不会使房子增多，与句意不符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能说“更多了”，搭配不当。"}], "explanations": {"社会关系": "正确。“认识了新的人，……更多了”指人际联系增加，与“社会关系”相合。", "性格": "搭配：“性格”不能用“更多了”来计量，搭配不当。", "房子": "语义：认识新的人不会使房子增多，与句意不符。", "天气": "搭配：“天气”不能说“更多了”，搭配不当。"}, "sentence_index": 6, "correct_answer": "社会关系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从不遵守社会关系，总是我行我素。", "explanation": "这里应用〈社会规则〉。“遵守”的对象是规则、法律，社会关系不能被遵守。"}, {"text": "社会关系每天都在关注这次选举。", "explanation": "这里应用〈社会舆论〉。“关注”的主体是人或舆论，“社会关系”是联系，不能作施事去关注事情。"}, {"text": "他大学毕业后就从事社会关系，已经十年了。", "explanation": "这里应用〈社会工作〉。“从事”搭配职业、工作，“社会关系”是人际联系，不能作职业名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23696, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的社会关系们很广，朋友很多。", "corrected_sentence": "他的社会关系很广，朋友很多。", "error_description": "“社会关系”是抽象名词，不能加“们”表示复数；此处误加“们”。正确：他的社会关系很广，朋友很多。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23696, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他通过朋友认识了一只新的社会关系。", "corrected_sentence": "他通过朋友认识了一种新的社会关系。", "error_description": "“社会关系”的量词应用“种”，不用“只”（“只”多用于动物等）。正确：他通过朋友认识了一种新的社会关系。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5601a5e-75f0-4fff-8c6a-03e27937530d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23698, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独享", "is_correct": true, "explanation": "独享：独自享受，不与别人一起，与“分享”相对。"}, {"text": "修改", "is_correct": false, "explanation": "“修改”指改动内容，与“分享”没有相对关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”指仔细看，与“分享”不构成反义。"}, {"text": "整理", "is_correct": false, "explanation": "“整理”指使有条理，与“分享”不构成反义。"}], "correct_answer": "独享", "explanations": {"独享": "独享：独自享受，不与别人一起，与“分享”相对。", "修改": "“修改”指改动内容，与“分享”没有相对关系。", "观察": "“观察”指仔细看，与“分享”不构成反义。", "整理": "“整理”指使有条理，与“分享”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23698, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独享", "is_correct": true, "explanation": "独享：独自享有，不与别人一起，与“分享”相对。"}, {"text": "搬运", "is_correct": false, "explanation": "“搬运”指把东西从一处移到另一处，与“分享”不构成反义。"}, {"text": "邀请", "is_correct": false, "explanation": "“邀请”指请人来或参加，与“分享”不构成反义。"}, {"text": "打印", "is_correct": false, "explanation": "“打印”指把文件印在纸上，与“分享”不构成反义。"}], "correct_answer": "独享", "explanations": {"独享": "独享：独自享有，不与别人一起，与“分享”相对。", "搬运": "“搬运”指把东西从一处移到另一处，与“分享”不构成反义。", "邀请": "“邀请”指请人来或参加，与“分享”不构成反义。", "打印": "“打印”指把文件印在纸上，与“分享”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23698, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把自己有的东西给别人，让别人也有。", "primary_collocate": null, "pronunciation": "fēn xiǎng", "ipa": "fən˥ ɕjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "小明把他的巧克力分享给同学。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想和你分享这个好消息。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做了蛋糕，让我们一起分享。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢和朋友分享快乐。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟不愿意分享自己的玩具。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好东西要和大家一起分享。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶把种的苹果分享给邻居。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把成功的喜悦分享给家人。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "午饭时，同学们互相分享各自带的菜。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子学会了分享，朋友就多了。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分享了", "label": "体标"}, {"form": "分享过", "label": "体标"}, {"form": "分享着", "label": "体标"}, {"form": "分享会", "label": "复合"}, {"form": "分享者", "label": "复合"}], "register": "中性", "sense_fingerprint": "分享：把自己的食物、物品或心情给别人一起享有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e5e0e04-19d0-4826-8ae8-48040290f7a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23698, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分享", "is_correct": true, "explanation": "分享 fēn xiǎng：把自己的东西给别人，让别人也有，正确答案。"}, {"text": "芬香", "is_correct": false, "explanation": "芬香 fēn xiāng（第一声）与 分享 fēn xiǎng（第三声）第二个音节声调不同，意思是香气浓郁。"}, {"text": "焚香", "is_correct": false, "explanation": "焚香 fén xiāng（第二声、第一声）与 分享 fēn xiǎng 两个音节的声调都不同，意思是点燃香料。"}, {"text": "分项", "is_correct": false, "explanation": "分项 fēn xiàng（第四声）与 分享 fēn xiǎng（第三声）第二个音节声调不同，意思是按项目分开。"}], "explanations": {"分享": "分享 fēn xiǎng：把自己的东西给别人，让别人也有，正确答案。", "芬香": "芬香 fēn xiāng（第一声）与 分享 fēn xiǎng（第三声）第二个音节声调不同，意思是香气浓郁。", "焚香": "焚香 fén xiāng（第二声、第一声）与 分享 fēn xiǎng 两个音节的声调都不同，意思是点燃香料。", "分项": "分项 fēn xiàng（第四声）与 分享 fēn xiǎng（第三声）第二个音节声调不同，意思是按项目分开。"}, "sentence_index": null, "correct_answer": "分享"}, "level_3": {"options": [{"text": "分享", "is_correct": true, "explanation": "分享：把自己的巧克力给同学吃，与句意相符。"}, {"text": "咀嚼", "is_correct": false, "explanation": "语义：“咀嚼”指嚼碎食物，不能表示把东西给别人。"}, {"text": "隐瞒", "is_correct": false, "explanation": "配价：“隐瞒”不能直接接“给”加接收者，句子不通。"}, {"text": "锁", "is_correct": false, "explanation": "语义：“锁”是把门或东西关起来，与“给同学”的意思不合。"}], "explanations": {"分享": "分享：把自己的巧克力给同学吃，与句意相符。", "咀嚼": "语义：“咀嚼”指嚼碎食物，不能表示把东西给别人。", "隐瞒": "配价：“隐瞒”不能直接接“给”加接收者，句子不通。", "锁": "语义：“锁”是把门或东西关起来，与“给同学”的意思不合。"}, "sentence_index": 0, "correct_answer": "分享"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小偷分享了我的钱包。", "explanation": "这里应该用〈偷〉。偷是暗中拿走别人的东西，分享是把自己有的东西给别人一起拥有，两者不是同一回事。"}, {"text": "他喜欢分享朋友。", "explanation": "这里应该用〈结交〉。结交是与人交往成为朋友，分享是把东西或快乐给人一起拥有，不能说分享朋友。"}, {"text": "他去年分享了五公斤体重。", "explanation": "这里应该用〈增加〉。体重的增减要说增加或减少，分享不能用于体重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分享", "is_correct": true, "explanation": "分享：把苹果给邻居，让邻居也能享用，与句意相符。"}, {"text": "埋", "is_correct": false, "explanation": "语义：“埋”指放在土里，与把苹果给邻居的意思不合。"}, {"text": "收割", "is_correct": false, "explanation": "配价：“收割”不能接“给邻居”这样的接收者，句子不通。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指摩擦去掉污物，与把苹果给人的意思不合。"}], "explanations": {"分享": "分享：把苹果给邻居，让邻居也能享用，与句意相符。", "埋": "语义：“埋”指放在土里，与把苹果给邻居的意思不合。", "收割": "配价：“收割”不能接“给邻居”这样的接收者，句子不通。", "擦": "语义：“擦”指摩擦去掉污物，与把苹果给人的意思不合。"}, "sentence_index": 6, "correct_answer": "分享"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钱分享在银行里。", "explanation": "这里应该用〈保管〉。保管是把东西存放好，分享是把东西给别人一起用。"}, {"text": "他把快乐分享给了墙。", "explanation": "这里应该用〈诉说〉。诉说是对人说出心事，分享快乐的对象应是能一起感受的人，墙不能分享快乐。"}, {"text": "他很快分享了一门外语。", "explanation": "这里应该用〈掌握〉。掌握知识是自己学会，不是给别人一起拥有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把蛋糕分享了给我们。", "corrected_sentence": "妈妈把蛋糕分享给了我们。", "error_description": "错误：“分享了给”；正确：“分享给了”。“给”是分享的补充成分，“了”应放在“给”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前不分享过这个蛋糕。", "corrected_sentence": "我们以前没分享过这个蛋糕。", "error_description": "错误：“不分享过”；正确：“没分享过”。表示没有过某种经历要用“没……过”，“不”不能与体标“过”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
