INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23700, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "创造某个重要东西的人。", "primary_collocate": null, "pronunciation": "dì zào zhě", "ipa": "ti˥˩ tsɑʊ˥˩ ʈʂɤ˨˩", "syllable_count": 3, "sentences": [{"text": "他们是这个奇迹的缔造者。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们每个人都是和平的缔造者。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个团队是历史的缔造者。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人是城市繁荣的缔造者。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都说他是幸福生活的缔造者。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家是新时代的缔造者之一。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些工人是这座大桥的缔造者。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不是旁观者，而是这个故事的缔造者。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人是未来世界的缔造者。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位建筑师是这座城市许多地标的缔造者。", "target_word": "缔造者", "complexity_tier": "T3", "furigana": "zhè wèi jiànzhùshī shì zhè zuò chéngshì xǔduō dìbiāo de dìzàozhě.", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "締造者", "label": "繁体"}], "register": "书面", "sense_fingerprint": "缔造者：创造和平、奇迹等重要事物的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caac8116-bbb0-40db-b2bd-488d2c40e0ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23700, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小偷", "is_correct": false, "explanation": "语义：“奇迹”是值得赞美的事物，小偷与“创造奇迹”的关系不合。"}, {"text": "缔造者", "is_correct": true, "explanation": "“缔造者”指创造重要事物的人，与“这个奇迹”搭配，符合句子语境。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人是患病的人，与“创造奇迹”的语义不合。"}, {"text": "垃圾", "is_correct": false, "explanation": "语域：“垃圾”是贬义口语词，与“奇迹”这种褒义的书面语域不合。"}], "explanations": {"小偷": "语义：“奇迹”是值得赞美的事物，小偷与“创造奇迹”的关系不合。", "缔造者": "“缔造者”指创造重要事物的人，与“这个奇迹”搭配，符合句子语境。", "病人": "语义：病人是患病的人，与“创造奇迹”的语义不合。", "垃圾": "语域：“垃圾”是贬义口语词，与“奇迹”这种褒义的书面语域不合。"}, "sentence_index": 0, "correct_answer": "缔造者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位缔造者擦干净了这张桌子。", "explanation": "这里应该用〈清洁工〉。擦桌子是清洁工的工作；缔造指创造重要事物或事业，不用于日常的清洁活动。"}, {"text": "这位缔造者修好了这台电脑。", "explanation": "这里应该用〈修理工〉。缔造指创造重要事物或事业，修好电脑是修理工的工作，不能用缔造者。"}, {"text": "这位缔造者洗好了这些碗。", "explanation": "这里应该用〈洗碗工〉。洗碗是洗碗工的工作，缔造指创造重要事物或事业，不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23700, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游客", "is_correct": false, "explanation": "语义：工人是建造者，游客是前来参观的人，二者身份不合。"}, {"text": "租客", "is_correct": false, "explanation": "搭配：“租客”需要被租住的对象，大桥不能被租住。"}, {"text": "废墟", "is_correct": false, "explanation": "语义：废墟是被毁坏后的遗迹，与“工人”作为创造者的身份矛盾。"}, {"text": "缔造者", "is_correct": true, "explanation": "“缔造者”指创造这座大桥的人，与“这些工人”的身份相符，符合句子语境。"}], "explanations": {"游客": "语义：工人是建造者，游客是前来参观的人，二者身份不合。", "租客": "搭配：“租客”需要被租住的对象，大桥不能被租住。", "废墟": "语义：废墟是被毁坏后的遗迹，与“工人”作为创造者的身份矛盾。", "缔造者": "“缔造者”指创造这座大桥的人，与“这些工人”的身份相符，符合句子语境。"}, "sentence_index": 6, "correct_answer": "缔造者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位缔造者种好了这片菜地。", "explanation": "这里应该用〈农民〉。种菜是农民的劳动，缔造指创造重要事物或事业，不能用于此。"}, {"text": "这位缔造者煮好了一锅粥。", "explanation": "这里应该用〈厨师〉。煮粥是厨师的工作，缔造指创造重要事物或事业，不能用于此。"}, {"text": "这位缔造者修好了这辆自行车。", "explanation": "这里应该用〈修车师傅〉。修自行车是修车师傅的工作，缔造不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23700, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是这座桥梁的一只缔造者。", "corrected_sentence": "他是这座桥梁的一位缔造者。", "error_description": "“缔造者”指人，量词应用“位”。“只”多用于动物，此处用“只”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是这个村庄的缔造者一。", "corrected_sentence": "他是这个村庄的缔造者之一。", "error_description": "“缔造者之一”是固定组合，“之”不能省略；这里漏掉了“之”，应为“缔造者之一”，“缔造者一”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
