INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23702, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cd34188-17c6-47c1-8f08-88bb4cf3beef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23702, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "宇宙是所有的东西，包括星星、地球和我们。", "primary_collocate": null, "pronunciation": "yǔ zhòu", "ipa": "y˨˩ ʈʂoʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "宇宙里有星星、地球，也有我们。", "target_word": "宇宙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳只是宇宙中的一颗小星星。", "target_word": "宇宙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宇宙大得没有人能走到头。", "target_word": "宇宙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子问妈妈：“宇宙有多大？”", "target_word": "宇宙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书上说，宇宙已经有一百多亿岁了。", "target_word": "宇宙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们住的地球，在宇宙里很小很小。", "target_word": "宇宙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥常常仰望宇宙，发呆很久。", "target_word": "宇宙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上我们躺在草地上，看着宇宙里的星星。", "target_word": "宇宙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宇宙这么大，也许还有别的生命。", "target_word": "宇宙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸带我去科学馆看关于宇宙的展览。", "target_word": "宇宙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宇宙飞船", "label": "复合"}, {"form": "宇宙空间", "label": "复合"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "宇宙|包含星星、地球和我们的一切", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7149fe61-a30a-47f9-9a43-5bf7b6a4bd0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23702, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书包", "is_correct": false, "explanation": "语义：书包是装书本的小袋子，装不下星星、地球和我们。"}, {"text": "宇宙", "is_correct": true, "explanation": "宇宙是所有东西的总和，包括星星、地球和我们，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "体貌：冰箱体积有限，不可能装下星星、地球和我们。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌是放置物品的家具，不能包含星星、地球和我们。"}], "explanations": {"书包": "语义：书包是装书本的小袋子，装不下星星、地球和我们。", "宇宙": "宇宙是所有东西的总和，包括星星、地球和我们，符合句意。", "冰箱": "体貌：冰箱体积有限，不可能装下星星、地球和我们。", "书桌": "语义：书桌是放置物品的家具，不能包含星星、地球和我们。"}, "sentence_index": 0, "correct_answer": "宇宙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的宇宙有三层楼。", "explanation": "这里应该用〈房子〉。宇宙指所有东西的总和，不能用来指一幢有三层楼的房子。"}, {"text": "我在夜空中看到了一张宇宙。", "explanation": "这里应该用〈个〉。“张”用于纸、桌子等平面的东西，不能用于宇宙。"}, {"text": "我们学校的宇宙很大，有很多教学楼。", "explanation": "这里应该用〈学校〉。宇宙包含一切，不能作为某所学校的范围，也不能说它有很多教学楼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cd34188-17c6-47c1-8f08-88bb4cf3beef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23702, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宇宙", "is_correct": true, "explanation": "“仰望宇宙”是常见搭配，指抬头望向广阔的天空，符合句意。"}, {"text": "毛巾", "is_correct": false, "explanation": "搭配：“仰望”的对象是天空、星空等高远之物，毛巾不能被仰望。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：钥匙是小件物品，不能作为“仰望”的对象，“仰望钥匙”不成话。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：冰箱是家用电器，不能作为“仰望”的对象。"}], "explanations": {"宇宙": "“仰望宇宙”是常见搭配，指抬头望向广阔的天空，符合句意。", "毛巾": "搭配：“仰望”的对象是天空、星空等高远之物，毛巾不能被仰望。", "钥匙": "搭配：钥匙是小件物品，不能作为“仰望”的对象，“仰望钥匙”不成话。", "冰箱": "搭配：冰箱是家用电器，不能作为“仰望”的对象。"}, "sentence_index": 6, "correct_answer": "宇宙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌子上有很多宇宙。", "explanation": "这里应该用〈东西〉。宇宙指天体与时空的总称，不是可以摆在桌上的具体物品，不能说“桌子上有很多宇宙”。"}, {"text": "妈妈把宇宙煮成了汤。", "explanation": "“煮”的对象只能是食材，宇宙是天地万物的总和，不能被煮。"}, {"text": "我们在厨房准备宇宙。", "explanation": "这里应该用〈食物〉。“准备”的对象是食材、饭菜等，宇宙是天体与时空的总称，不能被准备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cd34188-17c6-47c1-8f08-88bb4cf3beef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23702, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们都是一颗宇宙的一部分。", "corrected_sentence": "我们都是宇宙的一部分。", "error_description": "量词错误：“宇宙”不能用“颗”计量（“颗”用于小而圆的东西）。删去“一颗”，应为“我们都是宇宙的一部分”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cd34188-17c6-47c1-8f08-88bb4cf3beef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23702, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们生活在一座奇妙的宇宙里。", "corrected_sentence": "我们生活在一个奇妙的宇宙里。", "error_description": "“宇宙”的量词应为“个”。“座”用于山、桥、建筑等，不能用来计量宇宙。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cd34188-17c6-47c1-8f08-88bb4cf3beef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
