INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23708, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "妈妈肚子里有小宝宝，小宝宝慢慢长大，就叫孕育。", "primary_collocate": null, "pronunciation": "yùn yù", "ipa": "yn˥˩ y˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈的肚子里正在孕育着一个小宝宝。", "target_word": "孕育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正在孕育一个宝宝，已经六个月了。", "target_word": "孕育", "complexity_tier": "T3", "furigana": "tā zhèngzài yùnyù yí gè bǎobao, yǐjīng liù gè yuè le.", "sentence_source": "generated"}, {"text": "母亲孕育孩子非常辛苦。", "target_word": "孕育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女人孕育生命需要很多爱和照顾。", "target_word": "孕育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她怀着希望孕育着第二个孩子。", "target_word": "孕育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孕育宝宝的这几个月，妈妈吃得很健康。", "target_word": "孕育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母猫的肚子里正在孕育一窝小猫。", "target_word": "孕育", "complexity_tier": "T3", "furigana": "mǔ māo de dùzi lǐ zhèngzài yùnyù yì wō xiǎo māo.", "sentence_source": "generated"}, {"text": "妈妈说孕育我的时候，她最爱吃苹果。", "target_word": "孕育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孕育一个孩子，妈妈要吃很多苦。", "target_word": "孕育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶当年孕育爸爸的时候住在乡下。", "target_word": "孕育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "孕育着", "label": "进行体"}, {"form": "孕育了", "label": "完成体"}], "register": "中性", "sense_fingerprint": "孕育：母体怀着胎儿，使其慢慢长大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7149fe61-a30a-47f9-9a43-5bf7b6a4bd0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23708, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "孕育", "is_correct": true, "explanation": "正确。“孕育”指母体怀着胎儿，与“肚子里”的语境相符。"}, {"text": "哺乳", "is_correct": false, "explanation": "语义：“哺乳”指给已出生的婴儿喂奶，胎儿在肚子里无法被哺乳，与语境矛盾。"}, {"text": "哄", "is_correct": false, "explanation": "搭配：“哄”用于哄已出生的孩子，不用于肚子里的胎儿。"}, {"text": "哺育", "is_correct": false, "explanation": "语义：“哺育”指喂养已出生的幼儿，与“肚子里”的语境矛盾。"}], "explanations": {"孕育": "正确。“孕育”指母体怀着胎儿，与“肚子里”的语境相符。", "哺乳": "语义：“哺乳”指给已出生的婴儿喂奶，胎儿在肚子里无法被哺乳，与语境矛盾。", "哄": "搭配：“哄”用于哄已出生的孩子，不用于肚子里的胎儿。", "哺育": "语义：“哺育”指喂养已出生的幼儿，与“肚子里”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "孕育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶孕育了一锅香甜的粥。", "explanation": "这里应该用〈煮〉。孕育只指怀胎，煮粥要用煮。"}, {"text": "工厂孕育了一批汽车。", "explanation": "这里应该用〈生产〉。孕育只用于怀胎，工厂制造汽车要用生产。"}, {"text": "农场孕育了很多鸡。", "explanation": "这里应该用〈饲养〉。孕育不用于人工喂养牲畜，饲养鸡要用饲养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cd34188-17c6-47c1-8f08-88bb4cf3beef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23708, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "孕育", "is_correct": true, "explanation": "正确。“孕育一窝小猫”指母猫怀着胎儿，与“肚子里”的语境相符。"}, {"text": "饲养", "is_correct": false, "explanation": "语义：“饲养”指喂养已出生的动物，与“肚子里”的语境不符。"}, {"text": "生长", "is_correct": false, "explanation": "配价：“生长”是不及物动词，后面不能直接带“一窝小猫”作宾语。"}, {"text": "陪伴", "is_correct": false, "explanation": "语义：“陪伴”需要对方在身边，胎儿在肚子里，与语境矛盾。"}], "explanations": {"孕育": "正确。“孕育一窝小猫”指母猫怀着胎儿，与“肚子里”的语境相符。", "饲养": "语义：“饲养”指喂养已出生的动物，与“肚子里”的语境不符。", "生长": "配价：“生长”是不及物动词，后面不能直接带“一窝小猫”作宾语。", "陪伴": "语义：“陪伴”需要对方在身边，胎儿在肚子里，与语境矛盾。"}, "sentence_index": 6, "correct_answer": "孕育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "师傅孕育了一辆旧自行车。", "explanation": "这里应该用〈修理〉。孕育只指怀胎，修理旧车要用修理。"}, {"text": "印刷厂每天孕育几千本书。", "explanation": "这里应该用〈印刷〉。孕育只指怀胎，印刷书籍要用印刷。"}, {"text": "建筑队孕育了一座学校。", "explanation": "这里应该用〈建造〉。孕育只指怀胎，建造学校要用建造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cd34188-17c6-47c1-8f08-88bb4cf3beef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23708, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈孕育得弟弟很辛苦。", "corrected_sentence": "妈妈孕育弟弟很辛苦。", "error_description": "错误：“孕育得弟弟”，正确：“孕育弟弟”。“得”是补语标记，不能插在动词“孕育”和宾语“弟弟”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cd34188-17c6-47c1-8f08-88bb4cf3beef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23708, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在孕育了一个宝宝，已经快生了。", "corrected_sentence": "她在孕育一个宝宝，已经快生了。", "error_description": "错误：“在孕育了”，正确：“在孕育”。“在”表示动作正在进行，与完成体“了”不能同时使用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cd34188-17c6-47c1-8f08-88bb4cf3beef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23710, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "温和", "is_correct": true, "explanation": "正确。“温和”指不猛烈、不强硬，与“激烈”的动作猛、用力相对。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”形容清晰明白，与“激烈”没有反义关系。"}, {"text": "高大", "is_correct": false, "explanation": "无关：“高大”形容身材或体积，与“激烈”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”形容光线或颜色，与“激烈”没有反义关系。"}], "correct_answer": "温和", "explanations": {"温和": "正确。“温和”指不猛烈、不强硬，与“激烈”的动作猛、用力相对。", "清楚": "无关：“清楚”形容清晰明白，与“激烈”没有反义关系。", "高大": "无关：“高大”形容身材或体积，与“激烈”没有反义关系。", "明亮": "无关：“明亮”形容光线或颜色，与“激烈”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cd34188-17c6-47c1-8f08-88bb4cf3beef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
