INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23714, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "像魔法一样，很奇怪很漂亮。", "primary_collocate": null, "pronunciation": "qí huàn", "ipa": "t͡ɕʰi˧˥ xwan˥˩", "syllable_count": 2, "sentences": [{"text": "这座花园又奇幻又漂亮。", "target_word": "奇幻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她梦见了一个奇幻的地方。", "target_word": "奇幻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪地里的灯光看起来很奇幻。", "target_word": "奇幻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书里的森林非常奇幻。", "target_word": "奇幻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小女孩站在奇幻的月光下，像一位公主。", "target_word": "奇幻", "complexity_tier": "T3", "furigana": "xiǎo nǚ hái zhàn zài qí huàn de yuè guāng xià, xiàng yí wèi gōng zhǔ.", "sentence_source": "generated"}, {"text": "夜晚的海边亮着蓝色的光，十分奇幻。", "target_word": "奇幻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥带我看了一场奇幻的灯光表演。", "target_word": "奇幻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏的画面很奇幻，我很喜欢。", "target_word": "奇幻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彩色的泡泡在空中飞，真奇幻。", "target_word": "奇幻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们走进了奇幻的城堡。", "target_word": "奇幻", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "奇幻小说", "label": "复合"}, {"form": "奇幻电影", "label": "复合"}], "register": "中性", "sense_fingerprint": "像魔法一样，奇怪又漂亮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd32baaa-958b-48ac-9588-24e2c9493849') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23714, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奇幻", "is_correct": true, "explanation": "正确：“又奇幻又漂亮”描写花园如幻想般美丽，与后半句“漂亮”相合。"}, {"text": "丑陋", "is_correct": false, "explanation": "语义：“丑陋”与后半句“漂亮”构成直接矛盾。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”多说声音或场所的吵闹，不用来形容花园的景致。"}, {"text": "枯黄", "is_correct": false, "explanation": "体貌：“枯黄”描写草木的颜色和状态，与“漂亮”构成矛盾。"}], "explanations": {"奇幻": "正确：“又奇幻又漂亮”描写花园如幻想般美丽，与后半句“漂亮”相合。", "丑陋": "语义：“丑陋”与后半句“漂亮”构成直接矛盾。", "嘈杂": "搭配：“嘈杂”多说声音或场所的吵闹，不用来形容花园的景致。", "枯黄": "体貌：“枯黄”描写草木的颜色和状态，与“漂亮”构成矛盾。"}, "sentence_index": 0, "correct_answer": "奇幻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑得很奇幻。", "explanation": "这里应该用〈快〉。奇幻形容像魔法一样奇特美丽的样子，形容跑的速度要用快，不能用奇幻。"}, {"text": "这个谣言很奇幻。", "explanation": "这里应该用〈离奇〉。奇幻要求像魔法一样既奇特又美，谣言只是稀奇古怪的假消息，没有美感，要用离奇。"}, {"text": "这个问题很奇幻。", "explanation": "这里应该用〈简单〉。奇幻形容像魔法一样的奇美，问题容易要用简单，不能用奇幻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd865e799-76d9-49a4-b65e-f0454572eb57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23714, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奇幻", "is_correct": true, "explanation": "正确：“一场奇幻的灯光表演”描写如幻想般的灯光效果，与“看了一场”相合。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”说的是空气或物体，不用来修饰“表演”。"}, {"text": "闷热", "is_correct": false, "explanation": "搭配：“闷热”形容天气，不用来修饰“灯光表演”。"}, {"text": "沙哑", "is_correct": false, "explanation": "搭配：「沙哑」形容嗓音，不能用来修饰「灯光表演」。"}], "explanations": {"奇幻": "正确：“一场奇幻的灯光表演”描写如幻想般的灯光效果，与“看了一场”相合。", "潮湿": "搭配：“潮湿”说的是空气或物体，不用来修饰“表演”。", "闷热": "搭配：“闷热”形容天气，不用来修饰“灯光表演”。", "沙哑": "搭配：「沙哑」形容嗓音，不能用来修饰「灯光表演」。"}, "sentence_index": 6, "correct_answer": "奇幻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试很奇幻。", "explanation": "这里应该用〈难〉。奇幻形容像魔法一样的奇美景象，考试难要用“难”，不能用奇幻。"}, {"text": "这份合同的条款很奇幻。", "explanation": "这里应该用〈晦涩〉。奇幻指幻想般的美，条款难懂要用晦涩。"}, {"text": "他的体温很奇幻。", "explanation": "这里应该用〈高〉。奇幻形容奇美的幻想景象，体温高要用“高”，不能用奇幻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd865e799-76d9-49a4-b65e-f0454572eb57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些彩灯让广场显得很奇幻着。", "corrected_sentence": "这些彩灯让广场显得很奇幻。", "error_description": "体标错误：“着”表示动作或状态的持续，不能接形容词“奇幻”作表示性质的谓语。错误形式“很奇幻着”，正确形式“很奇幻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd865e799-76d9-49a4-b65e-f0454572eb57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23714, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜晚的森林里有一位奇幻的城堡。", "corrected_sentence": "夜晚的森林里有一座奇幻的城堡。", "error_description": "量词错误：城堡应用量词「座」，「位」用于人。错误形式「一位奇幻的城堡」，正确形式「一座奇幻的城堡」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd865e799-76d9-49a4-b65e-f0454572eb57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
