INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23716, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cd34188-17c6-47c1-8f08-88bb4cf3beef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23716, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个人心里有墙，不能好好说话。", "primary_collocate": null, "pronunciation": "gé hé", "ipa": "kɤ˧˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他和哥哥之间有隔阂，很少说话。", "target_word": "隔阂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间有了隔阂，就不容易好好谈。", "target_word": "隔阂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夫妻之间有了隔阂，两个人很少说话。", "target_word": "隔阂", "complexity_tier": "T3", "furigana": "fū qī zhī jiān yǒu le gé hé, liǎng gè rén hěn shǎo shuō huà.", "sentence_source": "generated"}, {"text": "她想和妈妈说话，可是心里有隔阂。", "target_word": "隔阂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们之间没有隔阂，什么都可以说。", "target_word": "隔阂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吵架以后，两个人之间多了一道隔阂。", "target_word": "隔阂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新同学和老同学之间还有隔阂。", "target_word": "隔阂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明和同桌有隔阂，所以不一起玩。", "target_word": "隔阂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的隔阂太深，谁也不先开口。", "target_word": "隔阂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你先说话，别让隔阂越来越大。", "target_word": "隔阂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一层隔阂", "label": "量词：层"}, {"form": "一道隔阂", "label": "量词：道"}], "register": "中性", "sense_fingerprint": "隔阂：两人心里有距离，无法好好沟通", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7149fe61-a30a-47f9-9a43-5bf7b6a4bd0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23716, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "隔阂", "is_correct": true, "explanation": "「隔阂」指彼此心里有距离，与「之间有」搭配，正好解释了「很少说话」的原因。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：「饭菜」不是人际关系，「他和哥哥之间有饭菜」说不通。"}, {"text": "工资", "is_correct": false, "explanation": "语义：「工资」与兄弟之间的关系无关，句子无法理解。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：「之间有」后接关系或感情，「体积」是物体的性质，不能说「之间有体积」。"}], "explanations": {"隔阂": "「隔阂」指彼此心里有距离，与「之间有」搭配，正好解释了「很少说话」的原因。", "饭菜": "语义：「饭菜」不是人际关系，「他和哥哥之间有饭菜」说不通。", "工资": "语义：「工资」与兄弟之间的关系无关，句子无法理解。", "体积": "搭配：「之间有」后接关系或感情，「体积」是物体的性质，不能说「之间有体积」。"}, "sentence_index": 0, "correct_answer": "隔阂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两篇文章的字数之间有隔阂，读者很难比较。", "explanation": "这里应该用〈差距〉。隔阂只指人心里的距离，文章字数之间的不同要用差距。"}, {"text": "这条河成了我们回城路上的隔阂。", "explanation": "这里应该用〈障碍〉。隔阂指人心里的距离，不指河流这类挡住去路的实物。"}, {"text": "两家公司在谈判中爆发了隔阂。", "explanation": "这里应该用〈冲突〉。隔阂是一种状态，不能「爆发」；公司之间发生的对立事件要用〈冲突〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cd34188-17c6-47c1-8f08-88bb4cf3beef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隔阂", "is_correct": true, "explanation": "「隔阂」指彼此心里有距离，与「还有」搭配，说明两个群体之间仍存在心理上的距离。"}, {"text": "作业", "is_correct": false, "explanation": "语义：「作业」是学生要完成的任务，不是人与人之间的存在，句子不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：「雨伞」是实物，「新同学和老同学之间还有雨伞」不成话。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：「之间还有」接的是关系或感情，「体温」是个人身体的状态，不能这样用。"}], "explanations": {"隔阂": "「隔阂」指彼此心里有距离，与「还有」搭配，说明两个群体之间仍存在心理上的距离。", "作业": "语义：「作业」是学生要完成的任务，不是人与人之间的存在，句子不通。", "雨伞": "语义：「雨伞」是实物，「新同学和老同学之间还有雨伞」不成话。", "体温": "搭配：「之间还有」接的是关系或感情，「体温」是个人身体的状态，不能这样用。"}, "sentence_index": 6, "correct_answer": "隔阂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子中间砌了一道隔阂，把两边隔开了。", "explanation": "隔阂指人与人之间思想、感情上的距离，不指砌出来的墙。这里说的是实物，与隔阂的意思不符。"}, {"text": "新同学和老同学之间还立着一座隔阂。", "explanation": "这里量词用错。〈座〉用于山、桥、楼等大而固定的东西，隔阂应该用〈层〉或〈道〉。"}, {"text": "他们之间有一把隔阂，谁也不肯先开口。", "explanation": "这里量词用错。〈把〉用于有柄的器具，隔阂应该用〈层〉或〈道〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cd34188-17c6-47c1-8f08-88bb4cf3beef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和弟弟之间有一颗隔阂，很少说话。", "corrected_sentence": "我和弟弟之间有一层隔阂，很少说话。", "error_description": "量词错误：「颗」用于小而圆的东西，不能修饰「隔阂」。应改为「层」，表示一层心理上的距离。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cd34188-17c6-47c1-8f08-88bb4cf3beef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我和同事之间是隔阂，平时很少聊天。", "corrected_sentence": "我和同事之间有隔阂，平时很少聊天。", "error_description": "动词错误：「是」表示等同，不能用来说明两者之间存在隔阂。应改为「有」，表示「之间存在」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cd34188-17c6-47c1-8f08-88bb4cf3beef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
