INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23720, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中国很大的一块土地。", "primary_collocate": null, "pronunciation": "dà lù", "ipa": "ta˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "他是在大陆长大的，后来去了台湾。", "target_word": "大陆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大陆有很多大城市，比如上海和北京。", "target_word": "大陆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明年我打算去大陆读书。", "target_word": "大陆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我朋友在大陆开了一家饭馆。", "target_word": "大陆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台湾的朋友来大陆看我。", "target_word": "大陆", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大陆的高铁又快又方便。", "target_word": "大陆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在大陆工作了五年，说一口好普通话。", "target_word": "大陆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从台湾飞到大陆只要两个小时。", "target_word": "大陆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大陆的人口很多，面积也很大。", "target_word": "大陆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影在大陆很有名，在香港也有人看。", "target_word": "大陆", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "大陸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "地理名词：与台湾、香港相对而言的中国大陆地区", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd32baaa-958b-48ac-9588-24e2c9493849') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23720, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大陆", "is_correct": true, "explanation": "正确：大陆（dà lù），指中国大陆地区。"}, {"text": "大炉", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，大炉指大型的炉子。"}, {"text": "大怒", "is_correct": false, "explanation": "nù 与 lù 声母不同（n/l），大怒指非常生气。"}, {"text": "大户", "is_correct": false, "explanation": "hù 与 lù 声母不同（h/l），大户指规模大或有钱有势的家庭。"}, {"text": "道路", "is_correct": false, "explanation": "dào 与 dà 韵母不同，道路指供车马行人通行的路。"}], "explanations": {"大陆": "正确：大陆（dà lù），指中国大陆地区。", "大炉": "lú（第二声）与 lù（第四声）声调不同，大炉指大型的炉子。", "大怒": "nù 与 lù 声母不同（n/l），大怒指非常生气。", "大户": "hù 与 lù 声母不同（h/l），大户指规模大或有钱有势的家庭。", "道路": "dào 与 dà 韵母不同，道路指供车马行人通行的路。"}, "sentence_index": null, "correct_answer": "大陆"}, "level_3": {"options": [{"text": "大陆", "is_correct": true, "explanation": "正确：“在大陆长大”指在中国大陆地区成长，与后文“去了台湾”相对应。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：长大要在家庭生活的地方，“图书馆”不是成长的处所。"}, {"text": "银河", "is_correct": false, "explanation": "搭配：“在……长大”要用地方或社会环境，“银河”不能这样搭配。"}, {"text": "办公室", "is_correct": false, "explanation": "搭配：“办公室”是工作场所，不用来说“在……长大”。"}], "explanations": {"大陆": "正确：“在大陆长大”指在中国大陆地区成长，与后文“去了台湾”相对应。", "图书馆": "语义：长大要在家庭生活的地方，“图书馆”不是成长的处所。", "银河": "搭配：“在……长大”要用地方或社会环境，“银河”不能这样搭配。", "办公室": "搭配：“办公室”是工作场所，不用来说“在……长大”。"}, "sentence_index": 0, "correct_answer": "大陆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在江苏大陆工作了五年。", "explanation": "这里应该用〈省〉。江苏是省级行政区，大陆指很大的一块土地，不能用来指一个省。"}, {"text": "他的大陆很旧。", "explanation": "这里应该用〈汽车〉。大陆指很大的一块土地，不能用来形容车的新旧，形容车要用汽车。"}, {"text": "我们班有四十个大陆。", "explanation": "这里应该用〈学生〉。大陆指很大的一块土地，不能用来指班里的人，要用学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd865e799-76d9-49a4-b65e-f0454572eb57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23720, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大陆", "is_correct": true, "explanation": "正确：大陆（dà lù），指中国大陆地区。"}, {"text": "带路", "is_correct": false, "explanation": "dài 与 dà 韵母不同，带路指给人领路。"}, {"text": "大树", "is_correct": false, "explanation": "shù 与 lù 声母不同（sh/l），大树指高大的树。"}, {"text": "大步", "is_correct": false, "explanation": "bù 与 lù 声母不同（b/l），大步指迈开的大步子。"}, {"text": "大度", "is_correct": false, "explanation": "dù 与 lù 声母不同（d/l），大度指心胸宽广、不计较。"}], "explanations": {"大陆": "正确：大陆（dà lù），指中国大陆地区。", "带路": "dài 与 dà 韵母不同，带路指给人领路。", "大树": "shù 与 lù 声母不同（sh/l），大树指高大的树。", "大步": "bù 与 lù 声母不同（b/l），大步指迈开的大步子。", "大度": "dù 与 lù 声母不同（d/l），大度指心胸宽广、不计较。"}, "sentence_index": null, "correct_answer": "大陆"}, "level_3": {"options": [{"text": "大陆", "is_correct": true, "explanation": "正确：“在大陆工作”指在中国大陆工作，与“说一口好普通话”相合。"}, {"text": "童年", "is_correct": false, "explanation": "语义：「童年」是人生的一段时期，不是工作场所，「在童年工作」不成立。"}, {"text": "晚霞", "is_correct": false, "explanation": "语义：「晚霞」是天边的景象，不是工作场所，「在晚霞工作」句意不通。"}, {"text": "梦境", "is_correct": false, "explanation": "语义：“梦境”不是真实的工作地点，与“工作了五年”“说普通话”相矛盾。"}], "explanations": {"大陆": "正确：“在大陆工作”指在中国大陆工作，与“说一口好普通话”相合。", "童年": "语义：「童年」是人生的一段时期，不是工作场所，「在童年工作」不成立。", "晚霞": "语义：「晚霞」是天边的景象，不是工作场所，「在晚霞工作」句意不通。", "梦境": "语义：“梦境”不是真实的工作地点，与“工作了五年”“说普通话”相矛盾。"}, "sentence_index": 6, "correct_answer": "大陆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "北京是一个大陆。", "explanation": "这里应该用〈城市〉。北京是城市，大陆指大片陆地或中国大陆地区，不能用来指城市。"}, {"text": "这座博物馆是一个大陆。", "explanation": "这里应该用〈建筑〉。博物馆是建筑物，大陆是地理概念，不能这样用。"}, {"text": "这张桌子是一个大陆。", "explanation": "这里应该用〈桌子〉。大陆指很大的一块土地，不能说一张桌子是大陆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd865e799-76d9-49a4-b65e-f0454572eb57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他第一次去在大陆。", "corrected_sentence": "他第一次去大陆。", "error_description": "错误：「在」插在动词「去」和处所宾语「大陆」之间，「去在大陆」不成句。正确：「去大陆」，「去」后直接接处所宾语，不加「在」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd865e799-76d9-49a4-b65e-f0454572eb57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在大陆来，说一口普通话。", "corrected_sentence": "我从大陆来，说一口普通话。", "error_description": "错误：表示起点要用介词“从”，“在”表示所在地，“在大陆来”不成句。正确：“从大陆来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd865e799-76d9-49a4-b65e-f0454572eb57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
