INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23722, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "跑着去抓前面的人或东西。", "primary_collocate": null, "pronunciation": "zhuī zhú", "ipa": "ʈʂuei˥ ʈʂu˧˥", "syllable_count": 2, "sentences": [{"text": "孩子们在公园里追逐蝴蝶。", "target_word": "追逐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗追逐着皮球，跑得很快。", "target_word": "追逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两只猫在院子里互相追逐。", "target_word": "追逐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察追逐小偷，跑了很远。", "target_word": "追逐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "狮子追逐着一只小鹿。", "target_word": "追逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在雪地里追逐打闹。", "target_word": "追逐", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小男孩追逐着气球跑过了马路。", "target_word": "追逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候常和朋友在河边追逐。", "target_word": "追逐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "狗在后面追逐那只兔子，兔子拼命地跑。", "target_word": "追逐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，不要在楼道里追逐。", "target_word": "追逐", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "追逐着", "label": "体标"}, {"form": "追逐过", "label": "体标"}, {"form": "追逐了", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：跑着去抓前面的人或动物，具体的追赶动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd32baaa-958b-48ac-9588-24e2c9493849') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23722, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "追逐", "is_correct": true, "explanation": "正确：「追逐蝴蝶」指跑着去抓蝴蝶，与公园里的场景一致。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：「修剪」用于草木、头发等，不能用于蝴蝶。"}, {"text": "送", "is_correct": false, "explanation": "配价：「送」需要说明送给谁，句中只有宾语「蝴蝶」，结构不完整。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：「怀念」是对过去事物的思念，与「在公园里」眼前的动作不合。"}], "explanations": {"追逐": "正确：「追逐蝴蝶」指跑着去抓蝴蝶，与公园里的场景一致。", "修剪": "搭配：「修剪」用于草木、头发等，不能用于蝴蝶。", "送": "配价：「送」需要说明送给谁，句中只有宾语「蝴蝶」，结构不完整。", "怀念": "语义：「怀念」是对过去事物的思念，与「在公园里」眼前的动作不合。"}, "sentence_index": 0, "correct_answer": "追逐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在超市里追逐着一台冰箱。", "explanation": "这里应该用〈搬运〉。冰箱不能跑，追逐只用于能跑动的人或动物，应说搬运冰箱。"}, {"text": "妈妈在路口追逐着红绿灯。", "explanation": "这里应该用〈等待〉。红绿灯不会跑，追逐只用于跑着去抓的对象，应说等待红绿灯。"}, {"text": "她轻轻追逐着小猫的头。", "explanation": "这里应该用〈抚摸〉。追逐是跑动的动作，不能用于轻轻地接触。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd865e799-76d9-49a4-b65e-f0454572eb57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追逐", "is_correct": true, "explanation": "正确：「追逐着气球」指跑动时追着气球，与句中「跑过了马路」相符。"}, {"text": "批评", "is_correct": false, "explanation": "语义：「批评」的对象须是人，不能用于气球，「批评着气球跑过了马路」句意不通。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：「饲养」针对动物，不能用于「气球」。"}, {"text": "陈列", "is_correct": false, "explanation": "语义：「陈列」指摆放展示，是静止的，与「跑过了马路」的动作矛盾。"}], "explanations": {"追逐": "正确：「追逐着气球」指跑动时追着气球，与句中「跑过了马路」相符。", "批评": "语义：「批评」的对象须是人，不能用于气球，「批评着气球跑过了马路」句意不通。", "饲养": "搭配：「饲养」针对动物，不能用于「气球」。", "陈列": "语义：「陈列」指摆放展示，是静止的，与「跑过了马路」的动作矛盾。"}, "sentence_index": 6, "correct_answer": "追逐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们在教室里追逐作业。", "explanation": "这里应该用〈讨论〉。作业不能被追逐，追逐的对象必须是能跑动的人或动物。"}, {"text": "妈妈在厨房追逐蔬菜。", "explanation": "这里应该用〈清洗〉。蔬菜不会跑，追逐只能用于跑着去抓的对象。"}, {"text": "农民在地里追逐麦子。", "explanation": "这里应该用〈收割〉。麦子不会跑，追逐只用于跑着去抓的对象，应说收割麦子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd865e799-76d9-49a4-b65e-f0454572eb57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "猎狗一路追逐了着野兔，跑进了树林。", "corrected_sentence": "猎狗一路追逐着野兔，跑进了树林。", "error_description": "错误：「追逐」后同时用了「了」和「着」，二者不能并用，「追逐了着野兔」不成句。正确：「追逐着野兔」，只用「着」表示正在进行的动作。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd865e799-76d9-49a4-b65e-f0454572eb57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟弟曾经追逐着过一只蜻蜓。", "corrected_sentence": "弟弟曾经追逐过一只蜻蜓。", "error_description": "错误：「追逐」后同时用了「着」和「过」，二者不能并用，「追逐着过」不成句。正确：「曾经追逐过一只蜻蜓」，只用「过」表示经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd865e799-76d9-49a4-b65e-f0454572eb57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
