INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23726, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd865e799-76d9-49a4-b65e-f0454572eb57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23726, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做成了很好的事。", "primary_collocate": null, "pronunciation": "chéng jiù", "ipa": "ʈʂʰɤŋ˧˥ tɕiou˥˩", "syllable_count": 2, "sentences": [{"text": "拿到这个奖是他最大的成就。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们都为他的成就高兴。", "target_word": "成就", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子学会骑车，对他来说是个大成就。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小小的成就，让她很开心。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她写完了第一本书，这是很大的成就。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他跑完了全程，对自己的成就很满意。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司今年的成就，要谢谢大家的努力。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的成就让爸爸妈妈很骄傲。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做成这件事，是我们一起的成就。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从不跟别人说自己的成就。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "成就感", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：做成的值得骄傲的好事，生活中的成绩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd32baaa-958b-48ac-9588-24e2c9493849') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23726, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成就", "is_correct": true, "explanation": "正确：「最大的成就」指做成的最值得骄傲的事，与「拿到这个奖」相符。"}, {"text": "疾病", "is_correct": false, "explanation": "语义：「疾病」是不好的事，说拿奖是他最大的疾病，与句意相反。"}, {"text": "伤口", "is_correct": false, "explanation": "语义：「伤口」指身体的创伤，与「拿到这个奖」无关，句意不通。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：「最大的」可修饰成就、困难等，不能修饰「体温」。"}], "explanations": {"成就": "正确：「最大的成就」指做成的最值得骄傲的事，与「拿到这个奖」相符。", "疾病": "语义：「疾病」是不好的事，说拿奖是他最大的疾病，与句意相反。", "伤口": "语义：「伤口」指身体的创伤，与「拿到这个奖」无关，句意不通。", "体温": "搭配：「最大的」可修饰成就、困难等，不能修饰「体温」。"}, "sentence_index": 0, "correct_answer": "成就"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药的成就很明显。", "explanation": "这里应该用〈功效〉。成就指人做成的事，药物的作用要用〈功效〉。"}, {"text": "这个月他的成就比上个月多了两千块。", "explanation": "这里应该用〈收入〉。成就指做成的事，不能用来计算金钱，表示多了多少钱要用〈收入〉。"}, {"text": "他承认了自己的成就，并向大家道了歉。", "explanation": "这里应该用〈过失〉。成就是做成的好事，不能承认或道歉；承认错误并道歉要用〈过失〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd865e799-76d9-49a4-b65e-f0454572eb57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23726, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成就", "is_correct": true, "explanation": "正确：「公司今年的成就」指公司做成的事，与「要谢谢大家的努力」相符。"}, {"text": "梦话", "is_correct": false, "explanation": "语义：「梦话」是睡梦中说的话，不是值得感谢的工作成果，句意不通。"}, {"text": "鼾声", "is_correct": false, "explanation": "语义：「鼾声」是睡觉时的呼吸声，不是公司做成的事，句意不通。"}, {"text": "喷嚏", "is_correct": false, "explanation": "语义：「喷嚏」是身体的反应，不是工作成果，与「要谢谢大家的努力」不合。"}], "explanations": {"成就": "正确：「公司今年的成就」指公司做成的事，与「要谢谢大家的努力」相符。", "梦话": "语义：「梦话」是睡梦中说的话，不是值得感谢的工作成果，句意不通。", "鼾声": "语义：「鼾声」是睡觉时的呼吸声，不是公司做成的事，句意不通。", "喷嚏": "语义：「喷嚏」是身体的反应，不是工作成果，与「要谢谢大家的努力」不合。"}, "sentence_index": 6, "correct_answer": "成就"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他取得了一本很大的成就。", "explanation": "这里应该用〈项〉。「本」用于书籍，「成就」要用量词「项」。"}, {"text": "她拿到了一把很重要的成就。", "explanation": "这里应该用〈项〉。「把」用于有柄的器具，「成就」要用量词「项」。"}, {"text": "这次比赛我得到了一首大成就。", "explanation": "这里应该用〈项〉。「首」用于诗歌、歌曲，「成就」要用量词「项」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd865e799-76d9-49a4-b65e-f0454572eb57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父母为她成就高兴。", "corrected_sentence": "父母为她的成就高兴。", "error_description": "错误在于「她」和「成就」之间漏掉了定语标记「的」，应为「她的成就」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd865e799-76d9-49a4-b65e-f0454572eb57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是他最大的一颗成就。", "corrected_sentence": "这是他最大的一项成就。", "error_description": "量词错误：「颗」多用于粒状或球状的小东西，「成就」应用量词「项」，正确写法是「一项成就」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd865e799-76d9-49a4-b65e-f0454572eb57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23728, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd865e799-76d9-49a4-b65e-f0454572eb57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
