INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23732, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人或更多人想要得到同一个东西，就会抢来抢去。", "primary_collocate": null, "pronunciation": "zhēng duó", "ipa": "ʈʂɤŋ˥ tuo˧˥", "syllable_count": 2, "sentences": [{"text": "两只小猫正在争夺一条小鱼。", "target_word": "争夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兄弟俩争夺那个玩具，哭了起来。", "target_word": "争夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个孩子争夺着最后一块蛋糕。", "target_word": "争夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为了一个停车位争夺了半天。", "target_word": "争夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打折时，人们都在争夺便宜的衣服。", "target_word": "争夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人争夺那把椅子，谁也不让。", "target_word": "争夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟们在树下争夺地上的面包。", "target_word": "争夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球场上，球员们争夺着每一个球。", "target_word": "争夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，同学们争夺篮球场。", "target_word": "争夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟和妹妹争夺同一本书。", "target_word": "争夺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "争夺了", "label": "体标"}, {"form": "争夺着", "label": "体标"}, {"form": "争夺过", "label": "体标"}, {"form": "争夺战", "label": "复合"}], "register": "中性", "sense_fingerprint": "多人想得到同一样东西而互相抢夺", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0347f031-0355-40d8-bc8c-c972af0e07eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23732, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "争夺", "is_correct": true, "explanation": "正确：“两只小猫争夺一条小鱼”表示两者互相抢夺同一条鱼，与句意相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是机器或物品，不能用于“小鱼”。"}, {"text": "规划", "is_correct": false, "explanation": "语义：“规划”针对计划或工作，不能用于“小鱼”。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”指印刷发行书籍，与小猫和小鱼无关。"}], "explanations": {"争夺": "正确：“两只小猫争夺一条小鱼”表示两者互相抢夺同一条鱼，与句意相符。", "修理": "搭配：“修理”的对象是机器或物品，不能用于“小鱼”。", "规划": "语义：“规划”针对计划或工作，不能用于“小鱼”。", "出版": "语义：“出版”指印刷发行书籍，与小猫和小鱼无关。"}, "sentence_index": 0, "correct_answer": "争夺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "科学家正在争夺这种病毒。", "explanation": "这里应该用〈研究〉。争夺指争抢某物，不能用于对病毒的探究。"}, {"text": "我非常争夺你的帮助。", "explanation": "这里应该用〈感谢〉。争夺表示与人抢夺，不能用于表达感激。"}, {"text": "他争夺了自己的错误。", "explanation": "这里应该用〈承认〉。争夺指争抢某物，不能用于承认错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23e663ea-358d-453a-a4ef-eb088c2e2768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23732, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "争夺", "is_correct": true, "explanation": "正确：“小鸟们在树下争夺地上的面包”表示多只小鸟互相抢食，与句意相符。"}, {"text": "设计", "is_correct": false, "explanation": "语义：“设计”针对图纸或方案，不能用于“面包”。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”的对象是艺术品或风景，地上的面包无法被欣赏。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，不能用于“面包”。"}], "explanations": {"争夺": "正确：“小鸟们在树下争夺地上的面包”表示多只小鸟互相抢食，与句意相符。", "设计": "语义：“设计”针对图纸或方案，不能用于“面包”。", "欣赏": "语义：“欣赏”的对象是艺术品或风景，地上的面包无法被欣赏。", "唱": "语义：“唱”的对象是歌曲，不能用于“面包”。"}, "sentence_index": 6, "correct_answer": "争夺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他认真争夺了老师的问题。", "explanation": "这里应该用〈回答〉。争夺指争抢某物，不能用于回应问题。"}, {"text": "他每天都在争夺知识。", "explanation": "这里应该用〈学习〉。争夺指与人抢夺某物，学习知识不涉及与他人抢。"}, {"text": "我们要争夺交通规则。", "explanation": "这里应该用〈遵守〉。争夺指争抢某物，不能用于遵从规则。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23e663ea-358d-453a-a4ef-eb088c2e2768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23732, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们为这个奖品争夺着一次。", "corrected_sentence": "他们为这个奖品争夺过一次。", "error_description": "体标用错：表示经历的“过”被换成了“着”。“着”表示动作持续，不能与“一次”搭配；应说“争夺过一次”，“过”紧跟动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23e663ea-358d-453a-a4ef-eb088c2e2768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23732, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个人正着争夺那把伞。", "corrected_sentence": "两个人正在争夺那把伞。", "error_description": "体标用错：进行体应说“正在”，不能说“正着”。“着”不能放在“正”后、动词前；正确形式为“正在争夺”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23e663ea-358d-453a-a4ef-eb088c2e2768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
