INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23736, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人或事物在列表中的位置顺序。", "primary_collocate": null, "pronunciation": "pái míng", "ipa": "pʰaɪ˧˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "名单上他的排名在第二位。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看看这家饭店的排名。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站上的排名每天都会变。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个歌手的排名下降了。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子很在意自己的排名。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的排名比去年高了三位。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机游戏里有玩家的排名。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我你们队的排名。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排名最后的同学要加油。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，排名马上出来了。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排名表", "label": "复合"}, {"form": "总排名", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或事物在榜单中的先后位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0347f031-0355-40d8-bc8c-c972af0e07eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23736, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是可以排列名单的事物，“在第二位”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有名次，名单上不会排颜色。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材是外形，不会在名单上排出名次。"}, {"text": "排名", "is_correct": true, "explanation": "排名指在名单中的位置顺序，“在第二位”与之相符，符合句意。"}], "explanations": {"年龄": "语义：年龄不是可以排列名单的事物，“在第二位”说不通。", "颜色": "语义：颜色没有名次，名单上不会排颜色。", "身材": "体貌：身材是外形，不会在名单上排出名次。", "排名": "排名指在名单中的位置顺序，“在第二位”与之相符，符合句意。"}, "sentence_index": 0, "correct_answer": "排名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个歌手的排名下降了五公斤。", "explanation": "这里应该用〈体重〉。排名是位置，不能用“公斤”计量。"}, {"text": "这个歌手的排名是三十岁。", "explanation": "这里应该用〈年龄〉。排名表示位置，不能说明年龄。"}, {"text": "这个歌手的排名在台上唱歌。", "explanation": "这里应该用〈人〉作主语。排名表示位置，不能做“唱歌”的主语，唱歌要求主语是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23e663ea-358d-453a-a4ef-eb088c2e2768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23736, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温度", "is_correct": false, "explanation": "语义：温度不是玩家在游戏中可排列的属性，句子说不通。"}, {"text": "作息", "is_correct": false, "explanation": "搭配：“作息”指人的起居习惯，与游戏里的排列次序不搭。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温没有先后次序，不能用于手机游戏中的排列。"}, {"text": "排名", "is_correct": true, "explanation": "排名指在榜单中的位置，符合手机游戏的语境。"}], "explanations": {"温度": "语义：温度不是玩家在游戏中可排列的属性，句子说不通。", "作息": "搭配：“作息”指人的起居习惯，与游戏里的排列次序不搭。", "体温": "语义：体温没有先后次序，不能用于手机游戏中的排列。", "排名": "排名指在榜单中的位置，符合手机游戏的语境。"}, "sentence_index": 6, "correct_answer": "排名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛结束后，排名定在了周六。", "explanation": "这里应该用〈日期〉。排名是位置，不能“定在”某一天。"}, {"text": "这盆花的排名很香。", "explanation": "这里应该用有香气的事物作主语，如〈饭菜〉。排名表示位置，没有气味，不能说“很香”。"}, {"text": "他的排名会游泳。", "explanation": "这里应该用〈人〉作主语。“会游泳”要求主语能游泳，排名不是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23e663ea-358d-453a-a4ef-eb088c2e2768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23736, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天看到了他的一只排名。", "corrected_sentence": "我昨天看到了他的一个排名。", "error_description": "量词用错：“排名”应搭配量词“个”，不能用“只”。“只”用于动物或成对物品中的单个，不能修饰抽象的“排名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23e663ea-358d-453a-a4ef-eb088c2e2768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23736, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的排名在一位。", "corrected_sentence": "他的排名在第一位。", "error_description": "错误形式“在一位”，正确形式“在第一位”。表示名次的序数要带“第”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23e663ea-358d-453a-a4ef-eb088c2e2768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23742, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23742, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23742, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西给别人看，让大家看到。", "primary_collocate": null, "pronunciation": "zhǎn xiàn", "ipa": "tʂan˨˩ ɕi̯ɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这次展览把艺术家的独特风格完整展现给观众。", "target_word": "展现", "complexity_tier": "T3", "furigana": "zhè cì zhǎn lǎn bǎ yì shù jiā de dú tè fēng gé wán zhěng zhǎn xiàn gěi guān zhòng", "sentence_source": "generated"}, {"text": "新车发布会上，厂商完整展现了这款车的设计理念。", "target_word": "展现", "complexity_tier": "T3", "furigana": "xīn chē fā bù huì shàng, chǎng shāng wán zhěng zhǎn xiàn le zhè kuǎn chē de shè jì lǐ niàn", "sentence_source": "generated"}, {"text": "舞台的幕布一拉开，展现在观众面前的是一座花园。", "target_word": "展现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位设计师在秀场上展现了新品的独特风格。", "target_word": "展现", "complexity_tier": "T3", "furigana": "zhè wèi shè jì shī zài xiù chǎng shàng zhǎn xiàn le xīn pǐn de dú tè fēng gé", "sentence_source": "generated"}, {"text": "展览会上，策展人把城市的历史风貌展现给参观者。", "target_word": "展现", "complexity_tier": "T3", "furigana": "zhǎn lǎn huì shàng, cè zhǎn rén bǎ chéng shì de lì shǐ fēng mào zhǎn xiàn gěi cān guān zhě", "sentence_source": "generated"}, {"text": "他的新招数终于展现出来，让大家眼前一亮。", "target_word": "展现", "complexity_tier": "T3", "furigana": "tā de xīn zhāo shù zhōng yú zhǎn xiàn chū lái, ràng dà jiā yǎn qián yí liàng", "sentence_source": "generated"}, {"text": "店员在柜台前把手机的新功能展现在客人面前。", "target_word": "展现", "complexity_tier": "T3", "furigana": "diàn yuán zài guì tái qián bǎ shǒu jī de xīn gōng néng zhǎn xiàn zài kè rén miàn qián", "sentence_source": "generated"}, {"text": "她在朋友面前展现了自己的绘画风格，大家都很赞赏。", "target_word": "展现", "complexity_tier": "T3", "furigana": "tā zài péng yǒu miàn qián zhǎn xiàn le zì jǐ de huì huà fēng gé, dà jiā dōu hěn zàn shǎng", "sentence_source": "generated"}, {"text": "窗帘一拉开，展现在眼前的是大海。", "target_word": "展现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在课堂上展现了自己的创意，老师很满意。", "target_word": "展现", "complexity_tier": "T3", "furigana": "hái zi men zài kè táng shàng zhǎn xiàn le zì jǐ de chuàng yì, lǎo shī hěn mǎn yì", "sentence_source": "generated"}], "morphological_forms": [{"form": "展现了", "label": "体标"}, {"form": "展现着", "label": "体标"}, {"form": "展现过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把具体的东西或抽象的风格、创意等摆出来、露出来或呈现出来，让大家看到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b13cb17d-02c1-4f79-bcfd-22a8dcf8b695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23742, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "展现", "is_correct": true, "explanation": "正确答案：展现（zhǎn xiàn），意思是把东西摆出来让大家看到。"}, {"text": "占线", "is_correct": false, "explanation": "zhàn（第四声）与 zhǎn 声调不同，意思是电话或线路被占用、忙线。"}, {"text": "战线", "is_correct": false, "explanation": "zhàn（第四声）与 zhǎn 声调不同，意思是作战的前沿阵地。"}, {"text": "产线", "is_correct": false, "explanation": "chǎn（第三声）与 zhǎn 声母不同（ch 与 zh），意思是生产线。"}], "explanations": {"展现": "正确答案：展现（zhǎn xiàn），意思是把东西摆出来让大家看到。", "占线": "zhàn（第四声）与 zhǎn 声调不同，意思是电话或线路被占用、忙线。", "战线": "zhàn（第四声）与 zhǎn 声调不同，意思是作战的前沿阵地。", "产线": "chǎn（第三声）与 zhǎn 声母不同（ch 与 zh），意思是生产线。"}, "sentence_index": null, "correct_answer": "展现"}, "level_3": {"options": [{"text": "展现", "is_correct": true, "explanation": "正确：展现表示把东西摆出来让观众看，与“风格”和“给观众”搭配。"}, {"text": "借给", "is_correct": false, "explanation": "语义：风格不是可以借出的物品，“借给观众”与句意不符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：修理的对象是器物，不能修理“风格”，也不与“给观众”搭配。"}, {"text": "购买", "is_correct": false, "explanation": "配价：购买的宾语是商品，不带与事“给观众”，“购买……给观众”不成立。"}], "explanations": {"展现": "正确：展现表示把东西摆出来让观众看，与“风格”和“给观众”搭配。", "借给": "语义：风格不是可以借出的物品，“借给观众”与句意不符。", "修理": "搭配：修理的对象是器物，不能修理“风格”，也不与“给观众”搭配。", "购买": "配价：购买的宾语是商品，不带与事“给观众”，“购买……给观众”不成立。"}, "sentence_index": 0, "correct_answer": "展现"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位设计师在秀场上展现了一次演讲。", "explanation": "这里应用“发表”。“展现”指把具体物品或作品摆出来让人看，演讲是一种活动，要说“发表”，不能用“展现”。"}, {"text": "这位设计师在秀场上展现了一顿饭。", "explanation": "这里应用“准备”。“展现”指把具体物品或作品摆出来让人看，做饭要说“准备”或“做”，不能用“展现”。"}, {"text": "这个月的销量展现了不少。", "explanation": "这里应用“增加”。“展现”用于把具体物品或作品摆出来让人看，销量的增减要用“增加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "展现", "is_correct": true, "explanation": "正确：展现表示把具体东西摆出来让人看，与“在客人面前”搭配。"}, {"text": "拆卸", "is_correct": false, "explanation": "搭配：“拆卸”的对象是有形器物，新功能不能被拆卸，句意不通。"}, {"text": "解说", "is_correct": false, "explanation": "配价：“解说”要求的对象是内容，“把新功能解说在客人面前”不成立。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎”的对象是有形的器物，功能不能被打碎。"}], "explanations": {"展现": "正确：展现表示把具体东西摆出来让人看，与“在客人面前”搭配。", "拆卸": "搭配：“拆卸”的对象是有形器物，新功能不能被拆卸，句意不通。", "解说": "配价：“解说”要求的对象是内容，“把新功能解说在客人面前”不成立。", "打碎": "搭配：“打碎”的对象是有形的器物，功能不能被打碎。"}, "sentence_index": 6, "correct_answer": "展现"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次改革展现了成本。", "explanation": "这里应用“降低”。“展现”用于把东西摆出来让人看，成本的变化要用“降低”。"}, {"text": "这次会议展现了一个小时。", "explanation": "这里应用“延长”。“展现”不指时间的增加，会议时长的变化要用“延长”。"}, {"text": "孩子们的成绩展现了很多。", "explanation": "这里应用“增长”。“展现”不用于成绩等数量的增加，要用“增长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "馆方这批古代陶器完整展现出来。", "corrected_sentence": "馆方把这批古代陶器完整展现出来。", "error_description": "错误形式：“馆方这批古代陶器完整展现出来”。正确形式：“馆方把这批古代陶器完整展现出来”。宾语“这批古代陶器”前须用“把”提到动词前，直接并列则不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把这张地图完整展现全班同学。", "corrected_sentence": "老师把这张地图完整展现给全班同学。", "error_description": "错误形式：“展现全班同学”。正确形式：“展现给全班同学”。“展现”引出接受对象要用“给”，漏掉“给”则不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
