INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23744, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家都很尊重和佩服这个人。", "primary_collocate": null, "pronunciation": "shēng wàng", "ipa": "ʂɤŋ˥ wɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "王老师在学校里声望很高。", "target_word": "声望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做了很多好事，在城里很有声望。", "target_word": "声望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家的声望越来越高。", "target_word": "声望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的声望很高，大家都听他的。", "target_word": "声望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们很尊重他，他在村里声望最高。", "target_word": "声望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她靠努力在行业里建立了声望。", "target_word": "声望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失去声望很容易，建立声望却很难。", "target_word": "声望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长是有声望的人，学生都佩服他。", "target_word": "声望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生的声望传到了很远的地方。", "target_word": "声望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用多年的好成绩换来了声望。", "target_word": "声望", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "声望", "label": "基本形式"}], "register": "中性", "sense_fingerprint": "大家尊重、佩服某人而形成的好名声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b13cb17d-02c1-4f79-bcfd-22a8dcf8b695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23744, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "声望", "is_correct": true, "explanation": "声望：指受人尊敬的好名声，在学校里可以很高。"}, {"text": "房价", "is_correct": false, "explanation": "搭配：房价是物价，不说“王老师在学校里房价很高”。"}, {"text": "票价", "is_correct": false, "explanation": "搭配：票价指车票或门票的价格，与人无关。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔指地面高度，不能用来说人的社会评价。"}], "explanations": {"声望": "声望：指受人尊敬的好名声，在学校里可以很高。", "房价": "搭配：房价是物价，不说“王老师在学校里房价很高”。", "票价": "搭配：票价指车票或门票的价格，与人无关。", "海拔": "语义：海拔指地面高度，不能用来说人的社会评价。"}, "sentence_index": 0, "correct_answer": "声望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只小猫的声望很高，全家人都很喜欢它。", "explanation": "这里应该用〈人气〉。声望指受人尊敬的名望，不用于形容小猫。"}, {"text": "今天的天气很好，声望也很高。", "explanation": "这里应该去掉〈声望〉。声望指受人尊敬的名望，不能用来形容天气。"}, {"text": "这座山的声望很高，每年都有很多人来爬。", "explanation": "这里应该用〈名气〉。声望指受人尊敬的名望，不用于形容山这样的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23744, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "声望", "is_correct": true, "explanation": "声望：指可以失去也可以建立的好名声，与前后句相合。"}, {"text": "血压", "is_correct": false, "explanation": "搭配：血压是生理指标，不能说“失去血压”或“建立血压”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不会因人的努力而失去或建立，句意不通。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：体积指物体的空间大小，不说“建立体积”。"}], "explanations": {"声望": "声望：指可以失去也可以建立的好名声，与前后句相合。", "血压": "搭配：血压是生理指标，不能说“失去血压”或“建立血压”。", "温度": "语义：温度不会因人的努力而失去或建立，句意不通。", "体积": "搭配：体积指物体的空间大小，不说“建立体积”。"}, "sentence_index": 6, "correct_answer": "声望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用多年的努力换来了一把声望。", "explanation": "这里应该用〈点〉。〈把〉用于有柄的物件，声望是抽象名词，可说“一点声望”。"}, {"text": "他用多年的努力换来了一根声望。", "explanation": "这里应该用〈点〉。〈根〉用于细长条的东西，声望是抽象名词，可说“一点声望”。"}, {"text": "他用多年的努力换来了一只声望。", "explanation": "这里应该用〈点〉。〈只〉用于成对物件之一或某些动物，声望是抽象名词，可说“一点声望”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在学校里声望高很，同学们都愿意向她请教。", "corrected_sentence": "她在学校里声望很高，同学们都愿意向她请教。", "error_description": "“很”要放在形容词前。应说“声望很高”，不能说“声望高很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23744, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在村里地声望很高，有事大家都找他。", "corrected_sentence": "他在村里的声望很高，有事大家都找他。", "error_description": "“声望”前的修饰语要用“的”，不能用“地”。应说“村里的声望”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23746, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合作", "is_correct": true, "explanation": "正确：“合作”与“对抗”意思相反，指双方共同配合。"}, {"text": "游泳", "is_correct": false, "explanation": "无关：“游泳”是另一类活动，与“对抗”没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "无关：“思考”是思维活动，与“对抗”没有反义关系。"}, {"text": "整理", "is_correct": false, "explanation": "无关：“整理”是整顿物品，与“对抗”没有反义关系。"}], "correct_answer": "合作", "explanations": {"合作": "正确：“合作”与“对抗”意思相反，指双方共同配合。", "游泳": "无关：“游泳”是另一类活动，与“对抗”没有反义关系。", "思考": "无关：“思考”是思维活动，与“对抗”没有反义关系。", "整理": "无关：“整理”是整顿物品，与“对抗”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
