INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23746, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两边互相抵抗。", "primary_collocate": null, "pronunciation": "duì kàng", "ipa": "tweɪ˥˩ kʰɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "两个队伍在比赛中互相对抗。", "target_word": "对抗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国军队在边境线上长期对抗。", "target_word": "对抗", "complexity_tier": "T3", "furigana": "liǎng guó jūn duì zài biān jìng xiàn shàng cháng qī duì kàng", "sentence_source": "generated"}, {"text": "孩子常常用沉默对抗父母。", "target_word": "对抗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们两家公司一直在市场上对抗。", "target_word": "对抗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两位选手在擂台上互相对抗。", "target_word": "对抗", "complexity_tier": "T3", "furigana": "liǎng wèi xuǎn shǒu zài léi tái shàng hù xiāng duì kàng", "sentence_source": "generated"}, {"text": "这两个国家已经对抗了很多年。", "target_word": "对抗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟总想和哥哥对抗，什么都不听。", "target_word": "对抗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两人在谈判桌上对抗，谁都不肯让步。", "target_word": "对抗", "complexity_tier": "T3", "furigana": "liǎng rén zài tán pàn zhuō shàng duì kàng shuí dōu bù kěn ràng bù", "sentence_source": "generated"}, {"text": "两个班的学生在球场上对抗着。", "target_word": "对抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方互相对抗，谁也不让谁。", "target_word": "对抗", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "对抗了", "label": "体标"}, {"form": "对抗着", "label": "体标"}, {"form": "对抗过", "label": "体标"}, {"form": "对抗赛", "label": "复合"}], "register": "中性", "sense_fingerprint": "双方互相抵抗、较量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b76edc4-0981-45f9-b40b-13826adb3d03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23746, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对抗", "is_correct": true, "explanation": "正确：“对抗”表示双方互相较量、抵抗，与“比赛”的语境相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与比赛的情境不符，“互相睡觉”句子不通。"}, {"text": "咳嗽", "is_correct": false, "explanation": "搭配：“咳嗽”是不及物动词，不能和“互相”一起带出动作对象。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与“比赛”无关，“互相吃饭”不合常理。"}], "explanations": {"对抗": "正确：“对抗”表示双方互相较量、抵抗，与“比赛”的语境相符。", "睡觉": "语义：“睡觉”与比赛的情境不符，“互相睡觉”句子不通。", "咳嗽": "搭配：“咳嗽”是不及物动词，不能和“互相”一起带出动作对象。", "吃饭": "语义：“吃饭”与“比赛”无关，“互相吃饭”不合常理。"}, "sentence_index": 0, "correct_answer": "对抗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两人在考试中对抗第一名。", "explanation": "这里应该用〈竞争〉。对抗指双方互相抵抗，争取第一名要用〈竞争〉。"}, {"text": "我们要互相对抗，共同完成任务。", "explanation": "这里应该用〈配合〉。对抗是双方互相抵抗，同一团队里的人要用〈配合〉。"}, {"text": "消防队员对抗被困的人。", "explanation": "这里应该用〈救援〉。对抗是双方抵抗，不能用来表示去帮助被困的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23746, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对抗", "is_correct": true, "explanation": "正确：“对抗”表示与哥哥互相抵抗，与“什么都不听”的语境相符。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“哭泣”不表示与哥哥抵抗，与“总想……什么都不听”的对抗语境不符。"}, {"text": "赶路", "is_correct": false, "explanation": "语义：“赶路”是赶往某处，与“总想……什么都不听”的对抗语境不符。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：“失眠”指睡不着，与“和哥哥”相争的意思无关。"}], "explanations": {"对抗": "正确：“对抗”表示与哥哥互相抵抗，与“什么都不听”的语境相符。", "哭泣": "语义：“哭泣”不表示与哥哥抵抗，与“总想……什么都不听”的对抗语境不符。", "赶路": "语义：“赶路”是赶往某处，与“总想……什么都不听”的对抗语境不符。", "失眠": "语义：“失眠”指睡不着，与“和哥哥”相争的意思无关。"}, "sentence_index": 6, "correct_answer": "对抗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵每天都在对抗百姓的安全。", "explanation": "这里应该用〈保护〉。对抗是双方抵抗，保护百姓的安全要用〈保护〉。"}, {"text": "运动员对抗世界纪录。", "explanation": "这里应该用〈挑战〉。纪录是要去超越的目标，对抗指双方互相抵抗，不能用于纪录。"}, {"text": "老师对抗学生的思考。", "explanation": "这里应该用〈启发〉。对抗指双方互相抵抗，老师激发学生思考要用〈启发〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23746, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两国的军队在边境上对抗了着。", "corrected_sentence": "两国的军队在边境上对抗着。", "error_description": "体标错误：“了”和“着”不能同时用在动词后面，表示动作持续只用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23746, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一张精彩的对抗赛。", "corrected_sentence": "这是一场精彩的对抗赛。", "error_description": "量词错误：比赛要用“场”，“张”用于平面的东西，不能用来量比赛。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
