INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23752, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人或东西做了多少帮助，可以数出来。", "primary_collocate": null, "pronunciation": "gòng xiàn dù", "ipa": "kʊŋ⁵¹ ɕjɛn⁵¹ tu⁵¹", "syllable_count": 3, "sentences": [{"text": "老板用表格记下每个人的贡献度。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的贡献度是百分之三十。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月，小王的贡献度排第一。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先算一算每个人的贡献度。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作做得多，贡献度就高。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对团队的贡献度很大。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁的贡献度最大，谁先拿奖品。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贡献度可以用分数来看。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们对每个人的贡献度都很清楚。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图显示了三个人的贡献度。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "所做帮助的多少，可以用数字计算", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6792c6-a92e-4e98-9b44-bbdd20737884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23752, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贡献度", "is_correct": true, "explanation": "正确。“记下每个人的贡献度”指记录每人所做帮助的多少，可以数出来，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能用来计算帮助的多少，表格里不会记录每人的“颜色”，句子不通。"}, {"text": "时速", "is_correct": false, "explanation": "语义：时速是速度，用于交通工具，不能用来衡量个人所做的帮助。"}, {"text": "颜值", "is_correct": false, "explanation": "体貌：颜值指外貌，不是用表格记录并计算出来的帮助量。"}], "explanations": {"贡献度": "正确。“记下每个人的贡献度”指记录每人所做帮助的多少，可以数出来，与句意相符。", "颜色": "语义：颜色不能用来计算帮助的多少，表格里不会记录每人的“颜色”，句子不通。", "时速": "语义：时速是速度，用于交通工具，不能用来衡量个人所做的帮助。", "颜值": "体貌：颜值指外貌，不是用表格记录并计算出来的帮助量。"}, "sentence_index": 0, "correct_answer": "贡献度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给大家提供了很多贡献度。", "explanation": "这里应该用〈帮助〉。“提供”搭配帮助、服务，贡献度表示帮助多少的程度，不能说“提供贡献度”。"}, {"text": "他立下了大贡献度。", "explanation": "这里应该用〈功劳〉。“立下”搭配功劳，贡献度是程度，不能说“立下大贡献度”。"}, {"text": "他在大会上做了一个贡献度。", "explanation": "这里应该用〈报告〉。“做”搭配报告、发言，“贡献度”表示程度，不能作“做”的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23752, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贡献度", "is_correct": true, "explanation": "正确。“谁的贡献度最大，谁先拿奖品”指按所做帮助的多少来奖励，与句意相符。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步不是可以计算的帮助量，也不能用“最大”来比较，与奖品的语境不符。"}, {"text": "血型", "is_correct": false, "explanation": "语义：血型是类别，没有大小之分，不能说“最大”，句子不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材通常说“好”或“高”，说“最大”不自然，且与拿奖品的语境不搭。"}], "explanations": {"贡献度": "正确。“谁的贡献度最大，谁先拿奖品”指按所做帮助的多少来奖励，与句意相符。", "脚步": "语义：脚步不是可以计算的帮助量，也不能用“最大”来比较，与奖品的语境不符。", "血型": "语义：血型是类别，没有大小之分，不能说“最大”，句子不通。", "身材": "体貌：身材通常说“好”或“高”，说“最大”不自然，且与拿奖品的语境不搭。"}, "sentence_index": 6, "correct_answer": "贡献度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一口气吃掉了一大碗贡献度。", "explanation": "这里应该用〈饭〉。“吃”搭配饭菜，“贡献度”是抽象的程度，不能被吃。"}, {"text": "他承受了很大贡献度。", "explanation": "这里应该用〈压力〉。“承受”搭配压力、痛苦，不能说“承受贡献度”。"}, {"text": "他在会议上发表了贡献度。", "explanation": "这里应该用〈意见〉。“发表”搭配意见、文章，贡献度表示程度，不能被发表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次项目中，他的贡献度很最高。", "corrected_sentence": "这次项目中，他的贡献度最高。", "error_description": "“很”和“最”都是程度副词，不能同时修饰“高”。应只用“最”，说“贡献度最高”，不能说“贡献度很最高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "团队里，每个人贡献度都要记清楚。", "corrected_sentence": "团队里，每个人的贡献度都要记清楚。", "error_description": "“每个人”作定语修饰“贡献度”，中间要加“的”。漏掉“的”应为“每个人的贡献度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a49d5b1-7f84-41de-86cb-4a1970ee0761') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
