INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23754, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "觉得某人或某物是好的、对的。", "primary_collocate": null, "pronunciation": "rèn kě", "ipa": "ɻən⁵¹ kʰɤ²¹⁴", "syllable_count": 2, "sentences": [{"text": "妈妈认可我选的专业。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我认可他说的话。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个想法，大家都认可。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师认可了我的答案。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顾客认可这个牌子的质量。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很少认可别人的做法。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还不太认可这个计划。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸认可过我的决定。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你认可这个价格吗？", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她认可朋友的意见，决定改一改。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "认可了", "label": "完成体"}, {"form": "认可过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "觉得某人或某物好、对而表示接受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6792c6-a92e-4e98-9b44-bbdd20737884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
